test('bank statement imports preserve exact balances and do not create financial operations',()=>{const {s,actor,input}=bankFixture(),before=structuredClone(s);input.importedBy='Inventado';input.lines[0].treasuryMoveIds=['in-one'];const b=importBankStatement(s,input,actor);assert.equal(b.importedBy,actor.name);assert.deepEqual(b.lines[0].treasuryMoveIds,[]);assert.equal(b.status,'Activo');assert.deepEqual(s.treasuryMoves,before.treasuryMoves);assert.deepEqual(s.entries,before.entries);assert.deepEqual(s.documents,before.documents);validateState(s)})
test('bank reconciliation groups same-sign movements with exact cents and conserves financial balances',()=>{const {s,actor,input}=bankFixture(),b=importBankStatement(s,input,actor),amounts=s.treasuryMoves.map(m=>m.amount);matchBankLine(s,b.id,b.lines[0].id,['in-one','in-two'],'Dos cobros acreditados juntos',actor);matchBankLine(s,b.id,b.lines[1].id,['out-one'],'',actor);assert.ok(s.treasuryMoves.every(m=>m.reconciled&&m.bankStatementLineId));assert.deepEqual(s.treasuryMoves.map(m=>m.amount),amounts);assert.equal(b.events[0].user,actor.name);assert.equal(s.entries.length,0);assert.equal(s.documents.length,0);assert.deepEqual(statementSummary(s,b),{ledger:800000,pendingBank:-10000,pendingLedger:0,difference:-10000,unexplained:0,matched:2});assert.equal(bankCandidates(s,b,b.lines[2]).length,0);validateState(s)})
test('bank reconciliation refuses wrong amounts, signs, repeated or already verified movements atomically',()=>{const {s,actor,input}=bankFixture(),b=importBankStatement(s,input,actor);for(const ids of [[],['in-one'],['in-one','in-one'],['in-one','out-one'],['missing']]){const before=structuredClone(s);assert.throws(()=>matchBankLine(s,b.id,b.lines[0].id,ids,'',actor));assert.deepEqual(s,before)}manualReconciliation(s,'in-one',true);assert.throws(()=>matchBankLine(s,b.id,b.lines[0].id,['in-one','in-two'],'',actor),/pendientes/);manualReconciliation(s,'in-one',false);matchBankLine(s,b.id,b.lines[0].id,['in-one','in-two'],'',actor);assert.throws(()=>manualReconciliation(s,'in-one',false),/extracto/);assert.throws(()=>matchBankLine(s,b.id,b.lines[0].id,['in-one','in-two'],'',actor),/fila pendiente/);assert.throws(()=>matchBankLine(s,b.id,b.lines[1].id,['out-one'],'',{...actor,role:'Depósito'}),/perfil/);validateState(s)})
test('bank statement import rejects invalid periods, arithmetic, duplicate rows and overlapping statements',()=>{const {s,actor,input}=bankFixture();for(const change of [{closing:input.closing+1},{treasuryId:'caja-principal'},{from:'2026-02-30'},{to:'2027-01-01'},{lines:[]},{lines:[{...input.lines[0],amount:0}]},{lines:[input.lines[0],input.lines[0]]}]){const before=structuredClone(s);assert.throws(()=>importBankStatement(s,{...input,...change},actor));assert.deepEqual(s,before)}importBankStatement(s,input,actor);assert.throws(()=>importBankStatement(s,input,actor),/superpone/);assert.throws(()=>importBankStatement(s,{...input,from:'2026-10-09',to:'2026-10-09',lines:input.lines.map(l=>({...l,date:'2026-10-09'}))},actor),/referencia/);const other={...s.masters.treasury.find(a=>a.id==='banco-demo'),id:'another-bank',name:'Otra cuenta'};s.masters.treasury.push(other);importBankStatement(s,{...input,treasuryId:other.id},actor);validateState(s)})
test('bank reconciliation reversal retains history and cancellation permits reviewed replacement',()=>{const {s,actor,input}=bankFixture(),b=importBankStatement(s,input,actor);matchBankLine(s,b.id,b.lines[0].id,['in-one','in-two'],'',actor);assert.throws(()=>cancelBankStatement(s,b.id,'Archivo incorrecto',actor),/Desvinculá/);assert.throws(()=>unmatchBankLine(s,b.id,b.lines[0].id,'',actor),/motivo/);unmatchBankLine(s,b.id,b.lines[0].id,'Revisión de evidencia',actor);assert.ok(s.treasuryMoves.every(m=>!m.reconciled&&!m.bankStatementLineId));cancelBankStatement(s,b.id,'Reemplazo de archivo',actor);assert.equal(b.status,'Anulado');assert.deepEqual(b.events.map(e=>e.action),['Vincular','Desvincular','Anular']);const replacement=importBankStatement(s,input,actor);assert.notEqual(replacement.id,b.id);assert.throws(()=>matchBankLine(s,b.id,b.lines[0].id,['in-one','in-two'],'',actor));validateState(s)})
test('bank backup validation protects links and balances and accepts legacy unlinked bases',()=>{const {s,actor,input}=bankFixture(),b=importBankStatement(s,input,actor);matchBankLine(s,b.id,b.lines[0].id,['in-one','in-two'],'',actor);validateState(JSON.parse(JSON.stringify(s)));for(const mutate of [copy=>delete copy.bankStatements,copy=>copy.bankStatements[0].closing++,copy=>copy.bankStatements[0].lines[0].amount++,copy=>copy.treasuryMoves[0].date='2026-02-30',copy=>copy.treasuryMoves[0].reconciled='yes',copy=>copy.treasuryMoves[0].reconciled=false,copy=>copy.treasuryMoves[0].bankStatementLineId='lost',copy=>copy.bankStatements[0].status='Anulado',copy=>copy.bankStatements[0].lines[0].treasuryMoveIds.push('out-one')]){const copy=structuredClone(s);mutate(copy);assert.throws(()=>validateState(copy),/extracto|bancarios|vínculos/)}const old=fixture();delete old.bankStatements;validateState(old);assert.throws(()=>engine.saveMaster(s,'treasury',{...s.masters.treasury.find(t=>t.id==='banco-demo'),type:'Caja'},'Administración'),/conserva/);assert.throws(()=>validateState({...s,bankStatements:null}),/Extractos/)})
test('bank row parser preserves signed ARS cents and flags every malformed row without rounding extra decimals',()=>{const rows=[{Fecha:'2026-10-08',Referencia:'1',Descripcion:'Ingreso',Importe:'123,45'},{Fecha:'2026-10-08',Referencia:'2',Descripcion:'Egreso',Importe:'-67.89'},{Fecha:'2026-10-08',Referencia:'3',Descripcion:'No válido',Importe:'1.234'},{Fecha:'2026-02-30',Referencia:'4',Descripcion:'No válido',Importe:'10'},{Fecha:'2026-10-08',Referencia:'5',Descripcion:'No válido',Importe:'1.000,00'},{Fecha:'2026-10-08',Referencia:'6',Descripcion:'No válido',Importe:'0'}],p=parseStatementRows(rows);assert.deepEqual(p.lines.map(l=>l.amount),[12345,-6789]);assert.deepEqual(p.errors.map(e=>e.row),[4,5,6,7]);assert.equal(parseStatementRows([{...rows[0],Importe:'9007199254740992'}]).errors.length,1);assert.equal(parseStatementRows([{...rows[0],__columns:'5'}]).errors.length,1)})
