test('stock transfer commits paired movements between branches without commercial or financial changes',()=>{const {s,actor,input}=transferFixture();input.lines[1].quantity=2.125;const before=input.lines.map(l=>engine.stock(s,l.productId)),t=transferStock(s,input,actor);assert.equal(t.number,'INT-TR-00000001');assert.equal(t.responsible,actor.name);assert.equal(t.toBranchId,'norte');assert.equal(s.stockMoves.filter(m=>m.transferId===t.id).length,4);input.lines.forEach((l,i)=>{assert.equal(engine.stock(s,l.productId),before[i]);assert.equal(engine.stock(s,l.productId,'norte-deposito'),l.quantity);assert.equal(engine.stock(s,l.productId,'principal'),before[i]-l.quantity)});assert.equal(s.documents.length,0);assert.equal(s.entries.length,0);assert.equal(s.treasuryMoves.length,0);validateState(JSON.parse(JSON.stringify(s)))})
test('stock transfer validates locations, physical products, quantities, reasons, periods and actor permissions',()=>{const {s,actor,input}=transferFixture();for(const change of [{toId:'principal'},{toId:'missing'},{reason:''},{lines:[]},{lines:[input.lines[0],input.lines[0]]}])assert.throws(()=>transferStock(s,{...input,...change},actor));for(const quantity of [0,-1,NaN,Infinity,1000001,0.0000001,1.0000001])assert.throws(()=>transferStock(s,{...input,lines:[{...input.lines[0],quantity}]},actor),/cantidad/);const service={...s.products[2],id:'service-test',sku:'SERVICE',kind:'Servicio'};s.products.push(service);assert.throws(()=>transferStock(s,{...input,lines:[{productId:service.id,quantity:1}]},actor),/servicios/);s.masters.branches.find(b=>b.id==='norte').active=false;assert.throws(()=>transferStock(s,input,actor),/activas/);s.masters.branches.find(b=>b.id==='norte').active=true;assert.throws(()=>transferStock(s,input,{...actor,role:'Producción'}),/perfil/);assert.throws(()=>transferStock(s,input,{...actor,role:'Personalizado',permissions:[]}),/perfil/);s.settings.closedUntil=today();assert.throws(()=>transferStock(s,input,actor),/cerrado/);assert.equal(s.stockTransfers.length,0)})
test('stock transfer shortage on a later line leaves both locations and transfer registry unchanged',()=>{const {s,actor,input}=transferFixture(),before=structuredClone(s);assert.throws(()=>transferStock(s,{...input,lines:[input.lines[0],{...input.lines[1],quantity:21}]},actor),/insuficiente/);assert.deepEqual(s,before)})
test('stock transfer does not use future receipts and cannot invalidate subsequent dated outflows',()=>{const {s,actor,input}=transferFixture();s.settings.exerciseStart='2026-01-01';s.settings.exerciseEnd='2026-12-31';s.stockMoves.forEach(m=>m.date='2026-10-07');assert.throws(()=>transferStock(s,{...input,date:'2026-10-06'},actor),/insuficiente/);const l=input.lines[0];s.stockMoves.push({id:uid(),productId:l.productId,quantity:-36,depositId:'principal',branchId:'central',date:'2026-10-08',reason:'Salida posterior',documentId:''});assert.throws(()=>transferStock(s,{...input,date:'2026-10-07',lines:[l]},actor),/2026-10-08/);transferStock(s,{...input,date:'2026-10-07',lines:[{...l,quantity:3}]},actor);assert.equal(engine.stock(s,l.productId,'principal'),1)})
test('stock transfer allows explicitly configured negative stock and preserves historic names',()=>{const {s,actor,input}=transferFixture(),l={...input.lines[0],quantity:50};s.products.find(p=>p.id===l.productId).negative=true;const t=transferStock(s,{...input,lines:[l]},actor);assert.equal(engine.stock(s,l.productId,'principal'),-10);s.products.find(p=>p.id===l.productId).name='Nombre actualizado';s.masters.deposits.find(d=>d.id===input.toId).name='Destino actualizado';assert.equal(t.toName,'Depósito norte');assert.notEqual(t.lines[0].description,'Nombre actualizado');validateState(s)})
test('stock transfer backups reject missing or inconsistent paired moves and support prior bases',()=>{const {s,actor,input}=transferFixture(),old=structuredClone(s);delete old.stockTransfers;validateState(old);assert.throws(()=>validateState({...old,stockTransfers:null}),/traslados/);const t=transferStock(s,input,actor);for(const modify of [copy=>copy.stockMoves.pop(),copy=>copy.stockMoves.at(-1).quantity++,copy=>copy.stockTransfers[0].lines[0].quantity++,copy=>copy.stockTransfers[0].date='2026-02-30',copy=>copy.stockTransfers.push(structuredClone(copy.stockTransfers[0])),copy=>delete copy.stockTransfers]){const copy=structuredClone(s);modify(copy);assert.throws(()=>validateState(copy),/traslado|cantidades|Identificadores/)}const back=transferStock(s,{...input,fromId:input.toId,toId:input.fromId,reason:`Devolución de ${t.number}`},actor);assert.equal(back.number,'INT-TR-00000002');assert.equal(engine.stock(s,input.lines[0].productId,'principal'),40);validateState(s)})
function fixture(){const s=initialState();loadTextileDemo(s);return s}
function input(s,kind='factura',overrides={}){const p=s.parties.find(p=>p.side==='cliente'),product=s.products.find(p=>p.sku==='REM-M-NEG');return {kind,side:'cliente',letter:'A',date:today(),due:today(),branchId:'central',partyId:p.id,lines:[{productId:product.id,description:product.name,quantity:2,unit:'Unidad',price:10000,tax:'21',discount:0}],payments:[],perceptions:0,sourceId:'',allocations:[],observations:'Prueba',responsible:'Administrador',costCenter:'',depositId:'principal',official:false,valued:true,seller:p.seller,priceList:'general',...overrides}}
const post=(s,kind='factura',overrides={})=>engine.createDocument(s,input(s,kind,overrides),'Administrador General')
function balanced(s){for(const e of s.entries)assert.equal(e.lines.reduce((n,l)=>n+l.debit-l.credit,0),0)}
test('CUIT validates checksum and rejects malformed values',()=>{assert.ok(engine.validCuit('20-12345678-6'));assert.ok(engine.validCuit('30712345671'));assert.ok(!engine.validCuit('20123456789'));assert.ok(!engine.validCuit('00000000000'))})
test('A adds per-line IVA, B extracts contained IVA, C and X do not discriminate',()=>{const l={price:10000,quantity:2,discount:0,tax:'21'};assert.deepEqual(engine.lineTotals(l,'A'),{net:20000,vat:4200,total:24200});assert.deepEqual(engine.lineTotals({...l,price:12100},'B'),{net:20000,vat:4200,total:24200});assert.equal(engine.lineTotals(l,'C').vat,0);assert.equal(engine.lineTotals(l,'X').vat,0)})
test('mixed VAT rates and discounts reconcile to cents',()=>{const ls=[{price:10500,quantity:1,discount:0,tax:'10.5'},{price:10000,quantity:1,discount:10,tax:'27'}];const t=engine.totals(ls,'A',123);assert.equal(t.net+t.vat+t.perceptions,t.total);assert.equal(t.total,23156)})
test('fiscal letter depends on emitter and receptor',()=>{assert.equal(engine.suggestedLetter('Responsable Inscripto','Responsable Monotributo'),'A');assert.equal(engine.suggestedLetter('Responsable Monotributo','Responsable Inscripto'),'C');assert.equal(engine.suggestedLetter('Responsable Inscripto','Consumidor Final'),'B')})
test('invoice creates receivable and balanced journal without stock movement',()=>{const s=fixture(),p=s.products[2],before=engine.stock(s,p.id);const d=post(s);assert.equal(engine.partyBalance(s,d.partyId),24200);assert.equal(engine.stock(s,p.id),before);balanced(s)})
