test('combo price is allocated to cents with mixed IVA and consistent A/B/C/X totals',()=>{const {s,combo}=comboFixture(100.01),p=s.products.find(p=>p.sku==='PANT-42-AZ');p.tax='10.5';const a=expandCombo(s,combo.id,3,'A',10),b=expandCombo(s,combo.id,3,'B',10);assert.equal(engine.totals(a,'A').net,27003);assert.deepEqual(engine.totals(a,'A'),engine.totals(b,'B'));for(const letter of ['C','X']){const lines=expandCombo(s,combo.id,3,letter,10);assert.equal(engine.totals(lines,letter).total,27003);assert.equal(engine.totals(lines,letter).vat,0)}assert.ok(a.every(l=>Number.isSafeInteger(l.price)));assert.equal(a[0].quantity,6);assert.equal(a[1].quantity,3);assert.throws(()=>expandCombo(s,combo.id,1.5,'A'),/entera/)})
test('combo merging preserves quantities and assigned amounts without repeated SKU',()=>{const {s,combo}=comboFixture(50000.01),one=expandCombo(s,combo.id,1,'A'),another=expandCombo(s,combo.id,2,'A'),combined=mergeComboLines(one,another,'A');assert.equal(combined.length,2);assert.equal(combined[0].quantity,6);assert.equal(engine.totals(combined,'A').net,15000003);assert.ok(combined.every(l=>l.discount>=0&&l.discount<=100));assert.throws(()=>mergeComboLines([{...one[0],tax:'27'}],another,'A'),/alícuota/);const converted=convertLinePrices(combined,'A','B');assert.deepEqual(engine.totals(converted,'B'),engine.totals(combined,'A'));assert.deepEqual(engine.totals(convertLinePrices(converted,'B','A'),'A'),engine.totals(combined,'A'))})
