function costingFixture(){const s=fixture();for(const m of s.stockMoves)m.date='2026-10-01';const actor={userId:'admin',name:'Contadora de prueba',role:'Administrador General',permissions:[]};prepareInventoryAccounts(s,actor);const accounts=inventoryAccountDefaults(s),opening=inventoryOpeningBalances(s,'2026-10-01').map(b=>({productId:b.productId,depositId:b.depositId,quantity:b.quantity,value:Math.round(b.quantity*1000)})),base={date:'2026-10-01',reference:'Apertura',accounts,opening};return {s,actor,accounts,base}}
// Material-only legacy regression lots explicitly review zero additional conversion in their synthetic scenario.
function postCosts(s,input,actor){const pending=productionCosts.productionOrdersForCost(s,input.date,s.inventoryCostBatches?.at(-1)?.date||'').filter(id=>!s.productionCosts?.some(r=>r.date<=input.date&&r.orders.includes(id)));for(const branchId of [...new Set(pending.map(id=>s.masters.production.find(o=>o.id===id).branchId))]){const cost={from:input.date,to:input.date,date:input.date,branchId,wipAccountId:input.accounts.wip,reference:`Conversión cero sintética ${s.productionCosts?.length||0}`,reason:'El escenario de regresión anterior contiene sólo materiales, sin gastos adicionales de conversión.',orders:pending.filter(id=>s.masters.production.find(o=>o.id===id).branchId===branchId),pools:[],zeroReason:'Ausencia explícita de mano de obra, servicios y cargas adicionales en esta prueba de materiales.',completeConfirmed:true,currencyConfirmed:true,inefficiencyConfirmed:true};productionCosts.postProductionCost(s,{...cost,review:productionCosts.productionCostReview(productionCosts.previewProductionCost(s,cost))},actor)}const preview=previewInventoryCost(s,input,s.inventoryCostBatches?.at(-1));return postInventoryCost(s,{...input,review:inventoryCostReview(preview)},actor)}
function receivedPurchase(s,quantity,price,date='2026-10-02',overrides={}){const supplier=s.parties.find(p=>p.side==='proveedor'),product=s.products.find(p=>p.sku==='REM-M-NEG'),document=input(s,'remito',{side:'proveedor',partyId:supplier.id,letter:'A',date,due:date,lines:[{productId:product.id,description:product.name,quantity,unit:product.unit,price,tax:'21',discount:0}],...overrides});const remit=engine.createDocument(s,document,'Administración'),invoice=engine.createDocument(s,{...document,kind:'factura',sourceId:remit.id},'Administración');return {remit,invoice,product}}
test('inventory opening uses reviewed total values, creates balanced entries and leaves stock and commercial balances intact',()=>{const {s,actor,base}=costingFixture(),before=structuredClone(s);const batch=postCosts(s,base,actor);assert.equal(batch.method,'CPP');assert.equal(batch.responsible,actor.name);assert.equal(batch.balances.reduce((n,b)=>n+b.value,0),60000);assert.deepEqual(s.stockMoves,before.stockMoves);assert.deepEqual(s.documents,before.documents);assert.equal(batch.entryIds.length,1);assert.equal(s.entries.at(-1).lines.reduce((n,l)=>n+l.debit-l.credit,0),0);validateState(JSON.parse(JSON.stringify(s)));assert.throws(()=>postCosts(s,base,actor),/posterior|referencia/)})
test('CPP purchase and sale costs reconcile exact cents and reclassify purchases using the original account after mapping edits',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {product}=receivedPurchase(s,10,2000);s.settings.accountMap.purchases='5.2';engine.createDocument(s,input(s,'remito',{date:'2026-10-03',due:'2026-10-03',lines:[{productId:product.id,description:product.name,quantity:5,unit:product.unit,price:10000,tax:'21',discount:0}]}),'Administración');const b=postCosts(s,{date:'2026-10-03',reference:'Costo del período',accounts},actor);assert.equal(b.rows.find(r=>r.kind==='Compra').counterpart,'5.1');assert.equal(b.rows.find(r=>r.kind==='Venta').value,6000);assert.equal(b.balances.find(r=>r.productId===product.id).quantity,45);assert.equal(b.balances.find(r=>r.productId===product.id).value,54000);assert.equal(s.entries.find(e=>e.inventoryBatchId===b.id).lines.find(l=>l.accountId==='5.1').credit,20000);validateState(s);const remaining=45;engine.adjustStock(s,'Administrador General',product.id,'principal',-remaining,'Salida restante','2026-10-04');const c=postCosts(s,{date:'2026-10-04',reference:'Agota stock',accounts},actor);assert.equal(c.balances.find(r=>r.productId===product.id).value,0);assert.equal(c.balances.find(r=>r.productId===product.id).quantity,0);validateState(s)})
test('CPP fractional quantities and zero costs exhaust all cents without retaining phantom value',()=>{const {s,actor,base,accounts}=costingFixture(),product=s.products[0];s.stockMoves=[{...s.stockMoves[0],productId:product.id,quantity:0.3}];base.opening=[{productId:product.id,depositId:'principal',quantity:0.3,value:1}];postCosts(s,base,actor);for(const date of ['2026-10-02','2026-10-03','2026-10-04'])engine.adjustStock(s,'Administrador General',product.id,'principal',-0.1,'Fracción',date);const b=postCosts(s,{date:'2026-10-04',reference:'Fracciones',accounts},actor);assert.deepEqual(b.rows.map(r=>r.value),[0,1,0]);assert.equal(b.balances[0].value,0);assert.equal(b.balances[0].quantity,0);validateState(s)})
test('stock transfers preserve CPP across deposits and branches with zero company transit balance',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);s.masters.branches.push({id:'otra',name:'Otra sucursal',active:true,point:'2'});s.masters.deposits.push({id:'destino',name:'Otro depósito',branchId:'otra'});const p=s.products.find(p=>p.sku==='REM-M-NEG');transferStock(s,{date:'2026-10-02',fromId:'principal',toId:'destino',reason:'Costo conservado',lines:[{productId:p.id,quantity:3}]},actor);const b=postCosts(s,{date:'2026-10-02',reference:'Traslado valorizado',accounts},actor);assert.deepEqual(b.rows.map(r=>r.value),[3000,3000]);assert.equal(b.balances.find(r=>r.depositId==='destino').value,3000);assert.equal(s.entries.filter(e=>e.inventoryBatchId===b.id).flatMap(e=>e.lines).filter(l=>l.accountId===accounts.transit).reduce((n,l)=>n+l.debit-l.credit,0),0);assert.equal(b.entryIds.length,2);validateState(s)})
test('manufacturing capitalizes the exact CPP materials without using editable product reference costs',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const raw=s.products.find(p=>p.sku==='REM-M-NEG'),finished=s.products.find(p=>p.sku==='PANT-42-AZ');raw.cost=99999;s.masters.production.push({id:'cost-order',name:'Lote valorizado',branchId:'central',productId:finished.id,quantity:2,start:'2026-10-02',end:'2026-10-02',status:'Planificada'});s.masters.materials.push({id:'cost-material',name:'Insumo',orderId:'cost-order',productId:raw.id,quantity:3,depositId:'principal',unit:raw.unit});finishProduction(s,'cost-order','principal','2026-10-02','Producción');const b=postCosts(s,{date:'2026-10-02',reference:'Fabricación valorizada',accounts},actor);assert.deepEqual(b.rows.map(r=>[r.kind,r.value]),[['Consumo',3000],['Fabricación',3000]]);assert.equal(b.balances.find(r=>r.productId===finished.id).value,23000);assert.equal(s.entries.filter(e=>e.inventoryBatchId===b.id).flatMap(e=>e.lines).filter(l=>l.accountId===accounts.wip).reduce((n,l)=>n+l.debit-l.credit,0),0);validateState(s)})
test('cost posting rejects absent invoices, future invoices, unknown inflows and a stale or missing review atomically',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const supplier=s.parties.find(p=>p.side==='proveedor');const remit=engine.createDocument(s,input(s,'remito',{side:'proveedor',partyId:supplier.id,date:'2026-10-02',due:'2026-10-02'}),'Administración');const close={date:'2026-10-02',reference:'No listo',accounts};let before=structuredClone(s);assert.throws(()=>previewInventoryCost(s,close,s.inventoryCostBatches.at(-1)),/factura/);assert.deepEqual(s,before);engine.createDocument(s,{...remit,kind:'factura',date:'2026-10-03',due:'2026-10-03',sourceId:remit.id},'Administración');assert.throws(()=>previewInventoryCost(s,close,s.inventoryCostBatches.at(-1)),/factura/);const inputClose={...close,date:'2026-10-03'},preview=previewInventoryCost(s,inputClose,s.inventoryCostBatches.at(-1));assert.throws(()=>postInventoryCost(s,inputClose,actor),/revisión/);engine.adjustStock(s,'Administrador General',s.products.find(p=>p.sku==='REM-M-NEG').id,'principal',-1,'Ajuste revisable','2026-10-03');before=structuredClone(s);assert.throws(()=>postInventoryCost(s,{...inputClose,review:inventoryCostReview(preview)},actor),/revisión/);assert.deepEqual(s,before);engine.adjustStock(s,'Administrador General',s.products[0].id,'principal',1,'Ingreso sin costo','2026-10-04');assert.throws(()=>previewInventoryCost(s,{...close,date:'2026-10-04'},s.inventoryCostBatches.at(-1)),/costo documentado/)})
test('opening refuses negative balances, duplicate pools, invalid cents, preexisting inventory journals and unauthorized operators',()=>{const {s,actor,base,accounts}=costingFixture();for(const opening of [[],[base.opening[0],base.opening[0]],[{...base.opening[0],value:0.001},base.opening[1]],[{...base.opening[0],quantity:999},base.opening[1]]])assert.throws(()=>postCosts(s,{...base,opening},actor));assert.throws(()=>postCosts(s,base,{...actor,role:'Depósito'}),/perfil/);assert.throws(()=>prepareInventoryAccounts(s,{...actor,role:'Administración'}),/Administrador/);s.entries.push({id:'existing',date:base.date,concept:'Previo',branchId:'central',documentId:'',lines:[{accountId:accounts.inventory,debit:100,credit:0},{accountId:accounts.opening,debit:0,credit:100}]});assert.throws(()=>postCosts(s,base,actor),/ya tiene asientos/);const f=costingFixture();f.s.stockMoves[0].quantity=-1;f.base.opening=inventoryOpeningBalances(f.s,f.base.date).map(b=>({...b,value:1}));assert.throws(()=>postCosts(f.s,f.base,f.actor),/negativas/)})
