test('non-creditable purchase VAT is capitalized once and services remain in the original purchase expense',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);s.settings.iva='Responsable Monotributo';const article=s.products.find(p=>p.sku==='REM-M-NEG'),service={...article,id:'cost-service',sku:'COST-SERV',name:'Servicio de compra',kind:'Servicio',parent:''};engine.saveProduct(s,service);const {product}=receivedPurchase(s,10,2000,'2026-10-02',{lines:[{productId:article.id,description:article.name,quantity:10,unit:article.unit,price:2000,tax:'21',discount:0},{productId:service.id,description:service.name,quantity:1,unit:service.unit,price:1000,tax:'21',discount:0}]});const b=postCosts(s,{date:'2026-10-02',reference:'IVA costo',accounts},actor);assert.equal(b.rows[0].value,24200);assert.equal(b.balances.find(b=>b.productId===product.id).value,64200);assert.equal(s.entries.at(-1).lines.find(l=>l.accountId==='5.1').credit,24200);assert.equal(s.entries.flatMap(e=>e.lines).filter(l=>l.accountId==='5.1').reduce((n,l)=>n+l.debit-l.credit,0),1210);validateState(s)})
