test('later purchase credits recost previous sales, preserve their journal and correct only the current cutoff',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {invoice,product}=receivedPurchase(s,10,2000);engine.createDocument(s,input(s,'remito',{date:'2026-10-03',due:'2026-10-03',lines:[{...invoice.lines[0],quantity:5}]}),'Administración');const old=postCosts(s,{date:'2026-10-03',reference:'Antes de nota',accounts},actor),oldEntries=structuredClone(s.entries.filter(e=>e.inventoryBatchId===old.id));const note=purchaseNote(s,invoice,'credito',2000);validateState(s);const b=postCosts(s,{date:'2026-10-04',reference:'Corrección NC',accounts},actor);assert.equal(b.costVersion,5);assert.equal(b.sourceMoves.length,0);assert.equal(b.balances.find(b=>b.productId===product.id).value,52200);assert.equal(b.corrections[0].noteId,note.id);assert.equal(b.corrections[0].amount,-2000);assert.deepEqual(s.entries.filter(e=>e.inventoryBatchId===old.id),oldEntries);const j=s.entries.find(e=>e.inventoryBatchId===b.id);assert.equal(j.date,'2026-10-04');assert.equal(j.lines.find(l=>l.accountId===accounts.inventory).credit,1800);assert.equal(j.lines.find(l=>l.accountId===accounts.cogs).credit,200);assert.equal(j.lines.find(l=>l.accountId==='5.1').debit,2000);validateState(JSON.parse(JSON.stringify(s)));const c=postCosts(s,{date:'2026-10-05',reference:'Sin duplicación',accounts},actor);assert.equal(c.entryIds.length,0);assert.deepEqual(c.corrections,[]);assert.equal(c.balances.find(b=>b.productId===product.id).value,52200);validateState(s)})
test('same-period debit and credit notes use their original expense accounts and preserve exact net journals',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {invoice,product}=receivedPurchase(s,10,2000);s.settings.accountMap.purchases='5.2';purchaseNote(s,invoice,'debito',1000,'2026-10-03');purchaseNote(s,invoice,'credito',2000,'2026-10-04');const b=postCosts(s,{date:'2026-10-04',reference:'Dos notas',accounts},actor);assert.equal(b.rows[0].value,19000);assert.equal(b.balances.find(b=>b.productId===product.id).value,59000);assert.deepEqual(b.corrections.map(n=>n.amount),[1000,-2000]);const j=s.entries.find(e=>e.inventoryBatchId===b.id);assert.equal(j.lines.find(l=>l.accountId==='5.1').credit,20000);assert.equal(j.lines.find(l=>l.accountId==='5.2').debit,1000);assert.equal(j.lines.find(l=>l.accountId===accounts.inventory).debit,19000);validateState(s)})
test('purchase corrections follow cross-branch transfers and retain historical disposal accounts after mapping changes',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {invoice,product}=receivedPurchase(s,10,2000);s.masters.branches.push({id:'otra',name:'Otra',active:true,point:'2'});s.masters.deposits.push({id:'destino',name:'Destino',branchId:'otra'});transferStock(s,{date:'2026-10-03',fromId:'principal',toId:'destino',reason:'Distribución',lines:[{productId:product.id,quantity:25}]},actor);postCosts(s,{date:'2026-10-03',reference:'Antes del descuento',accounts},actor);purchaseNote(s,invoice,'credito',2000);const b=postCosts(s,{date:'2026-10-04',reference:'Descuento trasladado',accounts:{...accounts,cogs:'5.2'}},actor);assert.equal(b.balances.find(b=>b.productId===product.id&&b.depositId==='principal').value,29000);assert.equal(b.balances.find(b=>b.depositId==='destino').value,29000);const js=s.entries.filter(e=>e.inventoryBatchId===b.id);assert.equal(js.length,2);assert.equal(js.flatMap(e=>e.lines).filter(l=>l.accountId===accounts.transit).reduce((n,l)=>n+l.debit-l.credit,0),0);validateState(s)})
test('purchase corrections propagate into manufactured stock and its past sales with no changes in quantities',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {invoice,product:raw}=receivedPurchase(s,10,2000),finished=s.products.find(p=>p.sku==='PANT-42-AZ');s.masters.production.push({id:'note-order',name:'Lote',branchId:'central',productId:finished.id,quantity:10,start:'2026-10-03',end:'2026-10-03',status:'Planificada'});s.masters.materials.push({id:'note-material',name:'Insumo',orderId:'note-order',productId:raw.id,quantity:25,depositId:'principal',unit:raw.unit});finishProduction(s,'note-order','principal','2026-10-03','Producción');engine.createDocument(s,input(s,'remito',{date:'2026-10-03',due:'2026-10-03',lines:[{...invoice.lines[0],productId:finished.id,quantity:15}]}),'Administración');postCosts(s,{date:'2026-10-03',reference:'Lote vendido',accounts},actor);const moves=structuredClone(s.stockMoves);purchaseNote(s,invoice,'credito',2000);const b=postCosts(s,{date:'2026-10-04',reference:'Descuento de materiales',accounts},actor);assert.equal(b.balances.find(b=>b.productId===raw.id).value,29000);assert.equal(b.balances.find(b=>b.productId===finished.id).value,24500);const j=s.entries.find(e=>e.inventoryBatchId===b.id);assert.equal(j.lines.find(l=>l.accountId===accounts.cogs).credit,500);assert.equal(j.lines.find(l=>l.accountId===accounts.inventory).credit,1500);assert.deepEqual(s.stockMoves,moves);validateState(s)})
test('purchase note review rejects stale notes, tampered corrections and backdated changes to conserved cutoffs',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {invoice}=receivedPurchase(s,10,2000);postCosts(s,{date:'2026-10-02',reference:'Compra previa',accounts},actor);const close={date:'2026-10-04',reference:'Notas',accounts},p=previewInventoryCost(s,close,s.inventoryCostBatches.at(-1));purchaseNote(s,invoice,'credito',2000);const before=structuredClone(s);assert.throws(()=>postInventoryCost(s,{...close,review:inventoryCostReview(p)},actor),/revisión/);assert.deepEqual(s,before);postCosts(s,close,actor);for(const mutate of [c=>c.inventoryCostBatches.at(-1).corrections[0].amount++,c=>c.documents.at(-1).date='2026-10-02',c=>c.documents.at(-1).lines[0].price++,c=>delete c.inventoryCostBatches.at(-1).corrections,c=>c.inventoryCostBatches.at(-1).costVersion=99]){const copy=structuredClone(s);mutate(copy);assert.throws(()=>validateState(copy))}})
test('cost corrections fully consumed stock retain zero inventory and reconcile all rounding cents to disposal',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {invoice,product}=receivedPurchase(s,10,2000);engine.adjustStock(s,'Administrador General',product.id,'principal',-50,'Agota','2026-10-03');postCosts(s,{date:'2026-10-03',reference:'Sin existencias',accounts},actor);purchaseNote(s,invoice,'credito',1);const b=postCosts(s,{date:'2026-10-04',reference:'Un centavo',accounts},actor);assert.equal(b.balances.find(b=>b.productId===product.id).value,0);const j=s.entries.find(e=>e.inventoryBatchId===b.id);assert.equal(j.lines.find(l=>l.accountId===accounts.adjustments).credit,1);assert.ok(!j.lines.some(l=>l.accountId===accounts.inventory));validateState(s)})
test('note cost uses original non-recoverable VAT and leaves service adjustments outside inventory',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);s.settings.iva='Responsable Monotributo';const article=s.products.find(p=>p.sku==='REM-M-NEG'),service={...article,id:'note-service',sku:'NOTE-SERV',name:'Servicio',kind:'Servicio',parent:''};engine.saveProduct(s,service);const {invoice,product}=receivedPurchase(s,10,2000,'2026-10-02',{lines:[{productId:article.id,description:article.name,quantity:10,unit:article.unit,price:2000,tax:'21',discount:0},{productId:service.id,description:service.name,quantity:1,unit:service.unit,price:1000,tax:'21',discount:0}]});postCosts(s,{date:'2026-10-02',reference:'IVA inicial',accounts},actor);purchaseNote(s,invoice,'credito',1000,'2026-10-03');s.settings.iva='Responsable Inscripto';const b=postCosts(s,{date:'2026-10-03',reference:'IVA nota',accounts},actor);assert.equal(b.corrections[0].amount,-1210);assert.equal(b.balances.find(b=>b.productId===product.id).value,62990);assert.equal(s.entries.find(e=>e.inventoryBatchId===b.id).lines.find(l=>l.accountId==='5.1').debit,1210);validateState(s)})


test('legacy CPP constancias remain valid and migrate through a new price-correction closing without rewriting history',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {invoice,product}=receivedPurchase(s,10,2000);postCosts(s,{date:'2026-10-02',reference:'Compra heredada',accounts},actor);for(const [i,b] of s.inventoryCostBatches.entries()){delete b.costVersion;delete b.corrections;b.review=inventoryCostReview(previewInventoryCost(s,{...b,costVersion:1},s.inventoryCostBatches[i-1],false))}validateState(s);const old=structuredClone(s.inventoryCostBatches);purchaseNote(s,invoice,'credito',2000);validateState(s);const b=postCosts(s,{date:'2026-10-04',reference:'Migración CPP con NC',accounts},actor);assert.equal(b.costVersion,5);assert.equal(b.balances.find(b=>b.productId===product.id).value,58000);assert.deepEqual(s.inventoryCostBatches.slice(0,2),old);validateState(s)})
test('cost notes on unreceived invoices remain expenses while unidentified articles and negative purchase cost reject atomically',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const supplier=s.parties.find(p=>p.side==='proveedor'),p=s.products.find(p=>p.sku==='REM-M-NEG');const invoice=engine.createDocument(s,input(s,'factura',{side:'proveedor',partyId:supplier.id,letter:'A',date:'2026-10-02',due:'2026-10-02'}),'Administración');purchaseNote(s,invoice,'credito',1);const b=postCosts(s,{date:'2026-10-04',reference:'Sin recepción',accounts},actor);assert.equal(b.corrections.length,0);assert.equal(b.entryIds.length,0);validateState(s);const f=costingFixture();postCosts(f.s,f.base,f.actor);const received=receivedPurchase(f.s,10,2000);purchaseNote(f.s,received.invoice,'credito',1000,'2026-10-03',{lines:[{...received.invoice.lines[0],productId:f.s.products.find(x=>x.id!==p.id&&x.kind!=='Servicio').id,quantity:1,price:1000}]});const before=structuredClone(f.s);assert.throws(()=>postCosts(f.s,{date:'2026-10-04',reference:'SKU incorrecto',accounts:f.accounts},f.actor),/artículos/);assert.deepEqual(f.s,before);const g=costingFixture();postCosts(g.s,g.base,g.actor);const article=g.s.products.find(p=>p.sku==='REM-M-NEG'),service={...article,id:'negative-service',sku:'NEG-SERV',kind:'Servicio',parent:''};engine.saveProduct(g.s,service);const receivedG=receivedPurchase(g.s,1,100,'2026-10-02',{lines:[{productId:article.id,description:article.name,quantity:1,unit:article.unit,price:100,tax:'21',discount:0},{productId:service.id,description:'Servicio',quantity:1,unit:service.unit,price:10000,tax:'21',discount:0}]});purchaseNote(g.s,receivedG.invoice,'credito',200,'2026-10-03',{lines:[{...receivedG.invoice.lines[0],quantity:1,price:200}]});const unchanged=structuredClone(g.s);assert.throws(()=>postCosts(g.s,{date:'2026-10-03',reference:'Costo negativo',accounts:g.accounts},g.actor),/no negativos/);assert.deepEqual(g.s,unchanged)})

test('a price note against a purchase absorbed into reviewed opening values requires an explicit allocation instead of silent omission',()=>{const {s,actor,base,accounts}=costingFixture();const {invoice}=receivedPurchase(s,10,2000,'2026-10-01');base.opening=inventoryOpeningBalances(s,base.date).map(b=>({...b,value:Math.round(b.quantity*1000)}));postCosts(s,base,actor);purchaseNote(s,invoice,'credito',2000,'2026-10-02');const before=structuredClone(s);assert.throws(()=>postCosts(s,{date:'2026-10-02',reference:'Origen sin trazabilidad',accounts},actor),/anterior a la apertura/);assert.deepEqual(s,before)})

function openingNoteFixture(){const {s,actor,base,accounts}=costingFixture();const {invoice,product}=receivedPurchase(s,10,2000,'2026-10-01');base.opening=inventoryOpeningBalances(s,base.date).map(b=>({...b,value:Math.round(b.quantity*1000)}));postCosts(s,base,actor);engine.createDocument(s,input(s,'remito',{date:'2026-10-02',due:'2026-10-02',lines:[{...invoice.lines[0],quantity:5}]}),'Administración');postCosts(s,{date:'2026-10-02',reference:'Salida previa a nota',accounts},actor);const note=purchaseNote(s,invoice,'credito',2000,'2026-10-03');const openingNotes=[{noteId:note.id,reference:'Costos de apertura conciliados con inventario físico y ventas anteriores',lines:[{sourceProductId:product.id,target:'Existencias',productId:product.id,depositId:'principal',value:1200},{sourceProductId:product.id,target:'Resultados',branchId:'central',accountId:accounts.cogs,value:800}]}];return {s,actor,accounts,invoice,product,note,input:{date:'2026-10-03',reference:'Asignación revisada',accounts,openingNotes}}}
test('reviewed opening price-note allocations correct later CPP outflows and recognize the pre-opening sold share without rewriting history',()=>{const {s,actor,accounts,product,note,input}=openingNoteFixture(),old=structuredClone(s.inventoryCostBatches),moves=structuredClone(s.stockMoves),b=postCosts(s,input,actor);assert.equal(b.costVersion,5);assert.equal(b.sourceMoves.length,0);assert.equal(b.balances.find(b=>b.productId===product.id).value,43920);assert.deepEqual(s.inventoryCostBatches.slice(0,2),old);assert.deepEqual(s.stockMoves,moves);assert.equal(b.corrections[0].noteId,note.id);assert.deepEqual(b.corrections[0].openingAssignment,input.openingNotes[0]);const j=s.entries.find(e=>e.inventoryBatchId===b.id);assert.equal(j.lines.find(l=>l.accountId===accounts.inventory).credit,1080);assert.equal(j.lines.find(l=>l.accountId===accounts.cogs).credit,920);assert.equal(j.lines.find(l=>l.accountId==='5.1').debit,2000);validateState(JSON.parse(JSON.stringify(s)));const next=postCosts(s,{date:'2026-10-04',reference:'Sin repetir asignación',accounts},actor);assert.equal(next.entryIds.length,0);assert.equal(next.balances.find(b=>b.productId===product.id).value,43920);validateState(s)})
test('opening note assignments reject incomplete, duplicate, unknown and invalid destinations or unsupported amounts atomically',()=>{const {s,actor,input,accounts}=openingNoteFixture(),a=input.openingNotes[0],row=a.lines[0];for(const allocation of [{...a,reference:''},{...a,reference:'x'.repeat(201)},{...a,lines:[]},{...a,lines:[row,row,a.lines[1]]},{...a,lines:[{...row,value:1199},a.lines[1]]},{...a,lines:[{...row,value:-1},a.lines[1]]},{...a,lines:[{...row,value:1.5},a.lines[1]]},{...a,lines:[{...row,productId:'lost'},a.lines[1]]},{...a,lines:[{...row,depositId:'lost'},a.lines[1]]},{...a,lines:[row,{...a.lines[1],accountId:accounts.inventory}]},{...a,lines:[row,{...a.lines[1],branchId:'lost'}]},{...a,lines:[{...row,sourceProductId:'lost'},a.lines[1]]},{...a,noteId:'lost'},{...a,lines:[{...row,target:'Other'},a.lines[1]]}]){const before=structuredClone(s);assert.throws(()=>postCosts(s,{...input,openingNotes:[allocation]},actor));assert.deepEqual(s,before)}assert.throws(()=>postCosts(s,{...input,openingNotes:[a,a]},actor),/repeticiones/);assert.throws(()=>postCosts(s,{...input,openingNotes:{}},actor),/lista/)})
test('opening note credits cannot make allocated opening pools negative and preserve exact cents when all later stock was disposed',()=>{const f=openingNoteFixture();f.input.openingNotes[0].lines=[{sourceProductId:f.product.id,target:'Existencias',productId:f.product.id,depositId:'principal',value:2000}];f.s.inventoryCostBatches[0].opening.find(b=>b.productId===f.product.id).value=1000;assert.throws(()=>previewInventoryCost(f.s,f.input,f.s.inventoryCostBatches.at(-1)),/no negativos/);const g=openingNoteFixture();engine.adjustStock(g.s,'Administrador General',g.product.id,'principal',-45,'Agota después de apertura','2026-10-03');const b=postCosts(g.s,g.input,g.actor);assert.equal(b.balances.find(b=>b.productId===g.product.id).value,0);assert.equal(b.balances.find(b=>b.productId===g.product.id).quantity,0);assert.equal(signedCost(g.s,b,g.accounts.cogs),-920);assert.equal(signedCost(g.s,b,g.accounts.adjustments),43920);validateState(g.s)})
function signedCost(s,b,accountId){return s.entries.filter(e=>e.inventoryBatchId===b.id).flatMap(e=>e.lines).filter(l=>l.accountId===accountId).reduce((n,l)=>n+l.debit-l.credit,0)}
test('opening allocations can identify transformed products and other branches with balanced transit and immutable review evidence',()=>{const {s,actor,input,accounts,product}=openingNoteFixture(),finished=s.products.find(p=>p.sku==='PANT-42-AZ');s.masters.branches.push({id:'opening-other',name:'Otra',active:true,point:'2'});input.openingNotes[0].lines=[{sourceProductId:product.id,target:'Existencias',productId:finished.id,depositId:'principal',value:1200},{sourceProductId:product.id,target:'Resultados',branchId:'opening-other',accountId:accounts.adjustments,value:800}];const reviewed=previewInventoryCost(s,input,s.inventoryCostBatches.at(-1));const different=structuredClone(input);different.openingNotes[0].reference='Otra justificación';assert.throws(()=>postInventoryCost(s,{...different,review:inventoryCostReview(reviewed)},actor),/revisión/);const b=postCosts(s,input,actor);assert.equal(b.balances.find(b=>b.productId===finished.id).value,18800);assert.equal(signedCost(s,b,accounts.transit),0);assert.equal(b.entryIds.length,2);validateState(s);for(const change of [c=>c.inventoryCostBatches.at(-1).openingNotes[0].lines[0].value++,c=>c.inventoryCostBatches.at(-1).openingNotes[0].reference='cambiada',c=>delete c.inventoryCostBatches.at(-1).openingNotes,c=>c.inventoryCostBatches.at(-1).corrections[0].openingAssignment.reference='cambiada',c=>c.inventoryCostBatches.at(-1).costVersion=2]){const copy=structuredClone(s);change(copy);assert.throws(()=>validateState(copy))}})

test('successive opening debit and credit assignments retain their original allocation and replay exactly once',()=>{const {s,actor,input,invoice,product,accounts}=openingNoteFixture();postCosts(s,input,actor);const note=purchaseNote(s,invoice,'debito',1000,'2026-10-04'),next={date:'2026-10-04',reference:'Nueva ND de apertura',accounts,openingNotes:[{noteId:note.id,reference:'Cargo posterior íntegro al costo de apertura',lines:[{sourceProductId:product.id,target:'Existencias',productId:product.id,depositId:'principal',value:1000}]}]};const b=postCosts(s,next,actor);assert.equal(b.balances.find(b=>b.productId===product.id).value,44820);assert.equal(signedCost(s,b,accounts.inventory),900);assert.equal(signedCost(s,b,accounts.cogs),100);assert.equal(signedCost(s,b,'5.1'),-1000);assert.equal(b.corrections.length,1);validateState(s);const idle=postCosts(s,{date:'2026-10-05',reference:'Después de las dos notas',accounts},actor);assert.equal(idle.entryIds.length,0);assert.equal(idle.balances.find(b=>b.productId===product.id).value,44820);validateState(s)})
test('reviewed allocation to results cannot disguise a negative acquisition price on an opening purchase with services',()=>{const {s,actor,base,accounts}=costingFixture(),product=s.products.find(p=>p.sku==='REM-M-NEG'),service={...product,id:'opening-service',sku:'OPEN-SERV',kind:'Servicio',parent:''};engine.saveProduct(s,service);const {invoice}=receivedPurchase(s,1,100,'2026-10-01',{lines:[{productId:product.id,description:product.name,quantity:1,unit:product.unit,price:100,tax:'21',discount:0},{productId:service.id,description:'Servicio',quantity:1,unit:service.unit,price:10000,tax:'21',discount:0}]});base.opening=inventoryOpeningBalances(s,base.date).map(b=>({...b,value:b.quantity*1000}));postCosts(s,base,actor);const note=purchaseNote(s,invoice,'credito',200,'2026-10-02',{lines:[{...invoice.lines[0],quantity:1,price:200}]}),close={date:'2026-10-02',reference:'Precio negativo declarado',accounts,openingNotes:[{noteId:note.id,reference:'No debe habilitar un costo de compra negativo',lines:[{sourceProductId:product.id,target:'Resultados',branchId:'central',accountId:accounts.cogs,value:200}]}]},before=structuredClone(s);assert.throws(()=>postCosts(s,close,actor),/no negativos/);assert.deepEqual(s,before)})

function customerDelivery(s,quantity=5,date='2026-10-03'){const product=s.products.find(p=>p.sku==='REM-M-NEG'),d=input(s,'remito',{date,due:date,lines:[{productId:product.id,description:product.name,quantity,unit:product.unit,price:10000,tax:'21',discount:0}]});const remit=engine.createDocument(s,d,'Administración'),invoice=engine.createDocument(s,{...d,kind:'factura',sourceId:remit.id},'Administración');return {remit,invoice,product}}
function returnInput(remit,quantity,date,note){return {date,sourceId:remit.id,depositId:'principal',reason:'Devolución de prueba',noteId:note?.id,lines:[{productId:remit.lines[0].productId,quantity}]}}
function returnNote(s,invoice,quantity,date,price=invoice.lines[0].price){return purchaseNote(s,invoice,'credito',price,date,{lines:[{...invoice.lines[0],quantity,price}]})}
test('physical returns conserve delivered limits, dated stock and financial documents and support pending notes',()=>{const {s,actor}=costingFixture(),{remit,invoice,product}=customerDelivery(s),documents=structuredClone(s.documents),before=s.stockMoves.filter(m=>m.productId===product.id).reduce((n,m)=>n+m.quantity,0);const r=registerStockReturn(s,returnInput(remit,2,'2026-10-04'),actor);assert.equal(r.number,'INT-DV-00000001');assert.equal(r.responsible,actor.name);assert.equal(s.stockMoves.at(-1).quantity,2);assert.equal(s.stockMoves.filter(m=>m.productId===product.id).reduce((n,m)=>n+m.quantity,0),before+2);assert.deepEqual(s.documents,documents);assert.equal(remainingReturnLines(s,remit.id)[0].quantity,3);validateState(s);const note=returnNote(s,invoice,2,'2026-10-05'),moves=structuredClone(s.stockMoves);linkStockReturnNote(s,r.id,note.id,actor);assert.equal(r.noteNumber,note.number);assert.deepEqual(s.stockMoves,moves);assert.throws(()=>linkStockReturnNote(s,r.id,note.id,actor),/pendiente/);validateState(JSON.parse(JSON.stringify(s)))})
test('return registration rejects excess, duplicate lines, wrong branch, date, precision and unauthorized actors without mutation',()=>{const {s,actor}=costingFixture(),{remit}=customerDelivery(s);const original=returnInput(remit,2,'2026-10-04');for(const change of [{lines:[{...original.lines[0],quantity:6}]},{lines:[original.lines[0],original.lines[0]]},{lines:[{...original.lines[0],quantity:0.0000001}]},{date:'2026-10-02'},{depositId:'missing'},{reason:''}]){const before=structuredClone(s);assert.throws(()=>registerStockReturn(s,{...original,...change},actor));assert.deepEqual(s,before)}assert.throws(()=>registerStockReturn(s,original,{...actor,role:'Vendedor'}),/perfil/);registerStockReturn(s,{...original,lines:[{...original.lines[0],quantity:5}]},actor);assert.deepEqual(remainingReturnLines(s,remit.id),[]);assert.throws(()=>registerStockReturn(s,original,actor),/cantidad/)})
test('supplier returns require available stock and matching note quantities while retaining the financial credit',()=>{const {s,actor}=costingFixture(),{remit,invoice,product}=receivedPurchase(s,2,2000);const note=returnNote(s,invoice,1,'2026-10-03'),i=returnInput(remit,2,'2026-10-03',note),before=structuredClone(s);assert.throws(()=>registerStockReturn(s,i,actor),/exactamente/);assert.deepEqual(s,before);engine.adjustStock(s,'Administrador General',product.id,'principal',-42,'Agotar existencias','2026-10-03');assert.throws(()=>registerStockReturn(s,returnInput(remit,1,'2026-10-04',note),actor),/stock|existencias/i);assert.equal(s.stockReturns?.length||0,0)})
test('backup validation rejects lost, duplicated or altered return moves and credit links',()=>{const {s,actor}=costingFixture(),{remit,invoice}=customerDelivery(s),note=returnNote(s,invoice,2,'2026-10-04');registerStockReturn(s,returnInput(remit,2,'2026-10-04',note),actor);for(const mutate of [c=>delete c.stockReturns,c=>c.stockReturns.push(c.stockReturns[0]),c=>c.stockReturns[0].lines[0].quantity++,c=>c.stockMoves.at(-1).returnId='lost',c=>c.stockMoves.at(-1).quantity=-2,c=>c.stockReturns[0].noteDate='2026-10-05',c=>c.documents.find(d=>d.kind==='credito').lines[0].quantity=1]){const copy=structuredClone(s);mutate(copy);assert.throws(()=>validateState(copy))}})
test('customer returns restore original delivered CPP rather than selling price and close only with a credit note',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);receivedPurchase(s,10,2000);const {remit,invoice,product}=customerDelivery(s);const old=postCosts(s,{date:'2026-10-03',reference:'Venta antes de devolución',accounts},actor),oldEntries=structuredClone(s.entries);const r=registerStockReturn(s,returnInput(remit,2,'2026-10-04'),actor),close={date:'2026-10-04',reference:'Reposición de cliente',accounts};assert.throws(()=>previewInventoryCost(s,close,old),/nota de crédito/);const note=returnNote(s,invoice,2,'2026-10-04');linkStockReturnNote(s,r.id,note.id,actor);const b=postCosts(s,close,actor);assert.equal(b.costVersion,5);assert.equal(b.rows[0].kind,'Devolución cliente');assert.equal(b.rows[0].value,2400);assert.equal(b.rows[0].creditId,note.id);assert.equal(b.balances.find(b=>b.productId===product.id).value,56400);assert.equal(signedCost(s,b,accounts.cogs),-2400);assert.deepEqual(s.entries.slice(0,oldEntries.length),oldEntries);assert.equal(b.returnSources[0].noteId,note.id);validateState(s);const next=postCosts(s,{date:'2026-10-05',reference:'Sin repetir devolución',accounts},actor);assert.equal(next.entryIds.length,0);for(const mutate of [c=>c.inventoryCostBatches[2].rows[0].value++,c=>delete c.inventoryCostBatches[2].returnSources,c=>c.inventoryCostBatches[2].returnSources[0].noteId='lost',c=>c.stockReturns[0].noteId='lost']){const copy=structuredClone(s);mutate(copy);assert.throws(()=>validateState(copy))}})
test('supplier return credit is excluded from price recosting, removes CPP and recognizes the difference once',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {remit,invoice,product}=receivedPurchase(s,10,2000);postCosts(s,{date:'2026-10-02',reference:'Compra antes de devolución',accounts},actor);const note=returnNote(s,invoice,2,'2026-10-04');registerStockReturn(s,returnInput(remit,2,'2026-10-04',note),actor);const b=postCosts(s,{date:'2026-10-04',reference:'Devolución al proveedor',accounts},actor);assert.equal(b.rows[0].kind,'Devolución proveedor');assert.equal(b.rows[0].value,2400);assert.equal(b.rows[0].creditValue,4000);assert.deepEqual(b.corrections,[]);assert.equal(b.balances.find(b=>b.productId===product.id).value,57600);assert.equal(signedCost(s,b,accounts.inventory),-2400);assert.equal(signedCost(s,b,accounts.adjustments),-1600);assert.equal(signedCost(s,b,'5.1'),4000);assert.equal(s.entries.filter(e=>e.documentId===note.id).length,1);validateState(s);const c=postCosts(s,{date:'2026-10-05',reference:'Devolución ya reconocida',accounts},actor);assert.equal(c.entryIds.length,0);validateState(s)})
test('later purchase price credits recost both the sale and its return while preserving earlier journals',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {invoice:purchase,product}=receivedPurchase(s,10,2000),{remit,invoice}=customerDelivery(s);postCosts(s,{date:'2026-10-03',reference:'Venta',accounts},actor);const note=returnNote(s,invoice,2,'2026-10-04');registerStockReturn(s,returnInput(remit,2,'2026-10-04',note),actor);postCosts(s,{date:'2026-10-04',reference:'Entrada de devolución',accounts},actor);const old=structuredClone(s.entries);purchaseNote(s,purchase,'credito',2000,'2026-10-05');const b=postCosts(s,{date:'2026-10-05',reference:'Corrección posterior al retorno',accounts},actor);assert.equal(b.balances.find(b=>b.productId===product.id).value,54520);assert.equal(signedCost(s,b,accounts.cogs),-120);assert.equal(signedCost(s,b,accounts.inventory),-1880);assert.deepEqual(s.entries.slice(0,old.length),old);validateState(s)})
test('a pre-opening customer delivery requires a reviewed total historical return cost and reference',()=>{const {s,actor,base,accounts}=costingFixture(),{remit,invoice,product}=customerDelivery(s,5,'2026-10-01');base.opening=inventoryOpeningBalances(s,base.date).map(b=>({...b,value:b.quantity*1000}));postCosts(s,base,actor);const note=returnNote(s,invoice,2,'2026-10-02'),r=registerStockReturn(s,returnInput(remit,2,'2026-10-02',note),actor),close={date:'2026-10-02',reference:'Costo histórico recuperado',accounts};assert.throws(()=>previewInventoryCost(s,close,s.inventoryCostBatches.at(-1)),/anterior a la apertura/);const b=postCosts(s,{...close,returnCosts:[{returnId:r.id,productId:product.id,value:1700,reference:'Costo conservado en libro anterior'}]},actor);assert.equal(b.rows[0].value,1700);assert.equal(b.rows[0].costReference,'Costo conservado en libro anterior');assert.equal(b.balances.find(b=>b.productId===product.id).value,36700);validateState(s)})
test('partial fractional returns exhaust the original sale cost in exact cents',()=>{const {s,actor,base,accounts}=costingFixture(),p=s.products.find(p=>p.sku==='REM-M-NEG');s.stockMoves=[{...s.stockMoves[0],productId:p.id,quantity:0.3}];base.opening=[{productId:p.id,depositId:'principal',quantity:0.3,value:1}];postCosts(s,base,actor);const {remit,invoice}=customerDelivery(s,0.3,'2026-10-02');postCosts(s,{date:'2026-10-02',reference:'Venta fraccionaria',accounts},actor);const costs=[];for(const date of ['2026-10-03','2026-10-04','2026-10-05']){const note=returnNote(s,invoice,0.1,date);registerStockReturn(s,returnInput(remit,0.1,date,note),actor);const b=postCosts(s,{date,reference:'Retorno '+date,accounts},actor);costs.push(b.rows[0].value)}assert.deepEqual(costs,[0,1,0]);assert.equal(s.inventoryCostBatches.at(-1).balances[0].value,1);assert.equal(s.inventoryCostBatches.at(-1).balances[0].quantity,0.3);validateState(s)})
test('physical note classification cannot rewrite an earlier price cutoff and returns cannot precede a valued cutoff',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {remit,invoice}=receivedPurchase(s,10,2000);purchaseNote(s,invoice,'credito',4000,'2026-10-03',{lines:[{...invoice.lines[0],quantity:2}]});postCosts(s,{date:'2026-10-03',reference:'Nota tratada como precio',accounts},actor);const note=s.documents.at(-1),before=structuredClone(s);assert.throws(()=>registerStockReturn(s,returnInput(remit,2,'2026-10-04',note),actor),/reclasificarse/);assert.deepEqual(s,before);assert.throws(()=>registerStockReturn(s,returnInput(remit,2,'2026-10-03'),actor),/valorizado/);const r=registerStockReturn(s,returnInput(remit,2,'2026-10-04'),actor);assert.throws(()=>linkStockReturnNote(s,r.id,note.id,actor),/reclasificarse/);validateState(s)})

test('supplier returns below CPP debit the difference account and leave no residual purchase expense',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {remit,invoice}=receivedPurchase(s,10,2000);postCosts(s,{date:'2026-10-02',reference:'Compra valorizada',accounts},actor);const note=returnNote(s,invoice,2,'2026-10-04',500);registerStockReturn(s,returnInput(remit,2,'2026-10-04',note),actor);const b=postCosts(s,{date:'2026-10-04',reference:'Crédito menor al costo',accounts},actor);assert.equal(b.rows[0].value,2400);assert.equal(b.rows[0].creditValue,1000);assert.equal(signedCost(s,b,accounts.adjustments),1400);assert.equal(signedCost(s,b,'5.1'),1000);validateState(s)})
test('supplier physical credit includes originally non-recoverable VAT and leaves credited services in expense after fiscal edits',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);s.settings.iva='Responsable Monotributo';const p=s.products.find(p=>p.sku==='REM-M-NEG'),service={...p,id:'return-service',sku:'RET-SERV',name:'Servicio separado',kind:'Servicio',parent:''};engine.saveProduct(s,service);const lines=[{productId:p.id,description:p.name,quantity:10,unit:p.unit,price:2000,tax:'21',discount:0},{productId:service.id,description:service.name,quantity:1,unit:service.unit,price:1000,tax:'21',discount:0}],{remit,invoice}=receivedPurchase(s,10,2000,'2026-10-02',{lines});postCosts(s,{date:'2026-10-02',reference:'Compra con IVA costo',accounts},actor);const note=purchaseNote(s,invoice,'credito',2000,'2026-10-04',{lines:[{...lines[0],quantity:2},lines[1]]});registerStockReturn(s,returnInput(remit,2,'2026-10-04',note),actor);s.settings.iva='Responsable Inscripto';const b=postCosts(s,{date:'2026-10-04',reference:'Devolución con servicios',accounts},actor);assert.equal(b.rows[0].value,2568);assert.equal(b.rows[0].creditValue,4840);assert.equal(signedCost(s,b,'5.1'),4840);assert.equal(signedCost(s,b,accounts.adjustments),-2272);assert.equal(b.rows.length,1);validateState(s)})
test('a supplier credit classified as physical cannot close before its actual stock movement',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {remit,invoice}=receivedPurchase(s,10,2000),note=returnNote(s,invoice,2,'2026-10-04');registerStockReturn(s,returnInput(remit,2,'2026-10-05',note),actor);assert.throws(()=>previewInventoryCost(s,{date:'2026-10-04',reference:'Nota antes de despacho',accounts},s.inventoryCostBatches.at(-1)),/movimiento físico/);postCosts(s,{date:'2026-10-05',reference:'Nota y despacho completos',accounts},actor);validateState(s)})
test('a version 3 costing history migrates to physical returns without changing previous constancias',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {remit,invoice,product}=customerDelivery(s);postCosts(s,{date:'2026-10-03',reference:'Entrega anterior versión 3',accounts},actor);for(const [i,b] of s.inventoryCostBatches.entries()){b.costVersion=3;b.review=inventoryCostReview(previewInventoryCost(s,{...b,costVersion:3},s.inventoryCostBatches[i-1],false))}validateState(s);const old=structuredClone(s.inventoryCostBatches),note=returnNote(s,invoice,2,'2026-10-04');registerStockReturn(s,returnInput(remit,2,'2026-10-04',note),actor);const b=postCosts(s,{date:'2026-10-04',reference:'Migración de devoluciones',accounts},actor);assert.equal(b.costVersion,5);assert.equal(b.rows[0].value,2000);assert.equal(b.balances.find(b=>b.productId===product.id).value,37000);assert.deepEqual(s.inventoryCostBatches.slice(0,2),old);validateState(s)})

function unbilledReceipt(s,quantity=10,date='2026-10-02',lines){const supplier=s.parties.find(p=>p.side==='proveedor'),product=s.products.find(p=>p.sku==='REM-M-NEG'),doc=input(s,'remito',{side:'proveedor',partyId:supplier.id,letter:'A',date,due:date,lines:lines||[{productId:product.id,description:product.name,quantity,unit:product.unit,price:99999,tax:'21',discount:0}]});return engine.createDocument(s,doc,'Administración')}
function receiptEstimate(receipt,value=20000){return {receiptId:receipt.id,reference:'Orden de compra y recepción firmada',lines:receipt.lines.map(l=>({productId:l.productId,value}))}}
function receiptInvoice(s,receipt,price=2200,date='2026-10-04',lines){return engine.createDocument(s,{...receipt,kind:'factura',sourceId:receipt.id,date,due:date,lines:lines||receipt.lines.map(l=>({...l,price})),allocations:[]},'Administración')}
function estimatedFixture(){const f=costingFixture();postCosts(f.s,f.base,f.actor);const receipt=unbilledReceipt(f.s),sale=customerDelivery(f.s,5,'2026-10-03');const batch=postCosts(f.s,{date:'2026-10-03',reference:'Recepción y entrega estimadas',accounts:f.accounts,receiptCosts:[receiptEstimate(receipt)]},f.actor);return {...f,receipt,sale,batch}}
test('unbilled goods accrue a reviewed cost liability without using remit prices or creating VAT, invoices or stock twice',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const receipt=unbilledReceipt(s),moves=structuredClone(s.stockMoves),documents=structuredClone(s.documents),b=postCosts(s,{date:'2026-10-02',reference:'Devengamiento estimado',accounts,receiptCosts:[receiptEstimate(receipt)]},actor);assert.equal(b.costVersion,5);assert.equal(b.rows[0].kind,'Compra estimada');assert.equal(b.rows[0].value,20000);assert.equal(signedCost(s,b,accounts.unbilled),-20000);assert.equal(signedCost(s,b,accounts.inventory),20000);assert.equal(b.receipts[0].estimatedValue,20000);assert.equal(b.receipts[0].invoiceId,undefined);assert.deepEqual(s.stockMoves,moves);assert.deepEqual(s.documents,documents);assert.ok(!s.entries.filter(e=>e.inventoryBatchId===b.id).flatMap(e=>e.lines).some(l=>l.accountId===s.settings.accountMap.vatCredit));validateState(s);const next=postCosts(s,{date:'2026-10-03',reference:'Deuda conservada',accounts},actor);assert.equal(next.entryIds.length,0);assert.equal(next.receipts[0].estimatedValue,20000);validateState(s)})
test('late invoicing clears the estimated liability and recosts prior sales in the new cutoff without rewriting them',()=>{const {s,actor,accounts,receipt,batch}=estimatedFixture(),old=structuredClone(s.inventoryCostBatches),entries=structuredClone(s.entries);const invoice=receiptInvoice(s,receipt);const b=postCosts(s,{date:'2026-10-04',reference:'Factura recibida',accounts},actor);assert.equal(b.sourceMoves.length,0);assert.equal(b.balances.find(b=>b.sku==='REM-M-NEG').value,55800);assert.equal(signedCost(s,b,accounts.cogs),200);assert.equal(signedCost(s,b,accounts.inventory),1800);assert.equal(signedCost(s,b,accounts.unbilled),20000);assert.equal(signedCost(s,b,'5.1'),-22000);assert.equal(b.settlements[0].invoiceId,invoice.id);assert.equal(b.settlements[0].difference,2000);assert.equal(b.receipts[0].invoiceValue,22000);assert.deepEqual(s.inventoryCostBatches.slice(0,2),old);assert.deepEqual(s.entries.slice(0,entries.length),entries);assert.equal(batch.balances.find(b=>b.sku==='REM-M-NEG').value,54000);validateState(JSON.parse(JSON.stringify(s)));const next=postCosts(s,{date:'2026-10-05',reference:'Conciliación ya reconocida',accounts},actor);assert.equal(next.entryIds.length,0);assert.deepEqual(next.settlements,[]);validateState(s)})
test('estimates reject missing articles, duplicated or invoiced receipts, fractional cents, missing reference or liability account atomically',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const receipt=unbilledReceipt(s),estimate=receiptEstimate(receipt),close={date:'2026-10-02',reference:'Estimación inválida',accounts};for(const estimates of [[],[{...estimate,lines:[]}],[estimate,estimate],[{...estimate,reference:''}],[{...estimate,receiptId:'lost'}],[{...estimate,lines:[{...estimate.lines[0],value:1.001}]}],[{...estimate,lines:[estimate.lines[0],estimate.lines[0]]}]]){const before=structuredClone(s);assert.throws(()=>postCosts(s,{...close,receiptCosts:estimates},actor));assert.deepEqual(s,before)}const noAccount={...accounts};delete noAccount.unbilled;assert.throws(()=>postCosts(s,{...close,accounts:noAccount,receiptCosts:[estimate]},actor),/pasivo/);receiptInvoice(s,receipt,2000,'2026-10-02');assert.throws(()=>postCosts(s,{...close,receiptCosts:[estimate]},actor),/pendiente/);assert.throws(()=>previewInventoryCost(s,{...close,costVersion:4,receiptCosts:[]},s.inventoryCostBatches.at(-1)),/versión anterior/i)})
test('a late invoice below the estimate reverses inventory and prior cost of sales in exact cents',()=>{const {s,actor,accounts,receipt}=estimatedFixture();receiptInvoice(s,receipt,1800);const b=postCosts(s,{date:'2026-10-04',reference:'Factura menor que estimación',accounts},actor);assert.equal(b.balances.find(b=>b.sku==='REM-M-NEG').value,52200);assert.equal(signedCost(s,b,accounts.cogs),-200);assert.equal(signedCost(s,b,accounts.inventory),-1800);assert.equal(signedCost(s,b,accounts.unbilled),20000);assert.equal(signedCost(s,b,'5.1'),-18000);assert.equal(b.settlements[0].difference,-2000);validateState(s)})
test('late invoice zero differences still cancel liability once and preserve an explicit reconciliation',()=>{const {s,actor,accounts,receipt}=estimatedFixture();receiptInvoice(s,receipt,2000);const b=postCosts(s,{date:'2026-10-04',reference:'Factura coincide',accounts},actor);assert.equal(b.settlements[0].difference,0);assert.equal(signedCost(s,b,accounts.inventory),0);assert.equal(signedCost(s,b,accounts.cogs),0);assert.equal(signedCost(s,b,accounts.unbilled),20000);assert.equal(signedCost(s,b,'5.1'),-20000);validateState(s)})
test('unbilled receipts in manual opening recognize debt against opening equity and require reviewed invoice differences',()=>{const {s,actor,base,accounts}=costingFixture(),receipt=unbilledReceipt(s,10,'2026-10-01'),p=s.products.find(p=>p.sku==='REM-M-NEG');customerDelivery(s,20,'2026-10-01');base.opening=inventoryOpeningBalances(s,base.date).map(b=>({...b,value:b.quantity*(b.productId===p.id?1200:1000)}));base.receiptCosts=[receiptEstimate(receipt)];const opening=postCosts(s,base,actor);assert.equal(opening.balances.reduce((n,b)=>n+b.value,0),56000);assert.equal(signedCost(s,opening,accounts.unbilled),-20000);assert.equal(signedCost(s,opening,accounts.opening),-36000);customerDelivery(s,5,'2026-10-02');postCosts(s,{date:'2026-10-02',reference:'Venta posterior a apertura',accounts},actor);const invoice=receiptInvoice(s,receipt,2200,'2026-10-03'),input={date:'2026-10-03',reference:'Conciliación de recepción migrada',accounts};assert.throws(()=>postCosts(s,input,actor),/reparto revisado/);const b=postCosts(s,{...input,openingInvoices:[{invoiceId:invoice.id,reference:'60 por ciento permanecía en la apertura',lines:[{sourceProductId:p.id,target:'Existencias',productId:p.id,depositId:'principal',value:1200},{sourceProductId:p.id,target:'Resultados',branchId:'central',accountId:accounts.cogs,value:800}]}]},actor);assert.equal(b.balances.find(b=>b.productId===p.id).value,31000);assert.equal(signedCost(s,b,accounts.unbilled),20000);assert.equal(signedCost(s,b,accounts.cogs),1000);assert.equal(signedCost(s,b,accounts.inventory),1000);assert.equal(signedCost(s,b,'5.1'),-22000);assert.equal(b.settlements[0].openingAssignment.reference,'60 por ciento permanecía en la apertura');validateState(s);postCosts(s,{date:'2026-10-04',reference:'Migración conciliada',accounts},actor);validateState(s)})
test('opening invoice zero and negative differences require exact magnitudes and cannot corrupt opening inventory',()=>{const {s,actor,base,accounts}=costingFixture(),receipt=unbilledReceipt(s,10,'2026-10-01'),p=s.products.find(p=>p.sku==='REM-M-NEG');base.opening=inventoryOpeningBalances(s,base.date).map(b=>({...b,value:b.quantity*1000}));base.receiptCosts=[receiptEstimate(receipt)];postCosts(s,base,actor);const invoice=receiptInvoice(s,receipt,1800),a={invoiceId:invoice.id,reference:'Menor costo identificado',lines:[{sourceProductId:p.id,target:'Existencias',productId:p.id,depositId:'principal',value:2000}]},close={date:'2026-10-04',reference:'Diferencia menor en apertura',accounts,openingInvoices:[a]};for(const patch of [{reference:''},{lines:[]},{lines:[{...a.lines[0],value:2001}]},{lines:[a.lines[0],a.lines[0]]},{lines:[{...a.lines[0],productId:'lost'}]}]){const before=structuredClone(s);assert.throws(()=>postCosts(s,{...close,openingInvoices:[{...a,...patch}]},actor));assert.deepEqual(s,before)}const b=postCosts(s,close,actor);assert.equal(b.balances.find(b=>b.productId===p.id).value,48000);assert.equal(signedCost(s,b,accounts.inventory),-2000);validateState(s)})
test('late invoice original non-recoverable VAT and services stay separate after tax condition edits',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);s.settings.iva='Responsable Monotributo';const p=s.products.find(p=>p.sku==='REM-M-NEG'),service={...p,id:'receipt-service',sku:'REC-SERV',name:'Servicio separado',kind:'Servicio',parent:''};engine.saveProduct(s,service);const lines=[{productId:p.id,description:p.name,quantity:10,unit:p.unit,price:2000,tax:'21',discount:0},{productId:service.id,description:service.name,quantity:1,unit:service.unit,price:1000,tax:'21',discount:0}],receipt=unbilledReceipt(s,10,'2026-10-02',lines),estimate={receiptId:receipt.id,reference:'Costo previsto con IVA no recuperable',lines:[{productId:p.id,value:24200}]};postCosts(s,{date:'2026-10-02',reference:'Bienes sin factura y servicio separado',accounts,receiptCosts:[estimate]},actor);receiptInvoice(s,receipt,0,'2026-10-04',[{...lines[0],price:2200},lines[1]]);s.settings.iva='Responsable Inscripto';const b=postCosts(s,{date:'2026-10-04',reference:'Factura con IVA costo original',accounts},actor);assert.equal(b.settlements[0].invoiceValue,26620);assert.equal(b.settlements[0].difference,2420);assert.equal(signedCost(s,b,'5.1'),-26620);assert.equal(s.entries.flatMap(e=>e.lines).filter(l=>l.accountId==='5.1').reduce((n,l)=>n+l.debit-l.credit,0),1210);validateState(s)})
test('invoice reconciliation reaches transferred stock and keeps company transit and supplier debt exact',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const receipt=unbilledReceipt(s);s.masters.branches.push({id:'receipt-other',name:'Otra',active:true,point:'2'});s.masters.deposits.push({id:'receipt-deposit',name:'Otro depósito',branchId:'receipt-other'});transferStock(s,{date:'2026-10-03',fromId:'principal',toId:'receipt-deposit',reason:'Mercadería estimada',lines:[{productId:receipt.lines[0].productId,quantity:3}]},actor);postCosts(s,{date:'2026-10-03',reference:'Recepción y traslado estimados',accounts,receiptCosts:[receiptEstimate(receipt)]},actor);receiptInvoice(s,receipt);const b=postCosts(s,{date:'2026-10-04',reference:'Factura alcanza traslado previo',accounts},actor);assert.equal(b.balances.find(b=>b.depositId==='receipt-deposit').value,3720);assert.equal(signedCost(s,b,accounts.transit),0);assert.equal(b.entryIds.length,2);assert.equal(signedCost(s,b,accounts.unbilled),20000);validateState(s)})
test('later price notes correct a reconciled estimate without resurrecting the cleared liability',()=>{const {s,actor,accounts,receipt}=estimatedFixture(),invoice=receiptInvoice(s,receipt);postCosts(s,{date:'2026-10-04',reference:'Factura previa a nota',accounts},actor);purchaseNote(s,invoice,'credito',2000,'2026-10-05');const b=postCosts(s,{date:'2026-10-05',reference:'Bonificación posterior a factura conciliada',accounts},actor);assert.equal(b.balances.find(b=>b.sku==='REM-M-NEG').value,54000);assert.equal(signedCost(s,b,accounts.unbilled),0);assert.equal(signedCost(s,b,accounts.cogs),-200);assert.equal(b.corrections[0].amount,-2000);assert.deepEqual(b.settlements,[]);validateState(s)})
test('invoice reconciliation review and restoration reject modified estimates, source invoices, liabilities and lost settlement evidence',()=>{const {s,actor,accounts,receipt}=estimatedFixture(),invoice=receiptInvoice(s,receipt),close={date:'2026-10-04',reference:'Revisión de factura conciliada',accounts},preview=previewInventoryCost(s,close,s.inventoryCostBatches.at(-1)),before=structuredClone(s);assert.throws(()=>postInventoryCost(s,{...close,review:'alterada'},actor),/revisión/);assert.deepEqual(s,before);postCosts(s,close,actor);for(const change of [c=>c.inventoryCostBatches[1].receiptCosts[0].lines[0].value++,c=>c.inventoryCostBatches[1].receipts[0].estimatedValue++,c=>delete c.inventoryCostBatches[2].settlements,c=>c.inventoryCostBatches[2].settlements[0].difference++,c=>c.inventoryCostBatches[2].receipts[0].invoiceValue++,c=>c.documents.find(d=>d.id===invoice.id).date='2026-10-02',c=>c.entries.push({id:'rogue-liability',date:'2026-10-03',concept:'Ajeno',branchId:'central',documentId:'',lines:[{accountId:accounts.unbilled,debit:100,credit:0},{accountId:accounts.opening,debit:0,credit:100}]})]){const copy=structuredClone(s);change(copy);assert.throws(()=>validateState(copy))}assert.equal(preview.settlements[0].invoiceValue,22000);s.parties.find(p=>p.id===receipt.partyId).name='Renombrado';s.products.find(p=>p.id===receipt.lines[0].productId).sku='RENAME-RECEIPT';validateState(s)})
test('zero inventory after full disposal retains no residual value when late invoicing corrects all cost of sales',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const receipt=unbilledReceipt(s);customerDelivery(s,50,'2026-10-03');postCosts(s,{date:'2026-10-03',reference:'Toda la recepción consumida',accounts,receiptCosts:[receiptEstimate(receipt)]},actor);receiptInvoice(s,receipt,2400);const b=postCosts(s,{date:'2026-10-04',reference:'Factura después de consumir todo',accounts},actor);assert.equal(b.balances.find(b=>b.sku==='REM-M-NEG').value,0);assert.equal(signedCost(s,b,accounts.inventory),0);assert.equal(signedCost(s,b,accounts.cogs),4000);assert.equal(signedCost(s,b,accounts.unbilled),20000);validateState(s)})

test('late-issued-date supplier invoices preserve issue date, book after the conserved cutoff and cannot forge their cost timing',()=>{const {s,actor,accounts,receipt,batch}=estimatedFixture(),old=structuredClone(s.inventoryCostBatches),invoice=receiptInvoice(s,receipt,2200,'2026-10-02');assert.equal(invoice.date,'2026-10-02');assert.equal(invoice.inventoryCostDate,'2026-10-04');assert.equal(invoice.inventoryAfterBatchId,batch.id);assert.equal(s.entries.find(e=>e.documentId===invoice.id).date,'2026-10-04');validateState(s);assert.deepEqual(s.inventoryCostBatches,old);const b=postCosts(s,{date:'2026-10-04',reference:'Factura llegó después del corte',accounts},actor);assert.equal(b.settlements[0].date,'2026-10-02');assert.equal(b.settlements[0].recognitionDate,'2026-10-04');assert.equal(b.balances.find(b=>b.sku==='REM-M-NEG').value,55800);for(const mutate of [c=>c.documents.find(d=>d.id===invoice.id).inventoryCostDate='2026-10-05',c=>delete c.documents.find(d=>d.id===invoice.id).inventoryAfterBatchId,c=>{delete c.documents.find(d=>d.id===invoice.id).inventoryCostDate;delete c.documents.find(d=>d.id===invoice.id).inventoryAfterBatchId},c=>c.entries.find(e=>e.documentId===invoice.id).date='2026-10-02']){const copy=structuredClone(s);mutate(copy);assert.throws(()=>validateState(copy))}const f=estimatedFixture(),forged=engine.createDocument(f.s,{...f.receipt,kind:'factura',sourceId:f.receipt.id,date:'2026-10-02',due:'2026-10-02',lines:f.receipt.lines.map(l=>({...l,price:2200})),inventoryCostDate:'2099-01-01',inventoryAfterBatchId:'inventado'},'Administración');assert.equal(forged.inventoryCostDate,'2026-10-04');assert.equal(forged.inventoryAfterBatchId,f.batch.id)})
test('late purchase price notes preserve original document dates and recognize corrections after a legacy cost cutoff',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {invoice}=receivedPurchase(s,10,2000);customerDelivery(s,5,'2026-10-03');postCosts(s,{date:'2026-10-03',reference:'Venta anterior conservada',accounts},actor);for(const [i,b] of s.inventoryCostBatches.entries()){b.costVersion=4;b.review=inventoryCostReview(previewInventoryCost(s,{...b,costVersion:4},s.inventoryCostBatches[i-1],false))}const old=structuredClone(s.inventoryCostBatches),note=purchaseNote(s,invoice,'credito',2000,'2026-10-02');assert.equal(note.inventoryCostDate,'2026-10-04');assert.equal(s.entries.find(e=>e.documentId===note.id).date,'2026-10-04');validateState(s);assert.deepEqual(s.inventoryCostBatches,old);const b=postCosts(s,{date:'2026-10-04',reference:'Bonificación recibida tarde',accounts},actor);assert.equal(b.balances.find(b=>b.sku==='REM-M-NEG').value,52200);assert.equal(b.corrections[0].date,'2026-10-02');assert.equal(b.corrections[0].recognitionDate,'2026-10-04');validateState(s)})
test('a customer credit issued before the cost cutoff can link to physical goods returned later without recosting older snapshots',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {remit,invoice}=customerDelivery(s,5,'2026-10-02');postCosts(s,{date:'2026-10-03',reference:'Entrega cerrada',accounts},actor);const note=returnNote(s,invoice,2,'2026-10-02');registerStockReturn(s,returnInput(remit,2,'2026-10-04',note),actor);const b=postCosts(s,{date:'2026-10-04',reference:'Devolución posterior a nota emitida',accounts},actor);assert.equal(b.rows[0].value,2000);assert.equal(b.returnSources[0].noteDate,'2026-10-02');validateState(s)})
test('legacy openings cannot silently treat an omitted unbilled receipt as a new expense when its invoice arrives',()=>{const {s,actor,base,accounts}=costingFixture(),receipt=unbilledReceipt(s,10,'2026-10-01');base.opening=inventoryOpeningBalances(s,base.date).map(b=>({...b,value:b.quantity*1000}));base.receiptCosts=[receiptEstimate(receipt)];const b=postCosts(s,base,actor);b.costVersion=4;delete b.receiptCosts;delete b.receipts;delete b.settlements;const entry=s.entries.find(e=>e.inventoryBatchId===b.id);entry.lines=entry.lines.filter(l=>l.accountId!==accounts.unbilled);entry.lines.find(l=>l.accountId===accounts.opening).credit=70000;b.review=inventoryCostReview(previewInventoryCost(s,{...b,costVersion:4},undefined,false));validateState(s);receiptInvoice(s,receipt,2000,'2026-10-02');assert.throws(()=>postCosts(s,{date:'2026-10-02',reference:'Migración pendiente',accounts},actor),/devengamiento estimado/);validateState(s)})

test('customer goods returned before receipt invoicing share the corrected original delivery cost and cancel no supplier debt twice',()=>{
 const {s,actor,accounts,receipt,sale}=estimatedFixture(),note=returnNote(s,sale.invoice,2,'2026-10-04');registerStockReturn(s,returnInput(sale.remit,2,'2026-10-04',note),actor)
 postCosts(s,{date:'2026-10-04',reference:'Cliente devolvió mercadería estimada',accounts},actor);receiptInvoice(s,receipt,2200,'2026-10-05')
 const b=postCosts(s,{date:'2026-10-05',reference:'Factura después de venta y devolución',accounts},actor);assert.equal(b.balances.find(b=>b.sku==='REM-M-NEG').value,58280);assert.equal(signedCost(s,b,accounts.inventory),1880);assert.equal(signedCost(s,b,accounts.cogs),120);assert.equal(signedCost(s,b,accounts.unbilled),20000);validateState(s)
})
test('estimated opening receipts accept a subsequent price note only with its separate reviewed allocation',()=>{
 const {s,actor,base,accounts}=costingFixture(),receipt=unbilledReceipt(s,10,'2026-10-01'),p=s.products.find(p=>p.sku==='REM-M-NEG');base.opening=inventoryOpeningBalances(s,base.date).map(b=>({...b,value:b.quantity*1000}));base.receiptCosts=[receiptEstimate(receipt)];postCosts(s,base,actor)
 const invoice=receiptInvoice(s,receipt),openingInvoices=[{invoiceId:invoice.id,reference:'Todo identificado en apertura',lines:[{sourceProductId:p.id,target:'Existencias',productId:p.id,depositId:'principal',value:2000}]}]
 postCosts(s,{date:'2026-10-04',reference:'Factura de recepción migrada',accounts,openingInvoices},actor);const note=purchaseNote(s,invoice,'credito',2000,'2026-10-05');assert.throws(()=>postCosts(s,{date:'2026-10-05',reference:'Nota requiere reparto',accounts},actor),/asignación revisada/)
 const b=postCosts(s,{date:'2026-10-05',reference:'Nota después de conciliar apertura',accounts,openingNotes:[{noteId:note.id,reference:'Mismos bienes de la apertura',lines:[{sourceProductId:p.id,target:'Existencias',productId:p.id,depositId:'principal',value:2000}]}]},actor);assert.equal(b.balances.find(b=>b.productId===p.id).value,50000);assert.equal(signedCost(s,b,accounts.unbilled),0);assert.equal(signedCost(s,b,accounts.inventory),-2000);validateState(s)
})
test('supplier physical credits arriving after a conserved cutoff keep original issue date and link to later stock returns',()=>{
 const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const {remit,invoice}=receivedPurchase(s,10,2000);postCosts(s,{date:'2026-10-03',reference:'Compra conservada antes de devolución',accounts},actor)
 const note=returnNote(s,invoice,2,'2026-10-02');assert.equal(note.inventoryCostDate,'2026-10-04');registerStockReturn(s,returnInput(remit,2,'2026-10-04',note),actor)
 const b=postCosts(s,{date:'2026-10-04',reference:'Devolución con nota recibida después',accounts},actor);assert.equal(b.rows[0].value,2400);assert.equal(b.rows[0].creditValue,4000);assert.equal(b.returnSources[0].noteCostDate,'2026-10-04');assert.equal(signedCost(s,b,accounts.inventory),-2400);assert.equal(signedCost(s,b,accounts.adjustments),-1600);validateState(s)
})

test('mixed invoice differences assigned to one transformed opening pool validate the net value rather than an artificial line sequence',()=>{
 const {s,actor,base,accounts}=costingFixture(),p=s.products.find(p=>p.sku==='REM-M-NEG'),q=s.products.find(p=>p.sku==='PANT-42-AZ'),lines=[p,q].map((p,i)=>({productId:p.id,description:p.name,quantity:i?2:10,unit:p.unit,price:1000,tax:'21',discount:0})),receipt=unbilledReceipt(s,10,'2026-10-01',lines)
 base.opening=inventoryOpeningBalances(s,base.date).map(b=>({...b,value:100}));base.receiptCosts=[{receiptId:receipt.id,reference:'Costo original de dos componentes',lines:[{productId:p.id,value:20000},{productId:q.id,value:2000}]}];postCosts(s,base,actor)
 const invoice=receiptInvoice(s,receipt,0,'2026-10-02',[{...lines[0],price:1980},{...lines[1],price:1250}]),allocation={invoiceId:invoice.id,reference:'Componentes transformados en el mismo saldo de apertura',lines:[{sourceProductId:p.id,target:'Existencias',productId:p.id,depositId:'principal',value:200},{sourceProductId:q.id,target:'Existencias',productId:p.id,depositId:'principal',value:500}]}
 const b=postCosts(s,{date:'2026-10-02',reference:'Diferencias mixtas sobre apertura',accounts,openingInvoices:[allocation]},actor);assert.equal(b.balances.find(b=>b.productId===p.id).value,400);assert.equal(b.settlements[0].difference,300);assert.equal(signedCost(s,b,accounts.inventory),300);assert.equal(signedCost(s,b,accounts.unbilled),22000);validateState(s)
})

const {executeCommand}=require(join(dir,'commands.js'))
const {trialBalance}=require(join(dir,'trial-balance.js'))
const {previewAccountingClose,accountingCloseReview,closeAccountingPeriod}=require(join(dir,'accounting-close.js'))
function periodFixture(){const s=initialState(),actor={userId:'admin',name:'Revisora de cierres',role:'Administrador General',permissions:[]};s.settings.exerciseStart='2026-01-01';s.settings.exerciseEnd='2026-12-31';engine.addManualEntry(s,actor.role,'2026-01-10','Aporte inicial','central',[{accountId:'1.1.1',debit:10000,credit:0},{accountId:'3.1',debit:0,credit:10000}]);engine.addManualEntry(s,actor.role,'2026-02-05','Gasto de febrero','central',[{accountId:'5.1',debit:3000,credit:0},{accountId:'1.1.1',debit:0,credit:3000}]);return {s,actor}}
function reviewedPeriod(s,input){const preview=previewAccountingClose(s,input);return {...input,acknowledged:preview.warnings.map(w=>w.id),review:accountingCloseReview(preview)}}
test('trial balance carries previous balances into the selected period and reconciles opening, movement and closing separately',()=>{const {s}=periodFixture(),b=trialBalance(s,'2026-02-01','2026-02-28'),cash=b.rows.find(r=>r.accountId==='1.1.1');assert.deepEqual([cash.opening,cash.debit,cash.credit,cash.closing],[10000,0,3000,7000]);assert.equal(b.rows.find(r=>r.accountId==='3.1').closing,-10000);assert.equal(b.totals.openingDebit,10000);assert.equal(b.totals.openingCredit,10000);assert.equal(b.totals.debit,3000);assert.equal(b.totals.credit,3000);assert.equal(b.totals.closingDebit,10000);assert.equal(b.totals.closingCredit,10000)})
test('trial balance filters the opening and period consistently by branch and never includes future entries',()=>{const {s,actor}=periodFixture();s.masters.branches.push({id:'norte-period',name:'Norte',point:'2',active:true});engine.addManualEntry(s,actor.role,'2026-01-12','Aporte Norte','norte-period',[{accountId:'1.1.1',debit:5000,credit:0},{accountId:'3.1',debit:0,credit:5000}]);engine.addManualEntry(s,actor.role,'2026-03-01','Gasto futuro','central',[{accountId:'5.1',debit:1000,credit:0},{accountId:'1.1.1',debit:0,credit:1000}]);const b=trialBalance(s,'2026-02-01','2026-02-28','norte-period');assert.equal(b.rows.find(r=>r.accountId==='1.1.1').closing,5000);assert.equal(b.totals.debit,0);assert.equal(trialBalance(s,'2026-02-01','2026-02-28').rows.find(r=>r.accountId==='1.1.1').closing,12000)})
test('trial balance rejects impossible ranges, unknown branches, unsafe sums and malformed journals instead of presenting an apparently balanced report',()=>{const {s}=periodFixture();for(const [from,to,branch] of [['2026-02-30','2026-03-31','all'],['2026-02-01','2026-01-31','all'],['2025-12-01','2026-02-28','all'],['2026-02-01','2026-02-28','missing']])assert.throws(()=>trialBalance(s,from,to,branch));for(const change of [c=>c.entries[0].lines[0].credit=100,c=>c.entries[0].lines[0].accountId='missing',c=>c.entries[0].branchId='missing',c=>c.entries[0].lines[0].debit++,c=>c.entries[0].date='2026-02-30',c=>c.entries[0].date='abc',c=>c.entries.push({...c.entries[0]}),c=>{for(const e of c.entries)e.lines.forEach(l=>{if(l.debit)l.debit=Number.MAX_SAFE_INTEGER;if(l.credit)l.credit=Number.MAX_SAFE_INTEGER})}]){const copy=structuredClone(s);change(copy);assert.throws(()=>trialBalance(copy,'2026-01-01','2026-12-31'))}})
test('reviewed accounting close freezes cumulative journals, records actor and blocks past movements without changing any entries',()=>{const {s,actor}=periodFixture(),input=reviewedPeriod(s,{date:'2026-02-28',reference:'Febrero',reason:'Diario y devengamientos revisados',acknowledged:[]}),before=structuredClone(s.entries),close=closeAccountingPeriod(s,input,actor);assert.equal(close.number,'INT-CC-00000001');assert.equal(close.responsible,actor.name);assert.equal(s.settings.closedUntil,'2026-02-28');assert.deepEqual(s.entries,before);assert.equal(close.preview.sources.entries.length,2);assert.throws(()=>engine.addManualEntry(s,actor.role,'2026-02-28','Retroactivo','central',before[0].lines),/cerrado/);engine.addManualEntry(s,actor.role,'2026-03-01','Asiento posterior','central',before[0].lines);validateState(s)})
test('successive closures use the previous limit and preserve opening balances and prior constancias',()=>{const {s,actor}=periodFixture();closeAccountingPeriod(s,reviewedPeriod(s,{date:'2026-01-31',reference:'Enero',reason:'Revisión inicial',acknowledged:[]}),actor);const previous=structuredClone(s.accountingCloses[0]);const b=closeAccountingPeriod(s,reviewedPeriod(s,{date:'2026-02-28',reference:'Febrero',reason:'Revisión siguiente',acknowledged:[]}),actor);assert.equal(b.previousClosedUntil,'2026-01-31');assert.equal(b.preview.balance.from,'2026-02-01');assert.equal(b.preview.balance.rows.find(r=>r.accountId==='1.1.1').opening,10000);assert.equal(b.preview.balance.totals.debit,3000);assert.deepEqual(s.accountingCloses[0],previous);validateState(JSON.parse(JSON.stringify(s)))})
test('closing a legacy date lock records it as antecedent and does not invent its prior review',()=>{const {s,actor}=periodFixture();s.settings.closedUntil='2026-01-31';const c=closeAccountingPeriod(s,reviewedPeriod(s,{date:'2026-02-28',reference:'Primer cierre con constancia',reason:'Bloqueo anterior conservado',acknowledged:[]}),actor);assert.equal(c.previousClosedUntil,'2026-01-31');assert.equal(c.preview.balance.from,'2026-02-01');validateState(s)})
test('accounting closing rejects missing, altered or stale review and every rejection leaves state unchanged',()=>{const {s,actor}=periodFixture(),input=reviewedPeriod(s,{date:'2026-02-28',reference:'Febrero',reason:'Revisado',acknowledged:[]});for(const patch of [{review:undefined},{review:'alterada'},{reference:'Otra referencia'},{reason:'Otro fundamento'},{date:'2026-03-01'},{acknowledged:['inexistente']}]){const before=structuredClone(s);assert.throws(()=>closeAccountingPeriod(s,{...input,...patch},actor));assert.deepEqual(s,before)}engine.addManualEntry(s,actor.role,'2026-02-10','Nuevo gasto','central',[{accountId:'5.1',debit:100,credit:0},{accountId:'1.1.1',debit:0,credit:100}]);assert.throws(()=>closeAccountingPeriod(s,input,actor),/revisión/);assert.equal(s.accountingCloses.length,0)})
test('closure permissions, unique references, exact acknowledgment and valid temporal limits are mandatory',()=>{const {s,actor}=periodFixture(),input=reviewedPeriod(s,{date:'2026-02-28',reference:'Febrero',reason:'Revisado',acknowledged:[]});for(const role of ['Administración','Depósito','Producción','Personalizado'])assert.throws(()=>closeAccountingPeriod(s,input,{...actor,role,permissions:['/contabilidad/cierres']}),/Administrador/);for(const patch of [{date:'2026-02-30'},{date:'2027-01-01'},{reference:''},{reason:''}])assert.throws(()=>previewAccountingClose(s,{...input,...patch}));closeAccountingPeriod(s,input,actor);assert.throws(()=>previewAccountingClose(s,{...input,date:'2026-02-28'}),/posterior/);assert.throws(()=>closeAccountingPeriod(s,reviewedPeriod(s,{...input,date:'2026-03-31'}),actor),/referencia/);const end=reviewedPeriod(s,{date:'2026-12-31',reference:'Fin de ejercicio',reason:'Solo bloqueo operativo revisado',acknowledged:[]});assert.equal(end.acknowledged.includes('year-end'),true);assert.throws(()=>closeAccountingPeriod(s,{...end,acknowledged:[]},actor),/observaciones/);assert.throws(()=>closeAccountingPeriod(s,{...end,acknowledged:[...end.acknowledged,...end.acknowledged]},actor),/observaciones/);closeAccountingPeriod(s,end,actor);validateState(s)})
test('general closing requires an exact inventory cut and preserves estimated debts and unbilled delivery observations',()=>{const {s,actor,accounts}=estimatedFixture(),input={date:'2026-10-04',reference:'Octubre',reason:'Existencias y devengamientos revisados',acknowledged:[]};assert.throws(()=>previewAccountingClose(s,input),/exactamente/);postCosts(s,{date:input.date,reference:'Inventario exacto',accounts},actor);const reviewed=reviewedPeriod(s,input);assert.equal(reviewed.acknowledged.filter(id=>id.startsWith('unbilled:')).length,1);assert.equal(reviewed.acknowledged.filter(id=>id.startsWith('delivery:')).length,0);assert.ok(reviewed.acknowledged.includes('inventory-policy'));const c=closeAccountingPeriod(s,reviewed,actor);assert.equal(c.preview.inventoryBatchId,s.inventoryCostBatches.at(-1).id);validateState(s)})
test('delivered goods and supplier services without invoices are explicit closure observations',()=>{const {s,actor,base,accounts}=costingFixture();postCosts(s,base,actor);const delivered=customerDelivery(s,5,'2026-10-02');s.documents=s.documents.filter(d=>d.id!==delivered.invoice.id);s.entries=s.entries.filter(e=>e.documentId!==delivered.invoice.id);customerDelivery(s,1,'2026-10-02');const service={...s.products.find(p=>p.sku==='REM-M-NEG'),id:'service-close',sku:'SERV-CLOSE',name:'Servicio recibido',kind:'Servicio',parent:''};engine.saveProduct(s,service);unbilledReceipt(s,1,'2026-10-02',[{productId:service.id,description:service.name,quantity:1,unit:service.unit,price:1000,tax:'21',discount:0}]);postCosts(s,{date:'2026-10-03',reference:'Inventario para cierre',accounts},actor);const input=reviewedPeriod(s,{date:'2026-10-03',reference:'Cierre con servicio pendiente',reason:'Devengamiento manual revisado',acknowledged:[]});assert.ok(input.acknowledged.some(id=>id.startsWith('service:')));assert.ok(input.acknowledged.some(id=>id.startsWith('delivery:')));assert.ok(input.acknowledged.includes('fiscal-review'));closeAccountingPeriod(s,input,actor);validateState(s)})
test('restoration detects altered sources, balance, review, observation, sequence and date lock in a conserved closure',()=>{const {s,actor}=periodFixture();closeAccountingPeriod(s,reviewedPeriod(s,{date:'2026-02-28',reference:'Febrero',reason:'Revisado',acknowledged:[]}),actor);for(const change of [c=>c.entries[0].lines[0].debit++,c=>c.entries[0].concept='Otro concepto',c=>c.entries.pop(),c=>c.accountingCloses[0].preview.balance.rows[0].closing++,c=>c.accountingCloses[0].preview.sources.entries=[],c=>c.accountingCloses[0].review='alterada',c=>c.accountingCloses[0].reference='Otro cierre',c=>c.accountingCloses[0].previousClosedUntil='2026-01-31',c=>c.settings.closedUntil='',c=>delete c.accountingCloses,c=>c.accountingCloses=[],c=>c.accountingCloses.push({...c.accountingCloses[0]}),c=>c.accountingCloses[0].acknowledged=['inventada']]){const copy=structuredClone(s);change(copy);assert.throws(()=>validateState(copy))}})
test('future account and branch additions, label edits and bank reconciliation do not rewrite a previous financial closure',()=>{const {s,actor}=periodFixture();s.treasuryMoves.push({id:'bank-close',date:'2026-02-10',treasuryId:'banco-demo',branchId:'central',amount:100,reason:'Movimiento sintético',documentId:'',reconciled:false});closeAccountingPeriod(s,reviewedPeriod(s,{date:'2026-02-28',reference:'Febrero',reason:'Revisado',acknowledged:[]}),actor);const previous=structuredClone(s.accountingCloses[0]);engine.saveMaster(s,'accounts',{id:'new-close-account',code:'5.99',name:'Nuevo gasto',group:'Gastos',postable:true},actor.role);engine.saveMaster(s,'accounts',{...s.masters.accounts.find(a=>a.id==='1.1.1'),name:'Caja renombrada',code:'1.1.01'},actor.role);s.masters.branches.push({id:'future-branch',name:'Sucursal futura',point:'3',active:true});s.treasuryMoves[0].reconciled=true;validateState(s);assert.deepEqual(s.accountingCloses[0],previous);assert.throws(()=>engine.saveMaster(s,'accounts',{...s.masters.accounts.find(a=>a.id==='1.1.1'),group:'Gastos'},actor.role),/grupo/);const copy=structuredClone(s);copy.masters.accounts.find(a=>a.id==='1.1.1').group='Gastos';assert.throws(()=>validateState(copy),/balance/)} )
test('settings commands cannot silently advance or reopen the accounting lock and valid company changes preserve it',async()=>{const {s,actor}=periodFixture();for(const closedUntil of ['2026-01-31','2026-02-28'])await assert.rejects(executeCommand(s,actor,{type:'settings.save',settings:{...s.settings,closedUntil}}),/Cierres/);closeAccountingPeriod(s,reviewedPeriod(s,{date:'2026-02-28',reference:'Febrero',reason:'Revisado',acknowledged:[]}),actor);await assert.rejects(executeCommand(s,actor,{type:'settings.save',settings:{...s.settings,closedUntil:''}}),/Cierres/);await executeCommand(s,actor,{type:'settings.save',settings:{...s.settings,name:'Nombre editable'}});assert.equal(s.settings.closedUntil,'2026-02-28');validateState(s)})

test('closed financial documents, inventory and treasury cannot be modified or hidden behind malformed dates',()=>{const {s,actor,accounts}=estimatedFixture();postCosts(s,{date:'2026-10-04',reference:'Corte para proteger fuentes',accounts},actor);s.treasuryMoves.push({id:'close-cash-source',date:'2026-10-04',treasuryId:'caja-demo',branchId:'central',amount:100,reason:'Fuente sintética',documentId:'',reconciled:false});closeAccountingPeriod(s,reviewedPeriod(s,{date:'2026-10-04',reference:'Fuentes conservadas',reason:'Control sintético del período',acknowledged:[]}),actor);for(const change of [c=>c.documents[0].total++,c=>c.stockMoves[0].quantity++,c=>c.treasuryMoves[0].amount++,c=>c.documents[0].date='abc',c=>c.stockMoves[0].date='abc',c=>c.treasuryMoves[0].date='abc']){const copy=structuredClone(s);change(copy);assert.throws(()=>validateState(copy))}validateState(JSON.parse(JSON.stringify(s)))})

const {previewServiceAccrual,previewServiceSettlement,previewServiceReestimate,serviceEstimate,serviceReview,accrueService,settleService,reestimateService,prepareServiceAccounts}=require(join(dir,'service-accruals.js'))
const {previewServiceCancellation,cancelService,serviceAccrualActive}=require(join(dir,'service-accruals.js'))
function serviceFixture(){const s=fixture(),actor={userId:'service-test',name:'Revisora de servicios',role:'Administrador General',permissions:[]};s.stockMoves=[];s.settings.exerciseStart='2026-01-01';s.settings.exerciseEnd='2026-12-31';prepareServiceAccounts(s,actor);s.masters.accounts.push({id:'5.8',code:'5.8',name:'Limpieza',group:'Gastos',postable:true});const products=[{...s.products[2],id:'clean',sku:'CLEAN',name:'Limpieza',kind:'Servicio',parent:''},{...s.products[2],id:'repair',sku:'REPAIR',name:'Reparación',kind:'Servicio',parent:''}];products.forEach(p=>engine.saveProduct(s,p));const supplier=s.parties.find(p=>p.side==='proveedor'),receipt=engine.createDocument(s,input(s,'remito',{side:'proveedor',partyId:supplier.id,date:'2026-10-01',due:'2026-10-01',letter:'X',lines:products.map((p,i)=>({productId:p.id,description:p.name,quantity:i?1:2,unit:p.unit,price:5000,tax:'21',discount:0}))}),actor.role),accrual={date:'2026-10-03',sourceId:receipt.id,reference:'Contrato recibido',reason:'Servicios consumidos, importe respaldado por contrato sintético',liabilityId:'2.1.7',lines:[{productId:'clean',value:10000,accountId:'5.8'},{productId:'repair',value:5000,accountId:'5.1'}]},invoice=(date='2026-10-05',prices=[6000,4000],letter='A')=>engine.createDocument(s,{...receipt,kind:'factura',date,due:date,letter,sourceId:receipt.id,lines:receipt.lines.map((l,i)=>({...l,price:prices[i]}))},actor.role);return {s,actor,receipt,accrual,invoice}}
function reviewedService(s,input,settlement=false){return {...input,review:serviceReview((settlement?previewServiceSettlement:previewServiceAccrual)(s,input))}}
function serviceBalance(s,id){return s.entries.flatMap(e=>e.lines).filter(l=>l.accountId===id).reduce((n,l)=>n+l.debit-l.credit,0)}
function serviceSettlement(s,a,d,date=d.date){return reviewedService(s,{date,accrualId:a.id,invoiceId:d.id,reference:'Conciliación de factura',reason:'Importe y cuentas revisados'},true)}
test('reviewed services accrue expenses and a separate liability without VAT, supplier debt, stock or treasury',()=>{const {s,actor,accrual}=serviceFixture(),before=structuredClone(s),a=accrueService(s,reviewedService(s,accrual),actor);assert.equal(a.number,'INT-DS-00000001');assert.equal(a.responsible,actor.name);assert.equal(a.preview.total,15000);assert.equal(serviceBalance(s,'5.8'),10000);assert.equal(serviceBalance(s,'5.1'),5000);assert.equal(serviceBalance(s,'2.1.7'),-15000);assert.equal(serviceBalance(s,'1.1.4'),0);assert.deepEqual(s.documents,before.documents);assert.deepEqual(s.stockMoves,before.stockMoves);assert.deepEqual(s.treasuryMoves,before.treasuryMoves);validateState(JSON.parse(JSON.stringify(s)))})
test('service review rejects stale amounts, missing review, duplicate articles, unsupported accounts and inaccessible operations atomically',()=>{const {s,actor,accrual}=serviceFixture(),review=reviewedService(s,accrual);for(const patch of [{review:undefined},{reason:'Otra causa'},{lines:[{...accrual.lines[0],value:9999}]},{lines:[accrual.lines[0],accrual.lines[0]]},{liabilityId:'2.1.1'},{liabilityId:'1.1.1'},{lines:[{...accrual.lines[0],accountId:'1.1.1'}]},{date:'2026-09-30'},{date:'2026-02-30'},{lines:[{...accrual.lines[0],value:Number.MAX_SAFE_INTEGER},accrual.lines[1]]}]){const before=structuredClone(s);assert.throws(()=>accrueService(s,{...review,...patch},actor));assert.deepEqual(s,before)}for(const role of ['Depósito','Producción','Personalizado'])assert.throws(()=>accrueService(s,review,{...actor,role,permissions:[]}),/permiso/);assert.throws(()=>prepareServiceAccounts(s,{...actor,role:'Administración'}),/Administrador/);accrueService(s,review,{...actor,role:'Personalizado',permissions:['/contabilidad/servicios-devengados']});validateState(s)})
test('partial selection accrues each service once and reconciles separate constancias against one mixed invoice',()=>{const {s,actor,accrual,invoice}=serviceFixture(),first={...accrual,lines:[accrual.lines[0]]},a=accrueService(s,reviewedService(s,first),actor);assert.throws(()=>previewServiceAccrual(s,first),/ya tiene/);const second={...accrual,reference:'Segundo servicio',lines:[accrual.lines[1]]},b=accrueService(s,reviewedService(s,second),actor),d=invoice();settleService(s,serviceSettlement(s,a,d),actor);settleService(s,{...serviceSettlement(s,b,d),reference:'Otra conciliación',review:serviceReview(previewServiceSettlement(s,{date:d.date,accrualId:b.id,invoiceId:d.id,reference:'Otra conciliación',reason:'Importe y cuentas revisados'}))},actor);assert.equal(serviceBalance(s,'2.1.7'),0);assert.equal(serviceBalance(s,'5.8'),12000);assert.equal(serviceBalance(s,'5.1'),4000);validateState(s)})
test('service settlement reverses the original invoice expense and preserves invoice VAT, supplier balance and previous accrual',()=>{const {s,actor,accrual,invoice}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor),prior=structuredClone(a),d=invoice(),original=structuredClone(s.entries.find(e=>e.documentId===d.id)),record=settleService(s,serviceSettlement(s,a,d),actor);assert.equal(record.number,'INT-CS-00000001');assert.equal(record.preview.estimatedValue,15000);assert.equal(record.preview.invoiceValue,16000);assert.equal(record.preview.difference,1000);assert.equal(serviceBalance(s,'5.8'),12000);assert.equal(serviceBalance(s,'5.1'),4000);assert.equal(serviceBalance(s,'2.1.7'),0);assert.equal(serviceBalance(s,'1.1.4'),3360);assert.equal(serviceBalance(s,'2.1.1'),-19360);assert.deepEqual(s.serviceAccruals[0],prior);assert.deepEqual(s.entries.find(e=>e.id===original.id),original);validateState(s)})
test('service settlement handles reductions and free service lines without leaving estimated debt or duplicate expenses',()=>{for(const prices of [[2000,1000],[0,1000]]){const {s,actor,accrual,invoice}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor),d=invoice('2026-10-05',prices),c=settleService(s,serviceSettlement(s,a,d),actor);assert.equal(c.preview.difference,prices[0]*2+prices[1]-15000);assert.equal(serviceBalance(s,'5.8'),prices[0]*2);assert.equal(serviceBalance(s,'5.1'),prices[1]);assert.equal(serviceBalance(s,'2.1.7'),0);validateState(s)}})
test('nonrecoverable invoice VAT remains part of the service expense and never becomes a tax credit',()=>{const {s,actor,accrual,invoice}=serviceFixture();s.settings.iva='Exento';const a=accrueService(s,reviewedService(s,accrual),actor),d=invoice('2026-10-05',[6000,4000],'B'),c=settleService(s,serviceSettlement(s,a,d),actor);assert.equal(c.preview.invoiceValue,16000);assert.equal(serviceBalance(s,'5.8'),12000);assert.equal(serviceBalance(s,'5.1'),4000);assert.equal(serviceBalance(s,'1.1.4'),0);assert.equal(serviceBalance(s,'2.1.1'),-16000);validateState(s)})
test('service reconciliation uses the invoice original expense account after automatic mappings change',()=>{const {s,actor,accrual,invoice}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor),d=invoice();s.masters.accounts.push({id:'5.9',code:'5.9',name:'Nuevas compras',group:'Gastos',postable:true});s.settings.accountMap.purchases='5.9';const c=settleService(s,serviceSettlement(s,a,d),actor);assert.equal(c.preview.purchaseAccountId,'5.1');assert.equal(serviceBalance(s,'5.9'),0);assert.equal(serviceBalance(s,'5.1'),4000);s.masters.accounts.find(a=>a.id==='5.8').postable=false;validateState(s)})
test('service accruals survive an earlier accounting close and invoiced estimates must be reconciled before the next close',()=>{const {s,actor,accrual,invoice}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor),input={date:'2026-10-04',reference:'Cierre de servicios estimados',reason:'Deuda pendiente revisada',acknowledged:[]},p=previewAccountingClose(s,input);assert.ok(p.warnings.some(w=>w.id===`service-accrual:${a.id}`));assert.ok(!p.warnings.some(w=>w.id.startsWith('service:')));closeAccountingPeriod(s,reviewedPeriod(s,input),actor);const closed=structuredClone(s.accountingCloses[0]),d=invoice();validateState(s);assert.throws(()=>previewAccountingClose(s,{...input,date:'2026-10-05'}),/Conciliá/);settleService(s,serviceSettlement(s,a,d),actor);closeAccountingPeriod(s,reviewedPeriod(s,{...input,date:'2026-10-05',reference:'Cierre conciliado'}),actor);assert.deepEqual(s.accountingCloses[0],closed);validateState(JSON.parse(JSON.stringify(s)))})
test('service constancias reject altered source quantities, snapshots, journal links and missing collections on recovery',()=>{const {s,actor,accrual,invoice}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor),d=invoice();settleService(s,serviceSettlement(s,a,d),actor);for(const change of [c=>c.documents[0].lines[0].quantity++,c=>c.serviceAccruals[0].lines[0].value++,c=>c.serviceAccruals[0].preview.total++,c=>c.serviceSettlements[0].preview.difference++,c=>c.serviceSettlements[0].review='otro',c=>{const original=c.entries.find(e=>e.documentId===d.id);c.entries.push({...original,id:'duplicated-service-invoice'})},c=>c.entries.find(e=>e.serviceRecordId).concept='Cambio',c=>c.entries.find(e=>e.serviceRecordId).serviceRecordId='ausente',c=>delete c.serviceAccruals,c=>delete c.serviceSettlements,c=>c.serviceAccruals=null,c=>c.serviceSettlements.push({...c.serviceSettlements[0]})]){const copy=structuredClone(s);change(copy);assert.throws(()=>validateState(copy))}validateState(s)})
test('service settlement rejects premature dates, wrong invoice, stale review and duplicate reconciliation without mutation',()=>{const {s,actor,accrual,invoice}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor),d=invoice(),review=serviceSettlement(s,a,d);for(const patch of [{date:'2026-10-04'},{invoiceId:'missing'},{accrualId:'missing'},{review:undefined},{reference:'Otro fundamento'}]){const before=structuredClone(s);assert.throws(()=>settleService(s,{...review,...patch},actor));assert.deepEqual(s,before)}settleService(s,review,actor);assert.throws(()=>settleService(s,review,actor),/ya fue/);assert.throws(()=>previewServiceAccrual(s,accrual),/ya tiene factura/);s.settings.closedUntil='2026-10-05';assert.throws(()=>previewServiceSettlement(s,review),/cerrado/)})
test('mixed physical goods and services accrue and reconcile only the selected services',()=>{const {s,actor,accrual,receipt,invoice}=serviceFixture(),p=s.products.find(p=>p.sku==='REM-M-NEG');receipt.lines.push({productId:p.id,description:p.name,quantity:3,unit:p.unit,price:1000,tax:'21',discount:0});s.stockMoves.push({id:'mixed-service-goods',date:receipt.date,productId:p.id,depositId:receipt.depositId,quantity:3,reason:receipt.number,documentId:receipt.id,branchId:receipt.branchId});const before=structuredClone(s.stockMoves),a=accrueService(s,reviewedService(s,accrual),actor);assert.throws(()=>previewServiceAccrual(s,{...accrual,lines:[{productId:p.id,value:1000,accountId:'5.1'}]}),/servicios/);prepareInventoryAccounts(s,actor);const accounts=inventoryAccountDefaults(s);postCosts(s,{date:'2026-10-01',reference:'Apertura de recepción mixta',accounts,opening:inventoryOpeningBalances(s,'2026-10-01').map(b=>({...b,value:b.quantity*1000})),receiptCosts:[{receiptId:receipt.id,reference:'Contrato de mercadería separado de servicios',lines:[{productId:p.id,value:3000}]}]},actor);postCosts(s,{date:'2026-10-03',reference:'Corte previo de recepción mixta',accounts},actor);const d=invoice('2026-10-02',[6000,4000,1000]);assert.equal(d.inventoryCostDate,'2026-10-04');const cp={date:'2026-10-03',reference:'Cierre antes del registro de factura mixta',reason:'Mercadería y servicios estimados',acknowledged:[]};assert.ok(previewAccountingClose(s,cp).warnings.some(w=>w.id===`service-accrual:${a.id}`));closeAccountingPeriod(s,reviewedPeriod(s,cp),actor);const closed=structuredClone(s.accountingCloses[0]);settleService(s,serviceSettlement(s,a,d,'2026-10-04'),actor);postCosts(s,{date:'2026-10-04',reference:'Factura de recepción mixta conciliada',accounts,openingInvoices:[{invoiceId:d.id,reference:'Mercadería de apertura sin diferencia; servicios conciliados por separado',lines:[{sourceProductId:p.id,target:'Existencias',productId:p.id,depositId:'principal',value:0}]}]},actor);assert.equal(serviceBalance(s,'5.8'),12000);assert.equal(serviceBalance(s,'5.1'),4000);assert.equal(serviceBalance(s,accounts.inventory),3000);assert.equal(serviceBalance(s,accounts.unbilled),0);assert.deepEqual(s.accountingCloses[0],closed);assert.deepEqual(s.stockMoves,before);validateState(s)})
function serviceRevision(s,a,lines=[{productId:'clean',value:13000},{productId:'repair',value:3000}],date='2026-10-04',reference='Información nueva del contrato'){const input={date,accrualId:a.id,reference,reason:'Nueva información documentada: importe actualizado de los servicios consumidos',lines};return {...input,review:serviceReview(previewServiceReestimate(s,input))}}
test('service reestimation posts only new expense differences and preserves original source, debt and accrual',()=>{const {s,actor,accrual}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor),before=structuredClone(s),r=reestimateService(s,serviceRevision(s,a),actor);assert.equal(r.number,'INT-RS-00000001');assert.equal(r.responsible,actor.name);assert.equal(r.preview.previousValue,15000);assert.equal(r.preview.total,16000);assert.equal(r.preview.difference,1000);assert.equal(serviceBalance(s,'5.8'),13000);assert.equal(serviceBalance(s,'5.1'),3000);assert.equal(serviceBalance(s,'2.1.7'),-16000);assert.equal(serviceBalance(s,'1.1.4'),0);assert.deepEqual(s.serviceAccruals,before.serviceAccruals);assert.deepEqual(s.documents,before.documents);assert.deepEqual(s.stockMoves,before.stockMoves);assert.deepEqual(s.treasuryMoves,before.treasuryMoves);assert.deepEqual(s.entries[0],before.entries[0]);assert.equal(serviceEstimate(s,a,'2026-10-03').total,15000);assert.equal(serviceEstimate(s,a,'2026-10-04').total,16000);validateState(s)})
test('multiple service reestimations accumulate increases and reductions and the invoice clears the updated liability',()=>{const {s,actor,accrual,invoice}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor),first=reestimateService(s,serviceRevision(s,a),actor),second=reestimateService(s,serviceRevision(s,a,[{productId:'clean',value:8000},{productId:'repair',value:4000}],'2026-10-04','Nueva revisión del contrato'),actor);assert.equal(second.preview.previousReestimateId,first.id);assert.equal(second.preview.difference,-4000);assert.equal(serviceBalance(s,'2.1.7'),-12000);const d=invoice(),p=serviceSettlement(s,a,d),r=settleService(s,p,actor);assert.deepEqual(r.preview.reestimateIds,[first.id,second.id]);assert.equal(r.preview.estimatedValue,12000);assert.equal(r.preview.difference,4000);assert.equal(serviceBalance(s,'5.8'),12000);assert.equal(serviceBalance(s,'5.1'),4000);assert.equal(serviceBalance(s,'2.1.7'),0);assert.equal(serviceBalance(s,'1.1.4'),3360);assert.equal(serviceBalance(s,'2.1.1'),-19360);validateState(JSON.parse(JSON.stringify(s)))})
test('service reestimation permits an expense redistribution with zero net liability change',()=>{const {s,actor,accrual}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor),r=reestimateService(s,serviceRevision(s,a,[{productId:'clean',value:12000},{productId:'repair',value:3000}]),actor);assert.equal(r.preview.difference,0);assert.equal(r.preview.entry.length,2);assert.equal(serviceBalance(s,'2.1.7'),-15000);assert.equal(serviceBalance(s,'5.8'),12000);assert.equal(serviceBalance(s,'5.1'),3000);validateState(s)})
test('closed service estimates retain their original balance when new information and invoices arrive later',()=>{const {s,actor,accrual,invoice}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor);closeAccountingPeriod(s,reviewedPeriod(s,{date:'2026-10-03',reference:'Cierre con estimación inicial',reason:'Información disponible a esa fecha',acknowledged:[]}),actor);const prior=structuredClone(s.accountingCloses[0]);reestimateService(s,serviceRevision(s,a),actor);closeAccountingPeriod(s,reviewedPeriod(s,{date:'2026-10-04',reference:'Cierre con información nueva',reason:'Nueva medición documentada',acknowledged:[]}),actor);const second=structuredClone(s.accountingCloses[1]);assert.equal(second.preview.services.reestimates.length,1);const d=invoice();settleService(s,serviceSettlement(s,a,d),actor);assert.deepEqual(s.accountingCloses[0],prior);assert.deepEqual(s.accountingCloses[1],second);validateState(s);const copy=structuredClone(s);copy.serviceReestimates[0].reason='Documento distinto';assert.throws(()=>validateState(copy))})
test('service reestimation rejects invalid scopes, periods, zero obligations, stale reviews and unauthorized actors without mutation',()=>{const {s,actor,accrual}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor),p=serviceRevision(s,a);for(const patch of [{accrualId:'missing'},{date:'2026-10-02'},{reason:''},{lines:[]},{lines:[p.lines[0],p.lines[0]]},{lines:[{productId:'clean',value:-1},p.lines[1]]},{lines:[{productId:'clean',value:Number.MAX_SAFE_INTEGER},p.lines[1]]},{lines:[{productId:'clean',value:0},{productId:'repair',value:0}]},{lines:accrual.lines},{review:undefined},{reason:'Cambio tras la revisión'}]){const before=structuredClone(s);assert.throws(()=>reestimateService(s,{...p,...patch},actor));assert.deepEqual(s,before)}assert.throws(()=>reestimateService(s,p,{...actor,role:'Depósito'}),/permiso/);reestimateService(s,p,{...actor,role:'Personalizado',permissions:['/contabilidad/servicios-devengados']});const before=structuredClone(s);assert.throws(()=>reestimateService(s,p,actor));assert.deepEqual(s,before);s.settings.closedUntil='2026-10-04';assert.throws(()=>previewServiceReestimate(s,p),/cerrado/)})
test('service invoice reconciliation uses the latest revision and refuses backdating before it',()=>{const {s,actor,accrual,invoice}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor);reestimateService(s,serviceRevision(s,a,undefined,'2026-10-06'),actor);const d=invoice('2026-10-05'),before=structuredClone(s);assert.throws(()=>serviceSettlement(s,a,d),/reestimación/);assert.throws(()=>previewServiceReestimate(s,serviceRevision(s,a)),/preceder/);assert.deepEqual(s,before);settleService(s,serviceSettlement(s,a,d,'2026-10-06'),actor);assert.throws(()=>previewServiceReestimate(s,{date:'2026-10-07',accrualId:a.id,reference:'Revisión tardía',reason:'No corresponde',lines:[{productId:'clean',value:1000},{productId:'repair',value:2000}]}),/factura o conciliación/);validateState(s)})
test('restored service reestimations reject missing records, altered predecessors, values and linked journals',()=>{const {s,actor,accrual}=serviceFixture(),a=accrueService(s,reviewedService(s,accrual),actor);reestimateService(s,serviceRevision(s,a),actor);reestimateService(s,serviceRevision(s,a,[{productId:'clean',value:14000},{productId:'repair',value:2000}],'2026-10-04','Información posterior'),actor);for(const change of [c=>delete c.serviceReestimates,c=>c.serviceReestimates=null,c=>c.serviceReestimates.reverse(),c=>c.serviceReestimates[1].preview.previousReestimateId='missing',c=>c.serviceReestimates[0].lines[0].value++,c=>c.serviceReestimates[0].preview.total++,c=>c.entries.find(e=>e.serviceRecordId===c.serviceReestimates[0].id).lines[0].debit++,c=>c.serviceReestimates.push({...c.serviceReestimates[0]})]){const copy=structuredClone(s);change(copy);assert.throws(()=>validateState(copy))}validateState(s)})

const {previewYearEndClose,yearEndReview,closeYearEnd,prepareYearEndAccount}=require(join(dir,'year-end-close.js'))
function yearEndFixture(){const {s,actor}=serviceFixture();s.documents=[];s.entries=[];s.serviceAccruals=[];prepareYearEndAccount(s,actor);s.masters.branches.push({id:'annual-north',name:'Sucursal anual',active:true});engine.addManualEntry(s,actor.role,'2026-10-01','Ingresos sintéticos','central',[{accountId:'1.1.1',debit:100000,credit:0},{accountId:'4.1',debit:0,credit:100000}]);engine.addManualEntry(s,actor.role,'2026-10-02','Gastos sintéticos','central',[{accountId:'5.1',debit:35000,credit:0},{accountId:'1.1.1',debit:0,credit:35000}]);engine.addManualEntry(s,actor.role,'2026-10-02','Pérdida de sucursal','annual-north',[{accountId:'5.8',debit:10000,credit:0},{accountId:'2.1.1',debit:0,credit:10000}]);return {s,actor}}
function reviewedYear(s,patch={}){const input={reference:'Cierre de resultados sintéticos 2026',reason:'Saldos nominales y revisiones del ejercicio documentados',resultsAccountId:'3.2',acknowledged:[],...patch},p=previewYearEndClose(s,input);return {...input,acknowledged:p.before.warnings.map(w=>w.id),review:yearEndReview(p)}}
test('year-end close transfers profit and loss by branch, zeros every result balance and atomically blocks the company',()=>{const {s,actor}=yearEndFixture(),before=structuredClone(s),c=closeYearEnd(s,reviewedYear(s),actor);assert.equal(c.number,'INT-CR-00000001');assert.equal(c.preview.result,55000);assert.equal(c.preview.branches.find(b=>b.id==='central').result,65000);assert.equal(c.preview.branches.find(b=>b.id==='annual-north').result,-10000);assert.equal(c.entryIds.length,2);assert.equal(c.responsible,actor.name);assert.equal(serviceBalance(s,'3.2'),-55000);assert.equal(serviceBalance(s,'4.1'),0);assert.equal(serviceBalance(s,'5.1'),0);assert.equal(serviceBalance(s,'5.8'),0);assert.ok(c.after.rows.filter(r=>['Ingresos','Gastos'].includes(r.group)).every(r=>r.closing===0));assert.equal(c.preview.annual.rows.find(r=>r.accountId==='4.1').closing,-100000);assert.equal(s.settings.closedUntil,'2026-12-31');assert.equal(s.settings.accountingCloseId,c.accountingCloseId);assert.equal(s.accountingCloses[0].preview.resultsClose.result,55000);assert.deepEqual(s.documents,before.documents);assert.deepEqual(s.stockMoves,before.stockMoves);assert.deepEqual(s.treasuryMoves,before.treasuryMoves);assert.deepEqual(s.entries.slice(0,before.entries.length),before.entries);assert.throws(()=>engine.addManualEntry(s,actor.role,'2026-12-31','No permitido','central',before.entries[0].lines),/cerrado/);validateState(JSON.parse(JSON.stringify(s)))})
test('year-end closes zero net results without inventing an equity amount and permits an empty exercise',()=>{const {s,actor}=yearEndFixture();s.entries=s.entries.filter(e=>e.branchId==='central');s.entries[1].lines=s.entries[1].lines.map(l=>l.debit?{...l,debit:100000}:{...l,credit:100000});const c=closeYearEnd(s,reviewedYear(s),actor);assert.equal(c.preview.result,0);assert.equal(c.entryIds.length,1);assert.equal(s.entries.at(-1).lines.length,2);assert.equal(serviceBalance(s,'3.2'),0);validateState(s);const empty=yearEndFixture();empty.s.entries=[];const e=closeYearEnd(empty.s,reviewedYear(empty.s),empty.actor);assert.equal(e.preview.result,0);assert.equal(e.entryIds.length,0);assert.equal(empty.s.accountingCloses.length,1);validateState(empty.s)})
test('year-end close includes unusual debit income and credit expense balances with exact signs',()=>{const {s,actor}=yearEndFixture();s.entries=[];engine.addManualEntry(s,actor.role,'2026-10-01','Ingresos reversados','central',[{accountId:'4.1',debit:12000,credit:0},{accountId:'1.1.1',debit:0,credit:12000}]);engine.addManualEntry(s,actor.role,'2026-10-02','Gastos reversados','central',[{accountId:'2.1.1',debit:6000,credit:0},{accountId:'5.1',debit:0,credit:6000}]);const c=closeYearEnd(s,reviewedYear(s),actor);assert.equal(c.preview.result,-6000);assert.equal(serviceBalance(s,'3.2'),6000);assert.equal(serviceBalance(s,'4.1'),0);assert.equal(serviceBalance(s,'5.1'),0);validateState(s)})
