const {previewAssetDisposal,disposeAsset,prepareAssetDisposalAccounts,assetDisposalReview}=require(join(dir,'asset-disposals.js'))
function assetExitFixture(options={}){const f=assetFixture(options);prepareAssetDisposalAccounts(f.s,f.actor);f.a=acquireFixedAsset(f.s,reviewedAsset(f.s,f.asset),f.actor);return f}
function assetSale(f,{date='2026-10-10',price=80000,branchId='central',lines,sourceId=''}={}){return engine.createDocument(f.s,{...f.invoice,side:'cliente',partyId:f.s.parties.find(p=>p.side==='cliente').id,date,due:date,branchId,sourceId,lines:lines||[{...f.invoice.lines[0],price}]},f.actor.role)}
function reviewedAssetExit(f,{date='2026-10-10',kind='Venta',invoiceId='',reference='Baja de prueba',...patch}={}){const i={date,assetId:f.a.id,kind,invoiceId,reference,reason:'Acta sintética de transferencia o pérdida de control completa a la fecha indicada',expenseAccountId:'5.10',incomeAccountId:kind==='Venta'?'4.9':'',controlConfirmed:true,...patch};return {...i,review:assetDisposalReview(previewAssetDisposal(f.s,i))}}
test('asset sale derecognizes cost and accumulated depreciation, reclassifies net revenue and preserves VAT, source debt and cash',()=>{
 const f=assetExitFixture(),sale=assetSale(f);postDepreciation(f.s,reviewedDep(f.s),f.actor);const before=structuredClone(f.s),b=disposeAsset(f.s,reviewedAssetExit(f,{invoiceId:sale.id}),f.actor)
 assert.equal(b.number,'INT-BA-00000001');assert.equal(b.preview.cost,100000);assert.equal(b.preview.accumulated,30000);assert.equal(b.preview.bookValue,70000);assert.equal(b.preview.netSale,80000);assert.equal(b.preview.result,10000);assert.equal(b.entryIds.length,1)
 for(const [id,v]of [['1.2.1',0],['1.2.2',0],['5.9',30000],['5.10',70000],['4.9',-80000],['4.1',0],['1.1.4',21000],['2.1.1',-121000]])assert.equal(serviceBalance(f.s,id),v)
 assert.deepEqual(f.s.documents,before.documents);assert.deepEqual(f.s.treasuryMoves,before.treasuryMoves);assert.deepEqual(f.s.stockMoves,before.stockMoves);assert.deepEqual(f.s.entries.slice(0,-1),before.entries);assert.deepEqual(f.s.fixedAssets,before.fixedAssets);assert.deepEqual(f.s.depreciationBatches,before.depreciationBatches);assert.equal(depreciationRows(f.s,'2026-10-11')[0].bookValue,0);assert.equal(depreciationRows(f.s,'2026-12-31')[0].charge,0);assert.equal(depreciationRows(f.s,'2026-10-10')[0].bookValue,70000);validateState(JSON.parse(JSON.stringify(f.s)))
})
