test('reexpression continuity and annual comparatives preserve prior adjusted sources and bring all states into current currency',()=>{
 const s=initialState(),actor={name:'Preparador',userId:'admin',role:'Administrador General',permissions:[]};s.settings.exerciseStart='2025-01-01';s.settings.exerciseEnd='2025-12-31';s.masters.accounts.push({id:'3.2',code:'3.2',name:'Resultados no asignados',group:'Patrimonio neto',postable:true});s.entries=[{id:'open-prior',date:'2024-12-31',concept:'Apertura previa',branchId:'central',documentId:'',manual:true,lines:[{accountId:'1.1.2',debit:100000,credit:0},{accountId:'3.1',debit:0,credit:100000}]},{id:'sale-prior',date:'2025-06-01',concept:'Venta previa',branchId:'central',documentId:'',manual:true,lines:[{accountId:'1.1.2',debit:100000,credit:0},{accountId:'4.1',debit:0,credit:100000}]},{id:'capital-prior',date:'2025-07-01',concept:'Aporte previo',branchId:'central',documentId:'',manual:true,lines:[{accountId:'1.1.2',debit:50000,credit:0},{accountId:'3.1',debit:0,credit:50000}]}]
 function nominal(to,ref,prior){const i=statementsInput(s,statementsForInflation,{to,reference:ref});i.equityEntries=i.equityEntries.map(e=>({...e,category:'Aportes'}));if(prior){i.priorPositionId=prior.id;i.priorPeriodId=prior.id}i.review=statementsForInflation.statementReview(statementsForInflation.previewStatements(s,i));return statementsForInflation.preserveStatements(s,i,actor)}
 const old=nominal('2025-12-31','Nominal anterior'),allIndices=[{month:'2024-12',value:'100'},...Array.from({length:12},(_,i)=>({month:`2025-${String(i+1).padStart(2,'0')}`,value:i<6?'200':i<11?'250':'300'})),...Array.from({length:12},(_,i)=>({month:`2026-${String(i+1).padStart(2,'0')}`,value:'450'}))]
 function adjustment(record,mode,openingId=''){const {targets,accounts}=reexpression.reexpressionTargets(s,record.id,mode);return {statementId:record.id,reference:`Ajustado ${record.number}`,reason:'Ensayo de continuidad y comparativos con fuentes conservadas.',mode,openingId,indices:{provider:'Ensayo',reference:'Serie sintética interanual',url:'https://www.facpce.org.ar/indices-facpce/',accessedAt:'2026-10-11',confirmed:true,values:allIndices.filter(v=>v.month<=record.to.slice(0,7))},policies:accounts.map(a=>({accountId:a.id,nature:'Monetaria',reason:'Saldo monetario del ensayo.'})),aging:targets.map(t=>({id:t.id,kind:t.type==='Resultados'?'Transacción':'Partida revisada',parts:[{amount:t.amount,month:t.month,reason:'Origen documentado del ensayo.',...(t.type==='Resultados'?{rubricId:t.rubricId}:{})}]})),notes:[...record.preview.notes,{id:'inflation',title:'Ajuste por inflación',body:'Caso sintético de continuidad, exposición monetaria y comparativos reexpresados.'}],residualReason:'Redondeos por cálculo de partidas del ensayo.',comparativePositionId:'',comparativePeriodId:'',comparativeReason:'Pendiente de antecedentes en este ensayo.',confirmed:true}}
 const first=adjustment(old,'Primera aplicación o reanudación');first.review=reexpression.reexpressionReview(reexpression.previewReexpression(s,first));const oldAdjusted=reexpression.preserveReexpression(s,first,actor);assert.equal(oldAdjusted.preview.globalResult,-110000)
 inflationPosting.prepareReexpressionPostingAccounts(s,actor);const pi=inflationPosting.reexpressionPostingDefaults(s,oldAdjusted.id);pi.components.find(c=>c.componentId==='eq-unassigned').accountId='3.2';pi.reference='Contabilización anterior';pi.reason='Reparto sintético de ajustes anteriores';pi.confirmed=true;pi.syntheticConfirmed=true;pi.allocations=inflationPosting.reexpressionPostingTargets(s,oldAdjusted.id).map(t=>({targetId:t.id,parts:t.delta?[{branchId:'central',amount:t.delta,reason:'Reparto documentado en una sola sucursal.'}]:[]}));pi.review=inflationPosting.reexpressionPostingReview(inflationPosting.previewReexpressionPosting(s,pi));legacyPostReexpression(s,pi,actor)
 const yc=require(join(dir,'year-end-close.js')),eo=require(join(dir,'exercise-opening.js'));const ci={reference:'Cierre anterior moneda prueba',reason:'Conciliación sintética anterior',resultsAccountId:'3.2',acknowledged:[]},cp=yc.previewYearEndClose(s,ci);ci.acknowledged=cp.before.warnings.map(w=>w.id);ci.review=yc.yearEndReview(cp);yc.closeYearEnd(s,ci,actor);const oi={reference:'Apertura siguiente moneda prueba',reason:'Continuidad sintética del diario',exerciseEnd:'2026-12-31',acknowledged:[]},op=eo.previewExerciseOpening(s,oi);oi.acknowledged=op.warnings.map(w=>w.id);oi.review=eo.exerciseOpeningReview(op);eo.openExercise(s,oi,actor)
 s.entries.push({id:'sale-current',date:'2026-01-15',concept:'Venta nueva',branchId:'central',documentId:'',manual:true,lines:[{accountId:'1.1.2',debit:20000,credit:0},{accountId:'4.1',debit:0,credit:20000}]});const current=nominal('2026-12-31','Nominal actual',old),next=adjustment(current,'Continuidad',oldAdjusted.id);next.comparativePositionId=oldAdjusted.id;next.comparativePeriodId=oldAdjusted.id;const p=reexpression.previewReexpression(s,next);assert.equal(p.openingNetAssets,250000);assert.equal(p.openingEquity,375000);assert.equal(p.closingEquity,270000);assert.equal(p.globalResult,-105000);assert.equal(p.statement.comparative.position.value.equity,375000);assert.equal(p.statement.comparative.period.results.profit,-165000);assert.equal(p.statement.comparative.period.equity.closing,375000);assert.equal(p.statement.comparative.period.cash.closing,375000);assert.equal(p.statement.comparative.period.cash.difference,0);assert.equal(p.statement.equity.rows[0].values['eq-capital'],150000);assert.equal(p.statement.equity.rows[0].values['eq-capital-adjustment'],390000);next.review=reexpression.reexpressionReview(p);reexpression.preserveReexpression(s,next,actor);validateState(JSON.parse(JSON.stringify(s)));assert.throws(()=>reexpression.previewReexpression(s,{...next,openingId:''}),/continuidad/);const revised=structuredClone(next);revised.indices.values.find(v=>v.month==='2025-06').value='201';assert.throws(()=>reexpression.previewReexpression(s,revised),/serie difiere/)
})

test('consumption uses original layers and comparison recomputes both magnitudes rather than inflating a net difference',()=>{const {state,input}=inflationFixture(),cost=input.aging.find(t=>t.id==='result:cost:0');cost.kind='Comparación de magnitudes';cost.parts=[{amount:60000,month:'2026-01',rubricId:'ex-cogs',reason:'Primera magnitud documentada de comparación.'},{amount:-30000,month:'2025-12',rubricId:'ex-cogs',reason:'Segunda magnitud documentada en distinta moneda.'}];const p=reexpression.previewReexpression(state,input);assert.equal(p.calculations.filter(t=>t.targetId===cost.id).reduce((n,c)=>n+c.adjusted,0),36818);assert.equal(p.globalResult,19772);assert.equal(p.statement.results.profit,19772);assert.ok(p.otherResidual!==-1);const bad=structuredClone(input);bad.aging.find(t=>t.id===cost.id).kind='Consumo de activos';assert.throws(()=>reexpression.previewReexpression(state,bad),/signos opuestos/)})
function postingFixture(){const {state,actor,input}=inflationFixture();state.settings.exerciseEnd='2026-10-11';input.review=reexpression.reexpressionReview(reexpression.previewReexpression(state,input));const record=reexpression.preserveReexpression(state,input,actor);inflationPosting.prepareReexpressionPostingAccounts(state,actor);const posting=inflationPosting.reexpressionPostingDefaults(state,record.id);posting.reference='Contabilización anual sintética';posting.reason='Mediciones, RECPAM monetario y otros resultados revisados; ensayo sin operaciones reales.';posting.confirmed=true;posting.syntheticConfirmed=true;posting.allocations=inflationPosting.reexpressionPostingTargets(state,record.id).map(t=>({targetId:t.id,parts:t.delta?[{branchId:'central',amount:t.delta,reason:'Reparto sintético revisado para la única sucursal de origen.'}]:[]}));return {state,actor,record,posting}}
// Existing regression fixtures reproduce pre-VNR annual records explicitly. New closing fixtures retain the production version.
function legacyPostReexpression(state,input,actor){const r=inflationPosting.postReexpression(state,input,actor);r.ledgerVersion=2;delete r.preview.inventoryClosingRequired;r.review=inflationPosting.reexpressionPostingReview(r.preview);return r}
function reviewedPosting(state,input){return {...input,review:inflationPosting.reexpressionPostingReview(inflationPosting.previewReexpressionPosting(state,input))}}
test('annual inflation posts exact measurements, equity, independently calculated RECPAM and residual while preserving original operations',()=>{const {state,actor,record,posting}=postingFixture(),before=structuredClone(state),p=inflationPosting.previewReexpressionPosting(state,posting);assert.equal(p.result,19772);assert.equal(p.debit,200137);assert.equal(p.credit,200137);assert.equal(p.monetaryResult,-68182);assert.equal(p.otherResult,-1);assert.equal(p.branches.length,1);assert.equal(p.after.rows.find(a=>a.accountId==='1.2.1').closing,300000);assert.equal(p.after.rows.find(a=>a.accountId==='1.2.2').closing,-7500);assert.equal(p.after.rows.find(a=>a.accountId==='3.90.2').closing,-157273);assert.equal(p.after.rows.find(a=>a.accountId==='5.90').closing,68182);assert.equal(p.after.rows.find(a=>a.accountId==='5.91').closing,1);const r=legacyPostReexpression(state,reviewedPosting(state,posting),actor);assert.equal(r.number,'INT-AI-00000001');assert.equal(r.responsible,actor.name);assert.deepEqual(state.entries.slice(0,11),before.entries);assert.equal(state.entries.length,12);assert.equal(state.entries.at(-1).reexpressionPostingId,r.id);assert.equal(r.ledgerVersion,2);assert.equal(r.preview.after.entryIds.at(-1),r.entryIds[0]);assert.deepEqual(state.financialStatements,before.financialStatements);assert.deepEqual(state.reexpressions,before.reexpressions);assert.deepEqual(state.documents,before.documents);assert.deepEqual(state.stockMoves,before.stockMoves);assert.deepEqual(state.treasuryMoves,before.treasuryMoves);validateState(JSON.parse(JSON.stringify(state)));assert.throws(()=>inflationPosting.previewReexpressionPosting(state,posting),/segunda vez/);assert.throws(()=>reexpression.previewReexpression(state,record),/contabilizado/);assert.throws(()=>engine.assertDate(state,'2026-10-11'),/ajuste anual/);assert.equal(isManualJournal(state.entries.at(-1)),false)})
test('annual inflation refuses interim, unconfirmed, stale, closed and incompatible account or branch allocations atomically',()=>{const {state,actor,posting}=postingFixture();for(const mutate of [i=>i.confirmed=false,i=>i.syntheticConfirmed=false,i=>i.allocations.pop(),i=>i.allocations[0].parts[0].amount++,i=>i.allocations[0].parts[0].branchId='missing',i=>i.allocations[0].parts[0].reason='',i=>i.components[0].accountId='1.1.2',i=>i.components[1].accountId=i.components[0].accountId,i=>i.monetaryLossAccountId='5.4',i=>i.otherLossAccountId=i.monetaryLossAccountId]){const copy=structuredClone(posting),before=structuredClone(state);mutate(copy);assert.throws(()=>inflationPosting.previewReexpressionPosting(state,copy));assert.deepEqual(state,before)}const annual=structuredClone(state);annual.settings.exerciseEnd='2026-12-31';assert.throws(()=>inflationPosting.previewReexpressionPosting(annual,posting),/anual completa/);const closed=structuredClone(state);closed.settings.closedUntil='2026-10-11';assert.throws(()=>inflationPosting.previewReexpressionPosting(closed,posting),/cerrado/);const stale=structuredClone(state);stale.entries.push({id:'late-post-source',date:'2026-10-10',concept:'Dato posterior',branchId:'central',documentId:'',lines:[{accountId:'1.1.2',debit:100,credit:0},{accountId:'4.1',debit:0,credit:100}]});assert.throws(()=>inflationPosting.previewReexpressionPosting(stale,posting),/posterior/);assert.throws(()=>legacyPostReexpression(state,reviewedPosting(state,posting),{...actor,role:'Administración'}),/Administrador General/);assert.throws(()=>legacyPostReexpression(state,{...reviewedPosting(state,posting),reason:'Revisión distinta'},actor),/revisión/);state.masters.branches.find(b=>b.id==='central').active=false;assert.throws(()=>inflationPosting.previewReexpressionPosting(state,posting),/activas/)})
test('posted inflation restoration rejects altered review, duplicate periods, missing sources, changed journals and post-adjustment operations',()=>{const {state,actor,posting}=postingFixture();legacyPostReexpression(state,reviewedPosting(state,posting),actor);for(const mutate of [s=>s.reexpressionPostings[0].preview.result++,s=>s.reexpressionPostings[0].preview.after.entryIds.pop(),s=>delete s.reexpressionPostings[0].ledgerVersion,s=>s.reexpressionPostings[0].ledgerVersion=6,s=>s.reexpressionPostings[0].components[0].accountId='3.2',s=>s.reexpressionPostings[0].allocations[0].parts[0].amount++,s=>s.entries.at(-1).lines[0].debit++,s=>delete s.entries.at(-1).reexpressionPostingId,s=>s.entries.at(-1).manual=true,s=>s.entries.pop(),s=>s.reexpressionPostings=[],s=>s.reexpressionPostings.push(structuredClone(s.reexpressionPostings[0])),s=>s.reexpressionPostings=null,s=>s.entries.push({id:'after-post',date:'2026-10-11',concept:'No admitido',branchId:'central',documentId:'',manual:true,lines:[{accountId:'1.1.2',debit:100,credit:0},{accountId:'4.1',debit:0,credit:100}]})]){const copy=structuredClone(state);mutate(copy);assert.throws(()=>validateState(copy))}const legacy=initialState();delete legacy.reexpressionPostings;validateState(legacy)})
test('year-end closure and next opening retain adjusted profit, capital, reserve, accumulated results and protected source records',()=>{const {state,actor,posting}=postingFixture();assert.throws(()=>previewYearEndClose(state,{reference:'Cierre',reason:'Revisión',resultsAccountId:'3.2',acknowledged:[]}),/contabilizá/);const record=legacyPostReexpression(state,reviewedPosting(state,posting),actor);assert.throws(()=>previewYearEndClose(state,{reference:'Cierre',reason:'Revisión',resultsAccountId:'3.90.6',acknowledged:[]}),/Resultados no asignados/);const close=closeYearEnd(state,reviewedYear(state),actor);assert.equal(close.preview.result,19772);assert.equal(close.preview.reexpressionPosting.id,record.id);assert.equal(close.after.rows.find(a=>a.accountId==='3.2').closing,5864);assert.equal(close.after.rows.find(a=>a.accountId==='3.3').closing,-12000);assert.equal(close.after.rows.find(a=>a.accountId==='3.1').closing,-320000);assert.equal(close.after.rows.find(a=>a.accountId==='3.90.2').closing,-157273);assert.ok(close.after.rows.filter(a=>['Ingresos','Gastos'].includes(a.group)).every(a=>!a.closing));assert.equal(state.accountingCloses.at(-1).preview.reexpressionPostings[0].id,record.id);validateState(state);openExercise(state,reviewedOpening(state),actor);assert.equal(state.settings.exerciseStart,'2026-10-12');assert.equal(state.exerciseOpenings.at(-1).preview.reexpressionPosting.id,record.id);assert.ok(state.exerciseOpenings.at(-1).preview.warnings[0].message.includes('no reexpreses otra vez'));assert.equal(trialBalance(state,state.settings.exerciseStart,state.settings.exerciseEnd).rows.find(a=>a.accountId==='1.2.1').opening,300000);engine.assertDate(state,'2026-10-12');validateState(JSON.parse(JSON.stringify(state)))})
test('inflation allocations preserve two branch journals and monetary exposure follows actual origins rather than an arbitrary residual split',()=>{const {state,actor}=statementsFixture(initialState);state.settings.exerciseEnd='2026-10-11';state.masters.branches.push({id:'branch-inflation',name:'Sucursal del ensayo',active:true});for(const e of state.entries.filter(e=>['sale','collection','depreciation'].includes(e.id)))e.branchId='branch-inflation';const ni=statementsInput(state,statementsForInflation,{to:'2026-10-11'});ni.review=statementsForInflation.statementReview(statementsForInflation.previewStatements(state,ni));const nominal=statementsForInflation.preserveStatements(state,ni,actor),ri=reexpressionInput(state,nominal,reexpression);ri.review=reexpression.reexpressionReview(reexpression.previewReexpression(state,ri));const record=reexpression.preserveReexpression(state,ri,actor);inflationPosting.prepareReexpressionPostingAccounts(state,actor);const input=inflationPosting.reexpressionPostingDefaults(state,record.id);Object.assign(input,{reference:'Dos sucursales del ensayo',reason:'Reparto por origen revisado para dos unidades.',confirmed:true,syntheticConfirmed:true});input.allocations=inflationPosting.reexpressionPostingTargets(state,record.id).map(t=>({targetId:t.id,parts:t.delta?[{branchId:t.accountId==='1.2.2'?'branch-inflation':'central',amount:t.delta,reason:'Origen del saldo revisado por unidad.'}]:[]}));const p=inflationPosting.previewReexpressionPosting(state,input),b=p.branches.find(b=>b.id==='branch-inflation'),c=p.branches.find(b=>b.id==='central');assert.equal(b.monetaryResult,-36364);assert.equal(b.otherResult,0);assert.equal(c.monetaryResult,-31818);assert.equal(c.otherResult,-1);assert.equal(p.branches.reduce((n,b)=>n+b.monetaryResult,0),-68182);assert.equal(b.lines.find(l=>l.accountId==='4.1').credit,36364);assert.ok(p.branches.every(b=>b.lines.reduce((n,l)=>n+l.debit-l.credit,0)===0));const original=structuredClone(state.entries),r=legacyPostReexpression(state,reviewedPosting(state,input),actor);assert.equal(r.entryIds.length,2);assert.deepEqual(state.entries.slice(0,11),original);validateState(JSON.parse(JSON.stringify(state)));closeYearEnd(state,reviewedYear(state),actor);assert.equal(state.yearEndCloses.at(-1).preview.branches.length,2);validateState(state)})
test('continuity after posted inflation uses adjusted opening ledger balances and rejects first application over already adjusted amounts',()=>{const {state,actor,posting,record}=postingFixture();legacyPostReexpression(state,reviewedPosting(state,posting),actor);closeYearEnd(state,reviewedYear(state),actor);openExercise(state,reviewedOpening(state,{exerciseEnd:'2026-12-31'}),actor);const ni=statementsInput(state,statementsForInflation,{to:'2026-12-31',reference:'Nuevo período con apertura ajustada'});ni.review=statementsForInflation.statementReview(statementsForInflation.previewStatements(state,ni));const nominal=statementsForInflation.preserveStatements(state,ni,actor),targets=reexpression.reexpressionTargets(state,nominal.id,'Continuidad'),ri={...reexpressionInput(state,nominal,reexpression),reference:'Continuidad del ajuste contabilizado',mode:'Continuidad',openingId:record.id,indices:{...record.indices,values:[...record.indices.values,{month:'2026-11',value:'175'},{month:'2026-12',value:'200'}]},aging:targets.targets.map(t=>({id:t.id,kind:t.type==='Resultados'?'Transacción':'Partida revisada',parts:[{amount:t.amount,month:t.type==='Cierre'&&['1.1.9','1.2.1','1.2.2'].includes(t.accountId)?'2026-10':t.month,reason:'Saldo de apertura ya ajustado al cierre anterior.',...(t.type==='Resultados'?{rubricId:t.rubricId}:{})}]}))};const p=reexpression.previewReexpression(state,ri);assert.equal(p.openingNetAssets,483409);assert.equal(p.openingEquity,644545);assert.equal(p.closingEquity,594545);assert.equal(p.globalResult,-50000);assert.equal(p.statement.equity.rows[0].values['eq-capital-adjustment'],316364);ri.review=reexpression.reexpressionReview(p);const next=reexpression.preserveReexpression(state,ri,actor);validateState(JSON.parse(JSON.stringify(state)));const bad={...reexpressionInput(state,nominal,reexpression),indices:ri.indices};assert.throws(()=>reexpression.previewReexpression(state,bad),/Continuidad/);inflationPosting.prepareReexpressionPostingAccounts(state,actor);const input=inflationPosting.reexpressionPostingDefaults(state,next.id);Object.assign(input,{reference:'Segundo ajuste anual',reason:'Ajuste de los saldos ya expresados en moneda anterior, sin duplicar el primer ajuste.',confirmed:true,syntheticConfirmed:true});input.allocations=inflationPosting.reexpressionPostingTargets(state,next.id).map(t=>({targetId:t.id,parts:t.delta?[{branchId:'central',amount:t.delta,reason:'Reparto revisado del período siguiente.'}]:[]}));const second=legacyPostReexpression(state,reviewedPosting(state,input),actor);assert.equal(second.preview.result,-50000);assert.equal(second.preview.after.rows.find(a=>a.accountId==='1.2.1').closing,400000);validateState(JSON.parse(JSON.stringify(state)));closeYearEnd(state,reviewedYear(state,{reference:'Segundo cierre anual'}),actor);assert.equal(state.yearEndCloses.at(-1).preview.result,-50000);validateState(state)})
test('branch monetary rounding is explicit and reconciles an aggregate one-cent exposure without unbalanced journals',()=>{const state=initialState(),actor={userId:'admin',name:'Administrador',role:'Administrador General',permissions:[]};state.settings.exerciseEnd='2026-10-11';state.masters.branches.push({id:'secondary',name:'Segunda sucursal',active:true});state.entries=['central','secondary'].map((branchId,i)=>({id:`tiny-opening-${i}`,date:'2025-12-31',concept:'Saldos mínimos sintéticos',branchId,documentId:'',manual:true,lines:[{accountId:'1.1.2',debit:1,credit:0},{accountId:'3.1',debit:0,credit:1}]}));const ni=statementsInput(state,statementsForInflation,{to:'2026-10-11'});ni.review=statementsForInflation.statementReview(statementsForInflation.previewStatements(state,ni));const nominal=statementsForInflation.preserveStatements(state,ni,actor),ri=reexpressionInput(state,nominal,reexpression);ri.review=reexpression.reexpressionReview(reexpression.previewReexpression(state,ri));const record=reexpression.preserveReexpression(state,ri,actor);assert.equal(record.preview.monetaryResult,-1);inflationPosting.prepareReexpressionPostingAccounts(state,actor);const input=inflationPosting.reexpressionPostingDefaults(state,record.id);Object.assign(input,{reference:'Redondeo de exposición por sucursal',reason:'Ensayo mínimo para conciliar redondeo individual y total agregado.',confirmed:true,syntheticConfirmed:true});input.allocations=inflationPosting.reexpressionPostingTargets(state,record.id).map(t=>({targetId:t.id,parts:t.delta?[{branchId:'central',amount:t.delta,reason:'Asignación revisada del centavo agregado de ajuste de capital.'}]:[]}));const p=inflationPosting.previewReexpressionPosting(state,input);assert.equal(p.result,-1);assert.equal(p.branches.reduce((n,b)=>n+b.monetaryResult,0),-1);assert.equal(p.branches.find(b=>b.id==='central').monetaryRounding,1);assert.equal(p.otherResult,0);assert.ok(p.branches.every(b=>b.lines.reduce((n,l)=>n+l.debit-l.credit,0)===0));legacyPostReexpression(state,reviewedPosting(state,input),actor);validateState(JSON.parse(JSON.stringify(state)))})
