test('finished conversion correction reaches stock and previously sold cost through an atomic CPP9 cut and leaves old records untouched',()=>{const f=finishedConvertedServiceFixture(),old=structuredClone(f.s),p=finishedCorrection(f),r=productionCorrections.postProductionReestimate(f.s,p,f.actor),b=f.s.inventoryCostBatches.at(-1);assert.equal(r.preview.difference,-2000);assert.deepEqual(r.preview.destinations,{wip:0,inventory:-1000,cogs:-1000,other:[]});assert.equal(b.costVersion,10);assert.equal(b.productionCorrectionId,r.id);assert.equal(r.inventoryBatchId,b.id);assert.equal(b.balances.find(v=>v.productId===f.order.productId).value,5500);assert.equal(serviceBalance(f.s,f.accounts.wip),0);assert.equal(serviceBalance(f.s,f.accounts.cogs),5500);assert.equal(serviceBalance(f.s,f.accounts.inventory),12500);assert.equal(serviceBalance(f.s,'2.1.7'),-13000);assert.deepEqual(f.s.entries.slice(0,old.entries.length),old.entries);assert.deepEqual(f.s.inventoryCostBatches.slice(0,old.inventoryCostBatches.length),old.inventoryCostBatches);assert.deepEqual(f.s.stockMoves,old.stockMoves);assert.deepEqual(f.s.productionCosts,old.productionCosts);validateState(JSON.parse(JSON.stringify(f.s)))})
