test('a VNR boundary is repriced by the linked conversion bridge and a later VNR comparison preserves the corrected finished lot',()=>{function vnr(f){inventoryRecovery.prepareInventoryRecoveryAccounts(f.s,f.actor);const b=f.s.inventoryCostBatches.at(-1),i={date:b.date,reference:'VNR del lote conservado',reason:'Precios sintéticos revisados para el inventario disponible.',scope:'Inventario completo',scopeReason:'Todas las partidas del corte.',currencyConfirmed:true,scopeConfirmed:true,changesReason:'',...inventoryRecovery.inventoryRecoveryAccountDefaults(f.s),groups:b.balances.filter(r=>r.quantity).map((r,n)=>({id:`vnr-finished-${n}`,name:r.sku,mode:'Partida individual',reason:'Realización individual.',impracticability:'',geography:'',members:[{productId:r.productId,depositId:r.depositId}],saleValue:r.value,saleCosts:0,completionCosts:0,evidence:'Cotización sintética conservada.',evidenceDate:b.date}))};return inventoryRecovery.assessInventoryRecovery(f.s,{...i,review:inventoryRecovery.inventoryRecoveryReview(inventoryRecovery.previewInventoryRecovery(f.s,i))},f.actor)}const f=finishedConvertedServiceFixture();vnr(f);const before=structuredClone(f.s),corrected=productionCorrections.postProductionReestimate(f.s,finishedCorrection(f),f.actor);assert.equal(corrected.preview.inventory.input.costVersion,10);assert.deepEqual(f.s.inventoryRecoveries,before.inventoryRecoveries);assert.equal(serviceBalance(f.s,f.accounts.inventory),12500);validateState(f.s);const g=finishedConvertedServiceFixture();productionCorrections.postProductionReestimate(g.s,finishedCorrection(g),g.actor);vnr(g);const b=postCosts(g.s,{date:'2026-10-07',reference:'CPP posterior al VNR del lote corregido',accounts:inventoryAccountDefaults(g.s)},g.actor);assert.equal(b.entryIds.length,0);assert.equal(b.balances.find(r=>r.productId===g.order.productId).value,5500);validateState(JSON.parse(JSON.stringify(g.s)))})
