function finishedVnr(f,recoverable=4500,date=f.s.inventoryCostBatches.at(-1).date,reference='VNR previo a nueva información'){inventoryRecovery.prepareInventoryRecoveryAccounts(f.s,f.actor);const b=f.s.inventoryCostBatches.at(-1),i={date,reference,reason:'Precios sintéticos revisados por partida, sin reescribir costo.',scope:'Inventario completo',scopeReason:'Todas las partidas del inventario al corte.',currencyConfirmed:true,scopeConfirmed:true,changesReason:'Nueva evidencia de realización documentada.',...inventoryRecovery.inventoryRecoveryAccountDefaults(f.s),groups:b.balances.filter(r=>r.quantity).map((r,n)=>({id:`production-vnr-${n}`,name:r.sku,mode:'Partida individual',reason:'Venta individual del artículo.',impracticability:'',geography:'',members:[{productId:r.productId,depositId:r.depositId}],saleValue:r.productId===f.order.productId?recoverable:r.value,saleCosts:0,completionCosts:0,evidence:'Cotización sintética para verificar el circuito.',evidenceDate:date}))};return inventoryRecovery.assessInventoryRecovery(f.s,{...i,review:inventoryRecovery.inventoryRecoveryReview(inventoryRecovery.previewInventoryRecovery(f.s,i))},f.actor)}
