function invoiceFinishedDelivery(f){const remit=f.s.documents.find(d=>d.side==='cliente'&&d.kind==='remito'&&d.lines.some(l=>l.productId===f.order.productId));return {remit,invoice:engine.createDocument(f.s,{...remit,kind:'factura',letter:'A',sourceId:remit.id},f.actor.role)}}
function returnFinishedDelivery(f,date,value,allowance=0,manual=true){const {remit,invoice}=invoiceFinishedDelivery(f),note=returnNote(f.s,invoice,1,date);registerStockReturn(f.s,returnInput(remit,1,date,note),f.actor);const returned=f.s.stockReturns.at(-1),valuation={date,reference:`Devolución histórica del lote ${date}`,accounts:inventoryAccountDefaults(f.s),...(manual?{returnCosts:[{returnId:returned.id,productId:f.order.productId,value,reference:'Costo bruto de la entrega revisado en su moneda.',allowance,allowanceReference:'Pérdida efectivamente consumida en el corte original.'}]}:{} )};return {returned,batch:postCosts(f.s,valuation,f.actor)}}
