 const f=productionCurrentClosingFixture();productionRecovery.assessProductionRecovery(f.state,currentProcessReviewed(f),f.actor);openCurrencyInventory(f);postCosts(f.state,{date:'2026-12-31',reference:'Segundo corte con pérdida actual de proceso conservada',accounts:inventoryAccountDefaults(f.state)},f.actor);const ni=statementsInput(f.state,statementsForInflation,{to:'2026-12-31',reference:'Estados de continuidad posteriores al proceso actual'});for(const a of ni.allocations)if([f.accounts.inventory,f.accounts.wip,'production-allowance'].includes(a.accountId))a.items[0].rubricId='ac-inventory';ni.review=statementsForInflation.statementReview(statementsForInflation.previewStatements(f.state,ni));const nominal=statementsForInflation.preserveStatements(f.state,ni,f.actor),targets=reexpression.reexpressionTargets(f.state,nominal.id,'Continuidad'),ri={...reexpressionInput(f.state,nominal,reexpression),mode:'Continuidad',openingId:f.adjusted.id,reference:'Moneda posterior a la comparación actual de proceso',indices:{...f.adjusted.indices,values:[...f.adjusted.indices.values,{month:'2026-11',value:'175'},{month:'2026-12',value:'200'}]},policies:targets.accounts.map(a=>({accountId:a.id,nature:[f.accounts.inventory,f.accounts.wip,'production-allowance'].includes(a.id)?'Histórica':'Monetaria',reason:'Costos y pérdida de proceso ya en moneda de octubre.'})),aging:targets.targets.map(t=>({id:t.id,kind:'Partida revisada',parts:[{amount:t.amount,month:[f.accounts.inventory,f.accounts.wip,'production-allowance'].includes(t.accountId)?'2026-10':t.month,reason:'Origen en la moneda del cierre anterior.',...(t.type==='Resultados'?{rubricId:t.rubricId}:{})}]}))},p=reexpression.previewReexpression(f.state,ri);assert.equal(p.statement.equity.rows[0].values['eq-unassigned'],-3600);assert.equal(p.statement.position.assets,30667);assert.equal(p.statement.position.equity,19967);assert.equal(p.globalResult,3567);reexpression.preserveReexpression(f.state,{...ri,review:reexpression.reexpressionReview(p)},f.actor);validateState(JSON.parse(JSON.stringify(f.state)))
