function bankSplitFixture(){const f=bankFixture();f.input.lines=[{...f.input.lines[0],amount:200000,reference:'PART-A'},{...f.input.lines[0],amount:400000,reference:'PART-B'},...f.input.lines.slice(1)];f.input.closing=390000;f.b=importBankStatement(f.s,f.input,f.actor);return f}
test('several bank rows reconcile one ledger movement without changing accounting and reverse as a whole from any row',()=>{const {s,actor,b}=bankSplitFixture(),before=structuredClone(s),ids=b.lines.slice(0,2).map(l=>l.id);matchBankGroup(s,b.id,ids,['in-one'],'Dos acreditaciones del mismo anticipo',actor);assert.equal(b.groups.length,1);assert.ok(b.lines.slice(0,2).every(l=>l.treasuryMoveIds[0]==='in-one'));assert.equal(s.treasuryMoves.find(m=>m.id==='in-one').bankStatementLineId,ids[0]);assert.equal(statementSummary(s,b).matched,2);assert.equal(statementSummary(s,b).pendingBank,-210000);assert.deepEqual(s.entries,before.entries);assert.deepEqual(s.documents,before.documents);assert.deepEqual(s.treasuryMoves.map(m=>m.amount),before.treasuryMoves.map(m=>m.amount));assert.equal(b.events[0].user,actor.name);validateState(JSON.parse(JSON.stringify(s)));assert.throws(()=>manualReconciliation(s,'in-one',false),/extracto/);assert.throws(()=>cancelBankStatement(s,b.id,'Reemplazo',actor));unmatchBankLine(s,b.id,ids[1],'Revisar la agrupación completa',actor);assert.equal(b.groups.length,0);assert.ok(b.lines.every(l=>!l.treasuryMoveIds.length));assert.equal(s.treasuryMoves.find(m=>m.id==='in-one').reconciled,false);assert.deepEqual(b.events[1].lineIds,ids);assert.equal(b.events[1].groupId,b.events[0].groupId);validateState(s);matchBankGroup(s,b.id,ids,['in-one'],'Nueva revisión',actor);validateState(s)})
test('bank groups require exact cents, same sign, pending unique references and a reason before any mutation',()=>{const {s,actor,b}=bankSplitFixture(),ids=b.lines.slice(0,2).map(l=>l.id);for(const [rows,moves,note] of [[[],['in-one'],'Motivo'],[[ids[0]],['in-one'],'Motivo'],[[ids[0],ids[0]],['in-one'],'Motivo'],[[ids[0],'missing'],['in-one'],'Motivo'],[[ids[0],b.lines[2].id],['in-one'],'Motivo'],[ids,[], 'Motivo'],[ids,['in-one','in-one'],'Motivo'],[ids,['in-two'],'Motivo'],[ids,['out-one'],'Motivo'],[ids,['missing'],'Motivo'],[ids,['in-one'],'']]){const old=structuredClone(s);assert.throws(()=>matchBankGroup(s,b.id,rows,moves,note,actor));assert.deepEqual(s,old)}const old=structuredClone(s);assert.throws(()=>matchBankGroup(s,b.id,ids,['in-one'],'Motivo',{...actor,role:'Depósito'}));assert.deepEqual(s,old);manualReconciliation(s,'in-one',true);assert.throws(()=>matchBankGroup(s,b.id,ids,['in-one'],'Motivo',actor));manualReconciliation(s,'in-one',false);matchBankGroup(s,b.id,ids,['in-one'],'Motivo',actor);assert.throws(()=>matchBankGroup(s,b.id,ids,['in-two'],'Otra revisión',actor));validateState(s)})
test('bank grouping supports many ledger movements and debit rows while preserving legacy single-row links',()=>{const {s,actor,input}=bankFixture();input.lines=[{...input.lines[0],reference:'A',amount:300000},{...input.lines[0],reference:'B',amount:700000},{...input.lines[1],reference:'C',amount:-70000},{...input.lines[1],reference:'D',amount:-130000},input.lines[2]];const b=importBankStatement(s,input,actor);matchBankGroup(s,b.id,b.lines.slice(0,2).map(l=>l.id),['in-one','in-two'],'Dos depósitos y dos cobros',actor);matchBankGroup(s,b.id,b.lines.slice(2,4).map(l=>l.id),['out-one'],'Débito bancario fraccionado',actor);assert.equal(b.groups.length,2);assert.deepEqual(statementSummary(s,b),{ledger:800000,pendingBank:-10000,pendingLedger:0,difference:-10000,unexplained:0,matched:4});validateState(s);unmatchBankLine(s,b.id,b.lines[0].id,'Revisar los cobros',actor);assert.equal(b.groups.length,1);assert.ok(s.treasuryMoves.filter(m=>m.amount>0).every(m=>!m.reconciled));validateState(s)})
test('restoring bank groups rejects lost members, repeated moves, wrong amounts, missing history and anchors',()=>{const {s,actor,b}=bankSplitFixture();matchBankGroup(s,b.id,b.lines.slice(0,2).map(l=>l.id),['in-one'],'Agrupación documentada',actor);for(const change of [s=>delete s.bankStatements[0].groups,s=>s.bankStatements[0].groups[0].lineIds.pop(),s=>s.bankStatements[0].groups[0].moveIds.push('in-one'),s=>s.bankStatements[0].lines[1].treasuryMoveIds=[],s=>s.bankStatements[0].groups.push(structuredClone(s.bankStatements[0].groups[0])),s=>s.bankStatements[0].groups[0].lineIds[1]='missing',s=>s.bankStatements[0].events=[],s=>s.bankStatements[0].events[0].lineIds.reverse(),s=>s.treasuryMoves.find(m=>m.id==='in-one').bankStatementLineId=s.bankStatements[0].lines[1].id,s=>s.treasuryMoves.find(m=>m.id==='in-one').amount++,s=>s.bankStatements[0].status='Anulado']){const copy=structuredClone(s);change(copy);assert.throws(()=>validateState(copy))}validateState(JSON.parse(JSON.stringify(s)))})

