test('bank CSV refuses malformed quotes, duplicate or extra columns, binary controls and oversized or empty input',()=>{for(const text of ['Fecha;Referencia;Descripcion;Importe\n2026-10-08;OP;"Sin cierre;100','Fecha;Referencia;Descripcion;Importe\n2026-10-08;OP;"Texto"resto;100','Fecha;Referencia;Descripcion;Importe\n2026-10-08;OP;Tex"to;100','Fecha;Referencia;Descripcion;Importe\n2026-10-08;OP;Texto;100;ignorado','Fecha;Referencia;Descripcion;Importe\n2026-10-08;OP;Texto','Fecha;Referencia;Referencia;Importe\n2026-10-08;OP;Texto;100','Fecha;Referencia;Descripcion;Importe','Fecha;Referencia;Descripcion;Importe\n2026-10-08;OP;Tex\0to;100','x'.repeat(10*1024*1024+1)])assert.throws(()=>parseBankStatementCsv(text))})
test('bank CSV checks its 5000-row limit and retains row errors for strict bank validation without partial imports',()=>{const header='Fecha;Referencia;Descripcion;Importe\n',row=i=>`2026-10-08;OP-${i};Texto;1.00`,x=parseBankStatementCsv(header+Array.from({length:5000},(_,i)=>row(i)).join('\n'));assert.equal(x.rows.length,5000);assert.throws(()=>parseBankStatementCsv(header+Array.from({length:5001},(_,i)=>row(i)).join('\n')),/5000/);const {s,actor,input}=bankFixture(),bad=parseStatementRows(parseBankStatementCsv(header+'2026-02-30;OP;Texto;1,234').rows);assert.equal(bad.errors.length,1);assert.equal(bad.errors[0].row,2);const before=structuredClone(s);assert.throws(()=>importBankStatement(s,{...input,lines:bad.lines},actor));assert.deepEqual(s,before)})
test('bank CSV file reader decodes real UTF-8 bytes and rejects wrong encodings before preview',async()=>{const bytes=new TextEncoder().encode('Fecha;Referencia;Descripcion;Importe\n2026-10-08;Ñ-001;Acreditación;42,01'),x=await readBankStatementCsv({size:bytes.length,arrayBuffer:async()=>bytes.buffer});assert.equal(x.rows[0].Referencia,'Ñ-001');assert.equal(parseStatementRows(x.rows).lines[0].amount,4201);await assert.rejects(()=>readBankStatementCsv({size:2,arrayBuffer:async()=>new Uint8Array([0xff,0xfe]).buffer}),/UTF-8/);await assert.rejects(()=>readBankStatementCsv({size:10*1024*1024+1,arrayBuffer:async()=>{throw new Error('No debería leer')}}),/10 MB/)})

