function reservedProductionFixture(duplicate=false){const f=productionFixture();if(duplicate)engine.saveMaster(f.s,'materials',{...f.s.masters.materials[0],id:'duplicate-material',orderId:f.order.id,productId:f.raw.id,depositId:'principal',quantity:2,unit:f.raw.unit,name:'Tela duplicada'},'Producción');f.plan=prepareProduction(f.s,f.order.id,f.actor);f.input={orderId:f.order.id,date:'2026-10-05',reason:'Apartar todos los insumos del lote.'};return f}
function reserveReviewed(f,change={}){const input={...f.input,...change};return materialReservations.reserveProductionMaterials(f.s,{...input,review:materialReservations.materialReservationReview(materialReservations.previewMaterialReservation(f.s,input))},f.actor)}
test('material reservation conserves physical stock, financial records and prepared requirements with exact reviewed availability',()=>{const f=reservedProductionFixture(),old=structuredClone(f.s),r=reserveReviewed(f);assert.equal(r.number,'INT-RM-00000001');assert.equal(r.responsible,f.actor.name);assert.deepEqual([r.preview.lines[0].physical,r.preview.lines[0].quantity,r.preview.lines[0].available],[40,3,40]);assert.equal(materialReservations.materialAvailable(f.s,f.raw.id,'principal','2026-10-05'),37);assert.equal(materialReservations.materialAvailable(f.s,f.raw.id,'principal','2026-10-05',f.order.id),40);for(const key of ['stockMoves','documents','entries'])assert.deepEqual(f.s[key],old[key]);assert.deepEqual(f.s.productionPlans,old.productionPlans);validateState(JSON.parse(JSON.stringify(f.s)));assert.throws(()=>reserveReviewed(f),/sin reserva activa/)})
test('reserved materials cannot leave through remitos, transfers, adjustments or another order even when negative stock is enabled',()=>{const f=reservedProductionFixture();f.raw.negative=true;reserveReviewed(f);const old=structuredClone(f.s),line={productId:f.raw.id,description:f.raw.name,quantity:38,unit:f.raw.unit,price:100,tax:'21',discount:0};assert.throws(()=>post(f.s,'remito',{date:'2026-10-05',lines:[line]}),/reservado/);assert.deepEqual(f.s,old);f.s.masters.deposits.push({id:'reserve-target',name:'Otro depósito',branchId:'central',active:true});const moved=structuredClone(f.s);assert.throws(()=>transferStock(f.s,{date:'2026-10-05',fromId:'principal',toId:'reserve-target',reason:'Traslado de ensayo',lines:[{productId:f.raw.id,quantity:38}]},{...f.actor,role:'Administrador General'}),/reservado/);assert.deepEqual(f.s,moved);assert.throws(()=>engine.adjustStock(f.s,'Administrador General',f.raw.id,'principal',-38,'Ajuste de prueba','2026-10-05'),/reservado/);assert.deepEqual(f.s,moved);validateState(f.s)})
test('reservation sums repeated requirements and competing lots cannot reserve the same stock',()=>{const f=reservedProductionFixture(true);const r=reserveReviewed(f);assert.equal(r.preview.lines[0].quantity,5);const other={...f.order,id:'other-reserved-order',name:'Otro lote',productionPlanId:undefined};engine.saveMaster(f.s,'production',other,'Producción');engine.saveMaster(f.s,'materials',{id:'other-reserved-material',name:'Otra tela',orderId:other.id,productId:f.raw.id,depositId:'principal',quantity:38,unit:f.raw.unit},'Producción');prepareProduction(f.s,other.id,f.actor);const old=structuredClone(f.s);assert.throws(()=>reserveReviewed(f,{orderId:other.id}),/insuficiente/);assert.deepEqual(f.s,old);validateState(f.s)})
test('reservation protects availability from later dated outflows and rejects a review after stock changes',()=>{const f=reservedProductionFixture(),input={...f.input},p=materialReservations.previewMaterialReservation(f.s,input);engine.adjustStock(f.s,'Administrador General',f.raw.id,'principal',-38,'Salida futura del ensayo','2026-10-09');const old=structuredClone(f.s);assert.throws(()=>materialReservations.reserveProductionMaterials(f.s,{...input,review:materialReservations.materialReservationReview(p)},f.actor),/insuficiente/);assert.deepEqual(f.s,old);engine.adjustStock(f.s,'Administrador General',f.raw.id,'principal',5,'Reponer insumos','2026-10-05');assert.throws(()=>materialReservations.reserveProductionMaterials(f.s,{...input,review:materialReservations.materialReservationReview(p)},f.actor),/nuevamente/);reserveReviewed(f);assert.throws(()=>engine.adjustStock(f.s,'Administrador General',f.raw.id,'principal',-5,'Salida intermedia','2026-10-06'),/reservado/);validateState(f.s)})
test('release preserves proof, requires authorized reason and frees availability before order cancellation',()=>{const f=reservedProductionFixture(),r=reserveReviewed(f),before=structuredClone(r.preview);assert.throws(()=>engine.saveMaster(f.s,'production',{...f.s.masters.production.find(o=>o.id===f.order.id),status:'Cancelada'},'Producción'),/Liberá/);for(const [date,reason,actor] of [['2026-10-04','Motivo',f.actor],['2026-10-06','',f.actor],['2026-10-06','Motivo',{...f.actor,role:'Depósito'}]]){const old=structuredClone(f.s);assert.throws(()=>materialReservations.releaseProductionMaterials(f.s,r.id,date,reason,actor));assert.deepEqual(f.s,old)}materialReservations.releaseProductionMaterials(f.s,r.id,'2026-10-06','Orden cancelada antes de iniciar.',f.actor);assert.equal(materialReservations.materialAvailable(f.s,f.raw.id,'principal','2026-10-06'),40);assert.equal(materialReservations.materialAvailable(f.s,f.raw.id,'principal','2026-10-05'),37);assert.deepEqual(r.preview,before);engine.saveMaster(f.s,'production',{...f.s.masters.production.find(o=>o.id===f.order.id),status:'Cancelada'},'Producción');validateState(f.s)})
test('finishing a reserved order consumes its own reservation exactly once and preserves other reserved orders',()=>{const f=reservedProductionFixture(),r=reserveReviewed(f);const rival={...f.order,id:'rival-reserved-order',name:'Otro lote reservado'};engine.saveMaster(f.s,'production',rival,'Producción');engine.saveMaster(f.s,'materials',{id:'rival-material',name:'Tela de otro lote',orderId:rival.id,productId:f.raw.id,depositId:'principal',quantity:36,unit:f.raw.unit},'Producción');prepareProduction(f.s,rival.id,f.actor);reserveReviewed(f,{orderId:rival.id});for(const op of f.plan.operations){productionStep(f.s,f.order.id,op.id,'iniciar','2026-10-05',undefined,f.actor);productionStep(f.s,f.order.id,op.id,'completar','2026-10-05',1,f.actor)}const original=structuredClone(r.preview);finishProduction(f.s,f.order.id,'principal','2026-10-05',f.actor.role,f.actor.name);assert.equal(r.release.kind,'Consumida');assert.equal(r.release.by,f.actor.name);assert.equal(engine.stock(f.s,f.raw.id,'principal'),37);assert.equal(materialReservations.materialAvailable(f.s,f.raw.id,'principal','2026-10-05'),1);assert.ok(materialReservations.activeMaterialReservation(f.s,rival.id));assert.deepEqual(r.preview,original);assert.equal(f.s.stockMoves.filter(m=>m.documentId===f.order.id).length,2);assert.throws(()=>finishProduction(f.s,f.order.id,'principal','2026-10-05',f.actor.role));validateState(JSON.parse(JSON.stringify(f.s)))})
test('a released reservation can be reviewed again while earlier sources survive later ordinary stock movements',()=>{const f=reservedProductionFixture(),first=reserveReviewed(f);materialReservations.releaseProductionMaterials(f.s,first.id,'2026-10-06','Revisar prioridad de lotes.',f.actor);engine.adjustStock(f.s,'Administrador General',f.raw.id,'principal',-10,'Salida antes de nueva reserva','2026-10-07');const second=reserveReviewed(f,{date:'2026-10-07',reason:'Nueva prioridad revisada.'});assert.equal(second.number,'INT-RM-00000002');assert.equal(second.preview.lines[0].physical,30);assert.equal(second.preview.previous[0].release.kind,'Liberada');engine.adjustStock(f.s,'Administrador General',f.raw.id,'principal',-27,'Usar existencias libres','2026-10-08');assert.equal(engine.stock(f.s,f.raw.id,'principal'),3);validateState(JSON.parse(JSON.stringify(f.s)))})
test('reservation backups reject lost source stock, altered requirements, repeated holds and forged release or review',()=>{const f=reservedProductionFixture();reserveReviewed(f);for(const change of [s=>s.productionReservations[0].preview.lines[0].quantity++,s=>s.productionReservations[0].review='incorrecta',s=>s.productionReservations[0].preview.stockPrefixIds.pop(),s=>s.stockMoves[0].quantity--,s=>s.productionReservations.push(structuredClone(s.productionReservations[0])),s=>s.productionReservations[0].release={date:'2026-10-05',reason:'Consumo falso',kind:'Consumida',by:'Alguien',at:new Date().toISOString()},s=>s.masters.production.find(o=>o.id===f.order.id).status='Cancelada']){const copy=structuredClone(f.s);change(copy);assert.throws(()=>validateState(copy))}validateState(f.s)})
test('material reservations keep distinct product and deposit identifiers separate when their names contain colons',()=>{const f=productionFixture();for(const [id,sku,depositId] of [['ingredient:part','REM-L-ONE','shared'],['ingredient','REM-L-TWO','part:shared']]){f.s.products.push({...f.raw,id,sku,name:sku});f.s.masters.deposits.push({id:depositId,name:depositId,branchId:'central',active:true});engine.adjustStock(f.s,'Administrador General',id,depositId,4,'Existencias de ensayo','2026-10-05');engine.saveMaster(f.s,'materials',{id:'material-'+sku,name:sku,orderId:f.order.id,productId:id,depositId,quantity:3,unit:f.raw.unit},'Producción')}f.plan=prepareProduction(f.s,f.order.id,f.actor);f.input={orderId:f.order.id,date:'2026-10-05',reason:'Reservar tres materiales distintos.'};const r=reserveReviewed(f);assert.equal(r.preview.lines.length,3);assert.equal(materialReservations.materialAvailable(f.s,'ingredient:part','shared','2026-10-05'),1);assert.equal(materialReservations.materialAvailable(f.s,'ingredient','part:shared','2026-10-05'),1);for(const op of f.plan.operations){productionStep(f.s,f.order.id,op.id,'iniciar','2026-10-05',undefined,f.actor);productionStep(f.s,f.order.id,op.id,'completar','2026-10-05',1,f.actor)}finishProduction(f.s,f.order.id,'principal','2026-10-05',f.actor.role);validateState(f.s);const wrong=structuredClone(f.s);wrong.stockMoves=wrong.stockMoves.filter(m=>!(m.documentId===f.order.id&&m.productId==='ingredient:part'));wrong.stockMoves.find(m=>m.documentId===f.order.id&&m.productId==='ingredient').quantity=-6;assert.throws(()=>validateState(wrong),/materiales|movimientos/)})

const productionSchedule=require(join(dir,'production-schedule.js'))
function shiftsFixture(){const f=productionFixture();engine.saveMaster(f.s,'workCenters',{...f.s.masters.workCenters[0],shifts:JSON.stringify([{name:'Tarde',startHour:14,endHour:18},{name:'Mañana',startHour:8,endHour:10}])},f.actor.role);return f}
test('split center shifts schedule sequential operations around breaks and preserve sorted calendars without physical changes',()=>{const f=shiftsFixture(),before=structuredClone(f.s),p=prepareProduction(f.s,f.order.id,f.actor);assert.equal(p.scheduleVersion,3);assert.equal(f.s.masters.workCenters[0].hours,6);assert.deepEqual(p.operations.map(o=>o.bookings),[[{date:'2026-10-05',hours:2,startHour:8}],[{date:'2026-10-05',hours:2,startHour:14}],[{date:'2026-10-05',hours:2,startHour:16}]]);assert.deepEqual(p.operations[0].calendar.shifts.map(s=>s.name),['Mañana','Tarde']);for(const key of ['stockMoves','entries','documents'])assert.deepEqual(f.s[key],before[key]);validateState(JSON.parse(JSON.stringify(f.s)))})
test('one operation can span shifts while competing lots consume only unreserved windows',()=>{const f=shiftsFixture();engine.saveMaster(f.s,'routes',{...f.s.masters.routes[0],steps:'Fabricar',hours:5},f.actor.role);const p=prepareProduction(f.s,f.order.id,f.actor);assert.deepEqual(p.operations[0].bookings,[{date:'2026-10-05',hours:2,startHour:8},{date:'2026-10-05',hours:3,startHour:14}]);engine.saveMaster(f.s,'production',{...f.order,id:'split-rival'},f.actor.role);engine.saveMaster(f.s,'materials',{...f.s.masters.materials[0],id:'split-rival-material',orderId:'split-rival'},f.actor.role);const other=prepareProduction(f.s,'split-rival',f.actor);assert.deepEqual(other.operations[0].bookings,[{date:'2026-10-05',hours:1,startHour:17},{date:'2026-10-06',hours:2,startHour:8},{date:'2026-10-06',hours:2,startHour:14}]);validateState(f.s)})
test('split shifts still respect work days and closures and fail without retaining partial reservations',()=>{const f=shiftsFixture();engine.saveMaster(f.s,'workCenters',{...f.s.masters.workCenters[0],nonWorkingDates:'2026-10-05'},f.actor.role);f.s.masters.production[0].end='2026-10-05';const before=structuredClone(f.s);assert.throws(()=>prepareProduction(f.s,f.order.id,f.actor),/capacidad/);assert.deepEqual(f.s,before);f.s.masters.production[0].end='2026-10-06';const p=prepareProduction(f.s,f.order.id,f.actor);assert.ok(p.operations.every(o=>o.bookings.every(b=>b.date==='2026-10-06')));validateState(f.s)})
test('center shifts reject overlaps, empty or repeated names, malformed definitions, partial minutes and overnight windows',()=>{const f=productionFixture();for(const shifts of [[],Array.from({length:9},(_,i)=>({name:'T'+i,startHour:i,endHour:i+1})),[{name:'',startHour:8,endHour:12}],[{name:'Turno',startHour:8,endHour:12},{name:'turno',startHour:14,endHour:18}],[{name:'Mañana',startHour:8,endHour:12},{name:'Tarde',startHour:11,endHour:18}],[{name:'Nocturno',startHour:22,endHour:6}],[{name:'Minutos',startHour:8.001,endHour:12}],[{name:'Largo',startHour:0,endHour:25}],{name:'Objeto'},'incorrecto']){const before=structuredClone(f.s);assert.throws(()=>engine.saveMaster(f.s,'workCenters',{...f.s.masters.workCenters[0],shifts:typeof shifts==='string'?shifts:JSON.stringify(shifts)},f.actor.role));assert.deepEqual(f.s,before)}})
test('center edits cannot insert a break across future bookings even if total capacity stays unchanged',()=>{const f=shiftsFixture(),d=today();f.s.masters.production[0].start=d;f.s.masters.production[0].end=d;f.s.masters.workCenters[0].workDays='1,2,3,4,5,6,7';prepareProduction(f.s,f.order.id,f.actor);const before=structuredClone(f.s);assert.throws(()=>engine.saveMaster(f.s,'workCenters',{...f.s.masters.workCenters[0],shifts:JSON.stringify([{name:'Primero',startHour:8,endHour:9},{name:'Segundo',startHour:10,endHour:15}])},f.actor.role),/reservada/);assert.deepEqual(f.s,before);validateState(f.s)})
test('old planned shifts remain conserved after historical center changes and version two plans retain their format',()=>{const f=shiftsFixture(),p=prepareProduction(f.s,f.order.id,f.actor),old=structuredClone(p);engine.saveMaster(f.s,'workCenters',{...f.s.masters.workCenters[0],shifts:JSON.stringify([{name:'Nueva jornada',startHour:10,endHour:20}])},f.actor.role);assert.deepEqual(p,old);validateState(f.s);const g=productionFixture(),legacy=prepareProduction(g.s,g.order.id,g.actor);assert.equal(legacy.scheduleVersion,2);assert.equal(legacy.operations[0].calendar.shifts,undefined);validateState(g.s)})
test('split shift restore rejects missing intervals, changed totals, break crossings, overlap and unsupported versions',()=>{const f=shiftsFixture();prepareProduction(f.s,f.order.id,f.actor);for(const change of [s=>delete s.productionPlans[0].operations[0].calendar.shifts,s=>s.productionPlans[0].operations[0].calendar.shifts[0].endHour=9,s=>s.productionPlans[0].operations[1].bookings[0].startHour=11,s=>s.productionPlans[0].operations[0].calendar.shifts[1].startHour=9,s=>s.productionPlans[0].dailyHours=7,s=>s.productionPlans[0].scheduleVersion=4,s=>s.masters.workCenters[0].shifts='invalid',s=>s.masters.workCenters[0].hours=7]){const copy=structuredClone(f.s);change(copy);assert.throws(()=>validateState(copy))}validateState(JSON.parse(JSON.stringify(f.s)))})
test('minute shifts conserve exact microhour bookings and a day boundary can be represented without overlap',()=>{const f=productionFixture(),shifts=[{name:'Minuto',startHour:1/60,endHour:2/60},{name:'Fin del día',startHour:23,endHour:24}];engine.saveMaster(f.s,'workCenters',{...f.s.masters.workCenters[0],shifts:JSON.stringify(shifts)},f.actor.role);const exact=productionSchedule.shiftDailyHours(shifts);engine.saveMaster(f.s,'routes',{...f.s.masters.routes[0],steps:'Fabricar',hours:exact},f.actor.role);f.s.masters.production[0].end=f.order.start;const p=prepareProduction(f.s,f.order.id,f.actor);assert.equal(p.operations[0].bookings[0].hours,0.016666);assert.equal(p.operations[0].bookings[1].hours,1);assert.equal(p.operations[0].bookings[1].startHour,23);validateState(f.s)})
test('generic master commands retain separate shift definitions and normalize daily hours before preparing the plan',async()=>{const f=productionFixture();await executeCommand(f.s,f.actor,{type:'master.save',key:'workCenters',item:{...f.s.masters.workCenters[0],hours:1,shifts:JSON.stringify([{name:'Mañana',startHour:8,endHour:12},{name:'Tarde',startHour:14,endHour:18}])}});assert.equal(f.s.masters.workCenters[0].hours,8);const p=prepareProduction(f.s,f.order.id,f.actor);assert.equal(p.scheduleVersion,3);assert.equal(p.operations[0].calendar.shifts.length,2);validateState(f.s)})
test('mixed routes preserve legacy single windows with fractional-hour ends alongside minute-based separate shifts',()=>{const f=multiCenterFixture();engine.saveMaster(f.s,'workCenters',{...f.s.masters.workCenters.find(c=>c.id==='center-cut'),shifts:JSON.stringify([{name:'Corte mañana',startHour:8,endHour:12}])},f.actor.role);engine.saveMaster(f.s,'workCenters',{...f.s.masters.workCenters.find(c=>c.id==='center-sew'),hours:7.123456},f.actor.role);const p=prepareProduction(f.s,f.order.id,f.actor);assert.equal(p.scheduleVersion,3);assert.equal(p.operations[1].calendar.singleWindow,true);assert.equal(p.operations[1].calendar.shifts[0].endHour,16.123456);validateState(JSON.parse(JSON.stringify(f.s)));const copy=structuredClone(f.s);copy.productionPlans[0].operations[0].calendar.singleWindow=true;assert.throws(()=>validateState(copy))})

const cardDisputes=require(join(dir,'card-disputes.js'))
function disputeFixture(settled=false){const f=cardFixture(),actor={userId:'admin',name:'Responsable de tarjetas',role:'Administrador General',permissions:[]};cardDisputes.prepareCardClaimAccounts(f.s,actor);const settlement=settled?engine.settleCards(f.s,f.settlement,'Administración'):undefined;return {...f,actor,settled:settlement,input:{receiptId:f.receipt.id,paymentIndex:0,settlementId:settlement?.id||'',date:today(),reference:'CB-TEST-01',reason:'Notificación sintética de procesadora, reclamo documentado.',amount:40000,claimAccountId:'card-dispute-asset',lossAccountId:'card-dispute-loss',recoveryAccountId:'card-dispute-recovery',treatment:'Crédito cierto documentado',assetConfirmed:true}}}
function reviewedDispute(f,input=f.input){return {...input,review:cardDisputes.cardDisputeReview(cardDisputes.previewCardDispute(f.s,input))}}
function reviewedResolution(f,id,outcome,amount,reference='RES-01'){const input={disputeId:id,date:today(),reference,reason:'Respuesta y evidencia de la procesadora revisadas.',amount,outcome};return {...input,review:cardDisputes.cardDisputeReview(cardDisputes.previewCardResolution(f.s,input))}}
test('pending card chargeback preserves customer receipts, tax, stock and treasury while excluding the disputed amount from settlement',()=>{const f=disputeFixture(),before=structuredClone(f.s),r=cardDisputes.registerCardDispute(f.s,reviewedDispute(f),f.actor);assert.equal(r.number,'INT-TC-00000001');assert.equal(r.responsible,f.actor.name);assert.equal(cardDisputes.cardClaimRemaining(f.s,r.id),40000);assert.equal(engine.pendingCardPayments(f.s)[0].remaining,60000);assert.equal(engine.pendingCardPayments(f.s)[0].disputed,40000);for(const key of ['documents','stockMoves','treasuryMoves'])assert.deepEqual(f.s[key],before[key]);assert.equal(f.s.entries.at(-1).lines[0].debit,40000);const snapshot=structuredClone(f.s);assert.throws(()=>engine.settleCards(f.s,{...f.settlement,fee:0,withholdings:[],items:[{...f.settlement.items[0],amount:60001}]},'Administración'),/supera/);assert.deepEqual(f.s,snapshot);engine.settleCards(f.s,{...f.settlement,fee:0,withholdings:[],items:[{...f.settlement.items[0],amount:60000}]},'Administración');validateState(JSON.parse(JSON.stringify(f.s)))})
test('chargeback from a settled coupon debits the conserved bank and partial refund plus loss close the claim without duplicating tax or fees',()=>{const f=disputeFixture(true),before=structuredClone(f.s),r=cardDisputes.registerCardDispute(f.s,reviewedDispute(f),f.actor);assert.equal(f.s.treasuryMoves.reduce((n,m)=>n+m.amount,0),55000);cardDisputes.resolveCardDispute(f.s,reviewedResolution(f,r.id,'Reintegrado',25000),f.actor);assert.equal(cardDisputes.cardClaimRemaining(f.s,r.id),15000);cardDisputes.resolveCardDispute(f.s,reviewedResolution(f,r.id,'Pérdida',15000,'RES-02'),f.actor);assert.equal(cardDisputes.cardClaimRemaining(f.s,r.id),0);assert.equal(f.s.treasuryMoves.reduce((n,m)=>n+m.amount,0),80000);assert.deepEqual(f.s.documents,before.documents);assert.deepEqual(f.s.cardSettlements,before.cardSettlements);assert.deepEqual(f.s.stockMoves,before.stockMoves);assert.equal(engine.partyBalance(f.s,f.receipt.partyId),engine.partyBalance(before,f.receipt.partyId));validateState(f.s);assert.equal(f.s.entries.filter(e=>e.cardDisputeRecordId).length,3)})
test('accepted pending claim restores coupon availability while a recognized loss permanently consumes its portion',()=>{const f=disputeFixture(),r=cardDisputes.registerCardDispute(f.s,reviewedDispute(f),f.actor);cardDisputes.resolveCardDispute(f.s,reviewedResolution(f,r.id,'Reintegrado',10000),f.actor);cardDisputes.resolveCardDispute(f.s,reviewedResolution(f,r.id,'Pérdida',30000,'LOSS-01'),f.actor);assert.equal(engine.pendingCardPayments(f.s)[0].remaining,70000);assert.equal(f.s.treasuryMoves.length,0);assert.equal(cardDisputes.cardClaimRemaining(f.s,r.id),0);validateState(f.s)})
test('card dispute rejects excessive, repeated, unauthorized, stale, malformed and incompatible account requests without mutation',()=>{const f=disputeFixture(),before=structuredClone(f.s);for(const change of [{assetConfirmed:false},{treatment:'otro'},{amount:0},{amount:100001},{amount:1.1},{settlementId:undefined},{settlementId:'unknown'},{reference:''},{claimAccountId:f.s.settings.accountMap.cardReceivables},{claimAccountId:'5.1'},{lossAccountId:'1.1.1'},{date:'2026-02-30'}]){assert.throws(()=>cardDisputes.registerCardDispute(f.s,reviewedDispute(f,{...f.input,...change}),f.actor));assert.deepEqual(f.s,before)}assert.throws(()=>cardDisputes.registerCardDispute(f.s,reviewedDispute(f),{...f.actor,role:'Depósito'}),/perfil/);assert.deepEqual(f.s,before);const stale=reviewedDispute(f);engine.settleCards(f.s,{...f.settlement,items:[{...f.settlement.items[0],amount:10000}],fee:0,withholdings:[]},'Administración');const after=structuredClone(f.s);assert.throws(()=>cardDisputes.registerCardDispute(f.s,stale,f.actor),/revisión/);assert.deepEqual(f.s,after);cardDisputes.registerCardDispute(f.s,reviewedDispute(f),f.actor);assert.throws(()=>cardDisputes.registerCardDispute(f.s,reviewedDispute(f),f.actor),/referencia/);validateState(f.s)})
