test('a recovered card refund can be charged again only up to its restored source and a distinct processor reference',()=>{const f=disputeFixture(true),first=cardDisputes.registerCardDispute(f.s,reviewedDispute(f),f.actor);cardDisputes.resolveCardDispute(f.s,reviewedResolution(f,first.id,'Reintegrado',40000),f.actor);const input={...f.input,reference:'CB-NEW-02',amount:100000};cardDisputes.registerCardDispute(f.s,reviewedDispute(f,input),f.actor);assert.throws(()=>cardDisputes.previewCardDispute(f.s,{...f.input,reference:'CB-NEW-03',amount:1}),/supera/);validateState(f.s)})
test('card dispute restore protects original receipt, settlement prefix, review, accounts, journal and bank amounts and refuses orphan entries',()=>{const f=disputeFixture(true);const r=cardDisputes.registerCardDispute(f.s,reviewedDispute(f),f.actor);cardDisputes.resolveCardDispute(f.s,reviewedResolution(f,r.id,'Pérdida',10000),f.actor);for(const change of [s=>s.cardDisputes[0].preview.input.amount++,s=>s.cardDisputes[0].review='alterada',s=>s.cardDisputes[0].sequence=3,s=>s.cardDisputes[0].preview.settlementPrefixIds=[],s=>s.cardSettlements[0].reference='cambiada',s=>s.documents.find(d=>d.id===f.receipt.id).observations='otra',s=>s.entries.find(e=>e.id===r.entryId).lines[0].debit++,s=>s.treasuryMoves.find(m=>m.id===r.treasuryMoveId).amount--,s=>s.cardDisputes=[],s=>s.cardDisputes[1].preview.input.outcome='Reintegrado']){const copy=structuredClone(f.s);change(copy);assert.throws(()=>validateState(copy))}validateState(JSON.parse(JSON.stringify(f.s)))})
test('card claims survive later account and party renames, keep both historical source allocation and recognized tax, and reject overconsumed pending backups',()=>{const f=disputeFixture(),r=cardDisputes.registerCardDispute(f.s,reviewedDispute(f),f.actor);f.s.masters.accounts.find(a=>a.id==='card-dispute-asset').name='Reclamos renombrados';f.s.parties.find(p=>p.id===f.receipt.partyId).name='Cliente renombrado';cardDisputes.resolveCardDispute(f.s,reviewedResolution(f,r.id,'Pérdida',40000),f.actor);validateState(f.s);engine.settleCards(f.s,{...f.settlement,fee:0,withholdings:[],items:[{...f.settlement.items[0],amount:60000}]},'Administración');const wrong=structuredClone(f.s);wrong.cardSettlements[0].items[0].amount=60001;wrong.cardSettlements[0].gross=60001;wrong.cardSettlements[0].net=60001;assert.throws(()=>validateState(wrong),/apartado/);validateState(f.s)})
