const {accountsAging,agingBuckets}=require(join(dir,'accounts-aging.js'))
function agingFixture(){
 const s=fixture();s.documents=[];s.entries=[];s.treasuryMoves=[]
 const party=s.parties.find(p=>p.side==='cliente'),base=input(s,'saldo',{date:'2026-01-01',letter:'X',lines:[],total:10000})
 const add=(id,kind,total,due,more={})=>{const d={...base,id,number:id,kind,net:total,vat:0,total,due,allocations:[],...more};s.documents.push(d);return d}
 return {s,party,add}
}
test('aging classifies exact day boundaries including today, future, missing due and leap days without mutating sources',()=>{
 const {s,add}=agingFixture(),date='2026-10-14'
 for(const [id,due] of [['future','2026-10-15'],['today',date],['one','2026-10-13'],['thirty','2026-09-14'],['thirtyone','2026-09-13'],['sixty','2026-08-15'],['sixtyone','2026-08-14'],['ninety','2026-07-16'],['ninetyone','2026-07-15'],['unknown','']])add(id,'saldo',100,due)
 const before=structuredClone(s),r=accountsAging(s,date)
 assert.deepEqual(r.groups[0].buckets,[200,200,200,200,100,100]);assert.equal(r.overdue,700);assert.equal(r.balance,1000);assert.equal(r.difference,0);assert.deepEqual(s,before)
 const leap=agingFixture();leap.add('leap','saldo',100,'2024-02-28',{date:'2024-01-01'});assert.equal(accountsAging(leap.s,'2024-03-01').items[0].days,2)
})

test('aging applies only cancellations issued by the cutoff and preserves unapplied credits without FIFO',()=>{
 const {s,add}=agingFixture(),invoice=add('invoice','factura',10000,'2026-09-01')
 add('partial','cobro',4000,'2026-10-01',{date:'2026-10-01',allocations:[{documentId:invoice.id,amount:3000}]})
 add('future-payment','cobro',7000,'2026-10-20',{date:'2026-10-20',allocations:[{documentId:invoice.id,amount:7000}]})
 let r=accountsAging(s,'2026-10-14');assert.equal(r.pending,7000);assert.equal(r.overdue,7000);assert.equal(r.unapplied,1000);assert.equal(r.balance,6000)
 assert.equal(r.items.find(i=>i.id==='invoice').applied,3000);assert.deepEqual(r.items.find(i=>i.id==='invoice').applications,['partial'])
 r=accountsAging(s,'2026-10-20');assert.equal(r.pending,0);assert.equal(r.unapplied,1000);assert.equal(r.balance,-1000)
})
test('aging keeps applications to future charges as unallocated credit until the charge enters the cutoff',()=>{
 const {s,add}=agingFixture(),invoice=add('future-invoice','factura',10000,'2026-10-20',{date:'2026-10-20'})
 add('advance','cobro',4000,'2026-10-01',{date:'2026-10-01',allocations:[{documentId:invoice.id,amount:4000}]})
 let r=accountsAging(s,'2026-10-14');assert.equal(r.pending,0);assert.equal(r.unapplied,4000);assert.equal(r.balance,-4000)
 r=accountsAging(s,'2026-10-20');assert.equal(r.pending,6000);assert.equal(r.unapplied,0);assert.equal(r.balance,6000)
})
test('aging reconciles credit notes, negative opening balances, supplier payments and branches independently',()=>{
 const {s,add,party}=agingFixture(),supplier=s.parties.find(p=>p.side==='proveedor'),invoice=add('sale','factura',10000,'2026-08-01')
 add('note','credito',2500,'2026-10-01',{allocations:[{documentId:invoice.id,amount:2500}]});add('credit-opening','saldo',-500,'')
 add('other-branch','saldo',3000,'2026-09-01',{branchId:'other'})
 const purchase=add('purchase','factura',8000,'2026-09-01',{side:'proveedor',partyId:supplier.id})
 add('payment','pago',2000,'2026-10-01',{side:'proveedor',partyId:supplier.id,allocations:[{documentId:purchase.id,amount:2000}]})
 const all=accountsAging(s,'2026-10-14');assert.equal(all.groups.length,3);assert.equal(all.pending,16500);assert.equal(all.unapplied,500);assert.equal(all.balance,16000);assert.equal(all.difference,0)
 const client=accountsAging(s,'2026-10-14','central','cliente',party.id);assert.equal(client.balance,7000);assert.equal(client.pending,7500);assert.equal(client.unapplied,500)
 assert.equal(accountsAging(s,'2026-10-14','central','proveedor').balance,6000)
})
