function applyReviewed(f,patch={}){const input={...f.input,...patch},p=creditApplications.previewAccountApplication(f.s,input);return creditApplications.applyAccountCredit(f.s,{...input,review:creditApplications.applicationReview(p)},f.actor)}
function reverseReviewed(f,r,patch={}){const input={applicationId:r.id,date:'2026-10-15',reference:'REV-01',reason:'Se revisó la asignación de comprobantes.',...patch},p=creditApplications.previewApplicationReversal(f.s,input);return creditApplications.reverseAccountApplication(f.s,{...input,review:creditApplications.applicationReview(p)},f.actor)}
