test('IVA sales ledger rejects missing revenue proof, invalid manual links and corrupted saved sources even if the supplied review is rewritten',()=>{const f=salesLedgerFixture();for(const patch of [{manual:[{...f.adjustment,entryId:f.settlement.entryId}]},{manual:[f.adjustment,f.adjustment]},{manual:[{...f.adjustment,reference:''}]},{manual:[{...f.adjustment,reason:''}]}])assert.throws(()=>vatSalesLedgerModel.previewVatSalesLedger(f.state,{...f.input,...patch}));const noEntry=structuredClone(f.state);noEntry.entries=noEntry.entries.filter(e=>e.id!==f.settlement.entryId);assert.throws(()=>vatSalesLedgerModel.previewVatSalesLedger(noEntry,f.input),/ingreso devengado/);vatSalesLedgerModel.preserveVatSalesLedger(f.state,reviewedSalesLedger(f,{manual:[f.adjustment]}),f.actor);for(const change of [s=>s.vatSalesLedger[0].preview.totals.book++,s=>s.vatSalesLedger[0].preview.origins[0].includedInMonth=true,s=>s.vatSalesLedger[0].preview.source.entryIds.reverse(),s=>s.vatSalesLedger[0].preview.revenues[0].entry.lines[0].debit++,s=>s.vatSalesLedger[0].number='INT-IDV-00000002',s=>s.vatSalesLedger=null]){const s=structuredClone(f.state);change(s);if(s.vatSalesLedger?.[0])s.vatSalesLedger[0].review=vatSalesLedgerModel.vatSalesLedgerReview(s.vatSalesLedger[0].preview);assert.throws(()=>validateState(s))}})
test('IVA sales ledger command requires its own accounting permission and never creates journals or changes fiscal files',async()=>{const f=salesLedgerFixture(),input=reviewedSalesLedger(f,{manual:[f.adjustment]}),before=structuredClone(f.state),file=vatSalesModel.vatSalesFiles(f.preparation);for(const permissions of [[],['/finanzas/impuestos'],['/reportes/impositivos'],['/contabilidad/conciliacion-iva']])await assert.rejects(()=>executeCommand(f.state,{...f.actor,role:'Personalizado',permissions},{type:'vat.sales-ledger',preparation:input}),/permiso/);assert.deepEqual(f.state,before);const result=await executeCommand(f.state,{...f.actor,role:'Personalizado',permissions:[vatSalesLedgerModel.vatSalesLedgerPath]},{type:'vat.sales-ledger',preparation:input});assert.equal(result.detail,'INT-IDV-00000001');for(const key of ['documents','entries','stockMoves','treasuryMoves','vatSales'])assert.deepEqual(f.state[key],before[key]);assert.deepEqual(vatSalesModel.vatSalesFiles(f.preparation),file);validateState(JSON.parse(JSON.stringify(f.state)))})
test('IVA sales ledger prevents reusing a late manual correction across distinct fiscal months and rejects an unfinished source month',()=>{const f=salesLedgerFixture(),august=f.post({date:'2026-08-05',due:'2026-08-05',lines:[f.line('21',10000)]});f.authorize(august);const augustInput={...f.preparation.preview.input,period:'2026-08',previousId:'',reference:'VENTAS-AGOSTO'},authorizations=f.authorizations.filter(a=>a.request.detail.CbteFch.startsWith('202608')),p=vatSalesModel.previewVatSales(f.state,augustInput,authorizations),source=vatSalesModel.preserveVatSales(f.state,{...augustInput,review:vatSalesModel.vatSalesReview(p)},authorizations,f.actor),firstInput={...f.input,sourceId:source.id,manual:[f.adjustment],reference:'AGOSTO-CON-AJUSTE-POSTERIOR'},first=vatSalesLedgerModel.previewVatSalesLedger(f.state,firstInput);vatSalesLedgerModel.preserveVatSalesLedger(f.state,{...firstInput,review:vatSalesLedgerModel.vatSalesLedgerReview(first)},f.actor);assert.throws(()=>vatSalesLedgerModel.previewVatSalesLedger(f.state,{...f.input,manual:[f.adjustment]}),/otro mes/);const october=f.post({date:'2026-10-05',due:'2026-10-05',lines:[f.line('21',100)]});f.authorize(october);const octoberInput={...augustInput,period:'2026-10',reference:'VENTAS-OCTUBRE'},octoberAuth=f.authorizations.filter(a=>a.request.detail.CbteFch.startsWith('202610')),op=vatSalesModel.previewVatSales(f.state,octoberInput,octoberAuth),os=vatSalesModel.preserveVatSales(f.state,{...octoberInput,review:vatSalesModel.vatSalesReview(op)},octoberAuth,f.actor);assert.throws(()=>vatSalesLedgerModel.previewVatSalesLedger(f.state,{...f.input,sourceId:os.id,asOf:'2026-10-17'}),/mes terminado/);validateState(JSON.parse(JSON.stringify(f.state)))})
after(()=>rmSync(dir,{recursive:true,force:true}))
